/**
 * حملة سيناريوهات خفية — تسجيل / توثيق / مقر / منتدى / هوية بعد إعادة التسجيل.
 * ليست اختبار اختراق حي؛ عقود ضد الرجوع للثغرات التي ظهرت في الجلسات السابقة.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { pickForumTileProfilePaintState } from '@/app/components/lawyer/dashboard/forumProfile/pickForumTileProfilePaintState';
import { resolveHqDirectoryKycStatus } from '@/app/domain/admin/hqUserPresence';
import {
    canUseForumNetworkFeatures,
    resolveLawyerVerificationStatus,
} from '@/app/services/auth/lawyerAccountStatus';
import {
    LAWYER_VERIFICATION_HQ_RECEIVED_AR,
    LAWYER_VERIFICATION_HQ_UNREACHABLE_AR,
} from '@/app/services/auth/lawyerVerificationRemote';
import { hqVerificationHasIdentityPair } from '@/app/api/auth/lawyer-verification/hqVerificationQueueRecord';
import {
    getUserIdentityUiState,
    publishUserIdentityUiState,
    resetUserIdentityUiStateForTests,
} from '@/app/services/profile/userIdentityUiState';
import { setLiveAuthUserId } from '@/app/utils/liveAuthUserId';
import {
    isLawyerProfileBootWarmPending,
    setLawyerProfileBootWarmPending,
} from '@/app/services/profile/profileBootWarmPending';
import {
    resetLawyerVerificationStoreForTests,
    writeLawyerVerificationPending,
} from '@/app/services/auth/lawyerVerificationStore';

vi.mock('@/app/services/profile/lawyerProfileLocalRead', () => ({
    readLocalProfileSync: vi.fn(() => null),
    isLawyerProfileLocalUnread: vi.fn(() => false),
    lawyerProfileLocalRecordExists: vi.fn(() => false),
}));

vi.mock('@/app/utils/authStorage', () => ({
    readPersistedSupabaseAuth: vi.fn(() => ({ user: null, session: null })),
    readDevMockUser: vi.fn(() => null),
}));

const GAP = '49d464e5-bd75-4105-bdb9-fd18fc647854';

describe('auth onboarding hidden-gap scenarios', () => {
    beforeEach(() => {
        resetUserIdentityUiStateForTests();
        resetLawyerVerificationStoreForTests();
        setLawyerProfileBootWarmPending(false);
        setLiveAuthUserId(null);
    });

    it('حساب بلا اسم يستقر بعد التسخين ولا يبقى aria-busy إلى الأبد', () => {
        const state = pickForumTileProfilePaintState(
            'lawyer-new-nameless',
            { accountType: 'lawyer', verificationStatus: 'pending' },
            '',
            '',
            '',
        );
        expect(state.displayName).toBe('');
        expect(state.isLoaded).toBe(true);
    });

    it('تبديل الحساب يصفّر هوية الواجهة العالقة من الحساب السابق', async () => {
        setLiveAuthUserId(null);
        publishUserIdentityUiState({
            userId: 'lawyer-a',
            displayName: 'أحمد مهدي',
            avatarUrl: '',
            profileInitial: 'أ',
            isLoaded: true,
        });
        setLiveAuthUserId('lawyer-a');
        expect(getUserIdentityUiState('lawyer-a')?.displayName).toBe('أحمد مهدي');
        setLawyerProfileBootWarmPending(true);
        setLiveAuthUserId('lawyer-b');
        await vi.waitFor(() => {
            expect(getUserIdentityUiState('lawyer-a')).toBeNull();
            expect(isLawyerProfileBootWarmPending()).toBe(false);
        });
    });

    it('بلا صف KV: المنتدى العميل قد يرى اعتماد app_metadata بينما الدليل لا يخفيه كـ بلا طلب', () => {
        expect(resolveLawyerVerificationStatus(GAP, {}, { verification_status: 'active' })).toBe(
            'active',
        );
        expect(canUseForumNetworkFeatures(GAP, {}, { verification_status: 'active' })).toBe(true);
        expect(resolveHqDirectoryKycStatus(undefined, true, 'active')).toBe('active');
        expect(resolveHqDirectoryKycStatus(undefined, true, 'none')).toBe('none');
        expect(resolveHqDirectoryKycStatus(undefined, true, 'pending')).toBe('pending');
    });

    it('قبول الهوية يتطلب الوجه والظهر — الصف المزروع بلا وثائق لا يُعتمد', () => {
        expect(hqVerificationHasIdentityPair({ hasIdFront: false, hasIdBack: false })).toBe(false);
        expect(hqVerificationHasIdentityPair({ hasIdFront: true, hasIdBack: false })).toBe(false);
        expect(hqVerificationHasIdentityPair({ hasIdFront: true, hasIdBack: true })).toBe(true);
    });

    it('رسائل الإكمال لا تتطابق: نجاح المقر ≠ فشل الإرسال', () => {
        expect(LAWYER_VERIFICATION_HQ_RECEIVED_AR).toMatch(/وصل طلبك إلى الإدارة/);
        expect(LAWYER_VERIFICATION_HQ_UNREACHABLE_AR).not.toMatch(/وصل طلبك إلى الإدارة/);
        expect(LAWYER_VERIFICATION_HQ_UNREACHABLE_AR).toMatch(/لم تستلم الطلب/);
    });

    it('user_metadata=active لا يفتح الواجهة — app_metadata فقط', () => {
        expect(
            resolveLawyerVerificationStatus(GAP, { verificationStatus: 'active' }, {}),
        ).toBe('pending');
        expect(
            resolveLawyerVerificationStatus(GAP, { verificationStatus: 'active' }, {
                verification_status: 'active',
            }),
        ).toBe('active');
    });

    it('إعادة الرفع المحلي pending تتقدّم على app_metadata rejected البالي', () => {
        writeLawyerVerificationPending(GAP, {
            email: 'a@b.com',
            fullName: 'علي محمد حسن',
            familyName: 'العلي',
            phone: '07719876543',
            governorate: 'بغداد',
            lawyerBarRoom: 'غرفة محاميي بغداد',
            idFrontDataUrl: null,
            idBackDataUrl: null,
            faceSelfieDataUrl: null,
            faceAssistOptedIn: false,
        });
        expect(
            resolveLawyerVerificationStatus(GAP, {}, { verification_status: 'rejected' }),
        ).toBe('pending');
    });
});

import type { ExecutionFile } from '@/app/types/execution';
import { asUnknownRecord } from '@/app/utils/asUnknownRecord';
import {
    filterTimelineEventsForInabaDossier,
    isInabaSubFileId,
} from '@/app/domain/execution/dossier/ExecutionDossierScope';
import {
    readExecutionDossierByIdFromCache,
    readScopedExecutionDossierFromCache,
} from '@/app/infrastructure/execution/ExecutionDossierRepository';
import { normalizeExecutionFileArrays } from './normalizeExecutionFileArrays';
import { recordHasPartyDeathMarkers } from '@/app/utils/partyDeathPersistGuards';
import { maritalFurnitureFinancialContentSignature } from '@/app/utils/maritalFurniture';
import {
    PERSONAL_COERCIVE_PERSIST_SIGNATURE_KEYS,
} from '@/app/components/lawyer/execution/coerciveStackUtils';

type ExecutionFileLegacyShape = ExecutionFile & {
    parentId?: string;
    parentFileId?: string;
    parties?: unknown[];
    creditor_party_death_case?: unknown;
    debtor_party_death_case?: unknown;
    party_death_case?: unknown;
    is_creditor_deceased?: boolean;
    is_debtor_deceased?: boolean;
    guarantor_followup?: unknown;
    procedural_guarantee?: unknown;
    hasGuarantor?: boolean;
    seizedProperties?: unknown;
    seizedMovables?: unknown;
    thirdPartySeizures?: unknown;
    realEstateSeizureAssets?: unknown;
    other_party_request_tracks?: unknown;
    other_party_actions_log?: unknown;
};

function parseUpdatedAt(file: { updatedAt?: unknown; createdAt?: unknown } | null): number {
    if (!file) return 0;
    const raw = file.updatedAt ?? file.createdAt;
    const parsed = raw ? Date.parse(String(raw)) : 0;
    return Number.isFinite(parsed) ? parsed : 0;
}

/** عند فوز فهرس القائمة على blob، لا تُفقد حقول السند/الحكم المحفوظة في المخزن */
function fillMissingInstrumentFields(
    target: ExecutionFileLegacyShape,
    source: ExecutionFileLegacyShape | null | undefined,
): ExecutionFileLegacyShape {
    if (!source) return target;
    const keys = [
        'docType',
        'docNumber',
        'judgmentDate',
        'claimType',
        'classification',
        'executionType',
        'chequeNumber',
        'chequeIssueDate',
        'shariaDeedNumber',
        'shariaIssueDate',
        'shariaRegisterNumber',
        'shariaIssuingCourt',
    ] as const;
    let next: ExecutionFileLegacyShape | null = null;
    for (const key of keys) {
        const fromTarget = String(asUnknownRecord(target)[key] ?? '').trim();
        const fromSource = String(asUnknownRecord(source)[key] ?? '').trim();
        if (!fromTarget && fromSource) {
            if (!next) next = { ...target };
            asUnknownRecord(next)[key] = asUnknownRecord(source)[key];
        }
    }
    return next ?? target;
}

export type BuildExecutionViewDataInput = {
    currentFile: ExecutionFile | null;
    file: ExecutionFile | null | undefined;
    executionId: string | undefined;
    executionStorageTick: number;
    preferStoreCurrentFile?: boolean;
};

export function buildExecutionViewData({
    currentFile,
    file,
    executionId,
    executionStorageTick,
    preferStoreCurrentFile = false,
}: BuildExecutionViewDataInput): ExecutionFile | null {
    const storeId = String(currentFile?.id ?? '').trim();
    const propId = String(file?.id ?? executionId ?? '').trim();
    const inDelegationView = preferStoreCurrentFile || isInabaSubFileId(storeId);
    const fileId = inDelegationView && storeId ? storeId : propId;

    let resolved: ExecutionFileLegacyShape | null = null;

    if (inDelegationView && currentFile) {
        resolved = currentFile as ExecutionFileLegacyShape;
    } else if (file && currentFile && String(currentFile.id ?? '').trim() === String(file.id ?? '').trim()) {
        // بعد persist المحلي يكون currentFile أحدث من prop الأب حتى يصل onUpdate.
        const storeTs = parseUpdatedAt(currentFile);
        const fileTs = parseUpdatedAt(file);
        resolved = (
            Number.isFinite(storeTs) && storeTs > fileTs ? currentFile : file
        ) as ExecutionFileLegacyShape;
    } else if (file) {
        resolved = file as ExecutionFileLegacyShape;
    } else if (currentFile) {
        resolved = currentFile as ExecutionFileLegacyShape;
    }

    const parentFromInabaId =
        isInabaSubFileId(storeId) && storeId.includes(':') ? storeId.slice(storeId.indexOf(':') + 1).trim() : '';
    const parentLink = String(
        resolved?.parentId ||
            resolved?.parentFileId ||
            parentFromInabaId ||
            '',
    ).trim();

    const stored = readScopedExecutionDossierFromCache({
        fileId,
        storeId,
        parentLink,
        inDelegationView,
    }) as ExecutionFileLegacyShape | null;

    if (inDelegationView && isInabaSubFileId(storeId) && resolved) {
        const rawTimeline = Array.isArray(stored?.timelineEvents)
            ? stored.timelineEvents
            : Array.isArray(resolved.timelineEvents)
              ? resolved.timelineEvents
              : [];
        const inabaTimeline = filterTimelineEventsForInabaDossier(rawTimeline, storeId);
        resolved = {
            ...resolved,
            fileNumber: String(stored?.fileNumber ?? resolved.fileNumber ?? '').trim(),
            fileYear: String(stored?.fileYear ?? resolved.fileYear ?? '').trim(),
            timelineEvents: inabaTimeline,
            creditors: resolved.creditors?.length
                ? resolved.creditors
                : stored?.creditors?.length
                  ? stored.creditors
                  : resolved.creditors,
            debtors: resolved.debtors?.length
                ? resolved.debtors
                : stored?.debtors?.length
                  ? stored.debtors
                  : resolved.debtors,
            parties: resolved.parties?.length
                ? resolved.parties
                : stored?.parties?.length
                  ? stored.parties
                  : resolved.parties,
            party_multiplicity: resolved.party_multiplicity ?? stored?.party_multiplicity,
            creditor_party_death_case: resolved.creditor_party_death_case ?? stored?.creditor_party_death_case,
            debtor_party_death_case: resolved.debtor_party_death_case ?? stored?.debtor_party_death_case,
            party_death_case: resolved.party_death_case ?? stored?.party_death_case,
            guarantor_followup: stored?.guarantor_followup ?? resolved.guarantor_followup,
            procedural_guarantee: stored?.procedural_guarantee ?? resolved.procedural_guarantee,
            hasGuarantor: stored?.hasGuarantor ?? resolved.hasGuarantor,
        } as ExecutionFileLegacyShape;
    } else if (resolved && stored) {
        const fileUpdatedAt = parseUpdatedAt(resolved);
        const storedUpdatedAt = parseUpdatedAt(stored);
        const resolvedDeath = recordHasPartyDeathMarkers(
            resolved as unknown as Record<string, unknown>,
        );
        const storedDeath = recordHasPartyDeathMarkers(
            stored as unknown as Record<string, unknown>,
        );
        if (Number.isFinite(storedUpdatedAt) && storedUpdatedAt > fileUpdatedAt) {
            resolved = stored;
        } else if (
            storedDeath &&
            !resolvedDeath &&
            Number.isFinite(storedUpdatedAt) &&
            storedUpdatedAt >= fileUpdatedAt
        ) {
            // حتى عند tick=0: لا تتجاهل وفاة في الـ blob لصالح فهرس/prop بلا وفاة.
            resolved = stored;
        } else if (
            // لا تستبدل تعديلاً أحدث في المتجر/الواجهة بنسخة كاش أقدم بعد persist محلي.
            executionStorageTick > 0 &&
            Number.isFinite(storedUpdatedAt) &&
            storedUpdatedAt >= fileUpdatedAt
        ) {
            try {
                const pairs: [unknown, unknown][] = [
                    [resolved.is_creditor_deceased ?? null, stored.is_creditor_deceased ?? null],
                    [resolved.is_debtor_deceased ?? null, stored.is_debtor_deceased ?? null],
                    [resolved.creditor_party_death_case ?? null, stored.creditor_party_death_case ?? null],
                    [resolved.debtor_party_death_case ?? null, stored.debtor_party_death_case ?? null],
                    [resolved.party_death_case ?? null, stored.party_death_case ?? null],
                    [resolved.party_multiplicity ?? null, stored.party_multiplicity ?? null],
                    [resolved.debtors ?? null, stored.debtors ?? null],
                    [resolved.guarantor_followup ?? null, stored.guarantor_followup ?? null],
                    [resolved.procedural_guarantee ?? null, stored.procedural_guarantee ?? null],
                    [resolved.hasGuarantor ?? null, stored.hasGuarantor ?? null],
                    [resolved.creditors ?? null, stored.creditors ?? null],
                    [resolved.seizedProperties ?? null, stored.seizedProperties ?? null],
                    [resolved.seizedMovables ?? null, stored.seizedMovables ?? null],
                    [resolved.thirdPartySeizures ?? null, stored.thirdPartySeizures ?? null],
                    [resolved.seizedAssets ?? null, stored.seizedAssets ?? null],
                    [resolved.realEstateSeizureAssets ?? null, stored.realEstateSeizureAssets ?? null],
                    [resolved.other_party_request_tracks ?? null, stored.other_party_request_tracks ?? null],
                    [resolved.other_party_actions_log ?? null, stored.other_party_actions_log ?? null],
                    [
                        maritalFurnitureFinancialContentSignature(resolved),
                        maritalFurnitureFinancialContentSignature(stored),
                    ],
                    ...PERSONAL_COERCIVE_PERSIST_SIGNATURE_KEYS.map((key): [unknown, unknown] => [
                        asUnknownRecord(resolved)[key] ?? null,
                        asUnknownRecord(stored)[key] ?? null,
                    ]),
                ];
                for (const [fromFile, fromStore] of pairs) {
                    if (JSON.stringify(fromFile) !== JSON.stringify(fromStore)) {
                        resolved = stored;
                        break;
                    }
                }
            } catch {
                /* ignore */
            }
        }
    } else if (!resolved && stored) {
        resolved = stored;
    }

    if (!resolved && executionId && !inDelegationView) {
        resolved = readExecutionDossierByIdFromCache(executionId);
    }

    if (resolved && stored) {
        resolved = fillMissingInstrumentFields(resolved, stored);
    }

    if (!resolved) return null;
    return normalizeExecutionFileArrays(resolved as ExecutionFile);
}

import { describe, expect, it, beforeEach, afterEach } from 'vitest';
import {
    canonicalFollowupTabForPrefetch,
    normalizeLegacyFollowupTabOnOpen,
    resolveLegacyFollowupTabRuntimeRedirect,
} from '@/app/components/lawyer/ExecutionDashboard/utils/followupLegacyTabNormalization';
import { simulateFollowupModalJourney } from './support/followupModalJourneyHarness';

describe('followupLegacyTabNormalization', () => {
    it('maps financial to seizure route on open', () => {
        expect(normalizeLegacyFollowupTabOnOpen('financial')).toEqual({
            tab: null,
            routeSeizureRequests: true,
        });
    });

    it('maps special to admin on open', () => {
        expect(normalizeLegacyFollowupTabOnOpen('special')).toEqual({
            tab: 'admin',
            routeSeizureRequests: false,
        });
    });

    it('redirects runtime financial to seizure_requests when that tab exists', () => {
        expect(
            resolveLegacyFollowupTabRuntimeRedirect({
                unifiedModalTab: 'financial',
                effectiveFollowupSectionTabOrder: ['personal', 'coercive', 'seizure_requests'],
                hideFollowupCoerciveTab: false,
            }),
        ).toBe('seizure_requests');
    });

    it('canonicalizes prefetch ids', () => {
        expect(canonicalFollowupTabForPrefetch('financial')).toBe('seizure_requests');
        expect(canonicalFollowupTabForPrefetch('special')).toBe('admin');
        expect(canonicalFollowupTabForPrefetch('coercive')).toBe('coercive');
    });
});

describe('followupModalJourneyHarness', () => {
    const storageKey = 'hami-followup-modal:journey-harness-test';

    beforeEach(() => {
        sessionStorage.removeItem(storageKey);
    });

    afterEach(() => {
        sessionStorage.removeItem(storageKey);
    });

    it('open → switch → close → reopen restores persisted tab', () => {
        const journey = simulateFollowupModalJourney(
            {
                claimType: 'استحصال دين مالي',
                isEmployee: false,
                financialCenterTotalIqd: 400_000,
            },
            ['__open__', 'correspondences', '__close__', '__open__'],
            storageKey,
        );

        expect(journey.scenarioTabIds).toContain('personal');
        expect(journey.steps[0].action).toBe('open');
        expect(journey.steps[1]).toMatchObject({
            action: 'switch_tab',
            tab: 'correspondences',
        });
        expect(journey.persistTabAfterClose).toBe('correspondences');

        const reopen = journey.steps[3];
        expect(reopen).toMatchObject({
            action: 'open',
            tab: 'correspondences',
            routeSeizureRequests: false,
        });
    });

    it('legacy financial saved tab routes to seizure on reopen', () => {
        sessionStorage.setItem(storageKey, JSON.stringify({ tab: 'financial' }));
        const journey = simulateFollowupModalJourney(
            {
                claimType: 'استحصال دين مالي',
                isEmployee: false,
                financialCenterTotalIqd: 400_000,
            },
            ['__open__'],
            storageKey,
        );
        expect(journey.steps[0]).toMatchObject({
            action: 'open',
            routeSeizureRequests: true,
        });
        expect(journey.finalTab).toBe('seizure_requests');
    });

    it('deceased scenario hides hidden toggle in journey snapshot', () => {
        const journey = simulateFollowupModalJourney(
            {
                claimType: 'استحصال دين مالي',
                isEmployee: false,
                activeDebtorIsDeceased: true,
                financialCenterTotalIqd: 400_000,
            },
            ['__open__'],
            storageKey,
        );
        expect(journey.hiddenToggleVisible).toBe(false);
    });
});

import type {
    HiddenGuarantorRequestKey,
    HiddenPersonalCoerciveRequestKey,
} from '@/app/components/lawyer/ExecutionDashboard/components/hiddenFollowupRequestsUtils';

/** سطح عرض الإجراء داخل محضر المتابعة */
export type FollowupActionSurface =
    | 'hidden_toggle'
    | 'hidden_personal_coercive'
    | 'hidden_guarantor'
    | 'hidden_break_inventory'
    | 'personal_tab'
    | 'coercive_tab'
    | 'seizure_tab';

export type FollowupRegistryActionId =
    | 'hidden:toggle'
    | 'hidden:break_inventory'
    | `hidden_personal:${HiddenPersonalCoerciveRequestKey}`
    | `hidden_guarantor:${HiddenGuarantorRequestKey}`;

export type FollowupRegistryActionDefinition = {
    id: FollowupRegistryActionId;
    surface: FollowupActionSurface;
    labelAr: string;
    /** مفتاح الكتالوج الأصلي في hiddenFollowupRequestsUtils */
    catalogKey?: HiddenPersonalCoerciveRequestKey | HiddenGuarantorRequestKey;
};

const HIDDEN_PERSONAL_LABELS: Record<HiddenPersonalCoerciveRequestKey, string> = {
    forced_bring_in: 'إحضار جبري',
    travel_ban: 'منع سفر',
    arrest_warrant_investigation: 'مفاتحة التحقيق',
    executive_dossier_presentation: 'عرض الإضبارة',
    executive_detention_judge: 'قرار القاضي',
};

const HIDDEN_GUARANTOR_LABELS: Record<HiddenGuarantorRequestKey, string> = {
    guarantor_request: 'طلب الكفيل',
    guarantor_seizure_salary: 'حجز راتب الكفيل',
    guarantor_seizure_property: 'حجز عقار الكفيل',
    guarantor_seizure_movable: 'حجز منقول الكفيل',
};

/**
 * سجل إجراءات محضر المتابعة — مرجع ثابت للمفاتيح والأسطح.
 * منطق الإظهار يبقى في hiddenFollowupRequestsUtils؛ هذا السجل يوحّد التسمية للمصفوفة والاختبارات.
 */
export const FOLLOWUP_ACTION_REGISTRY: readonly FollowupRegistryActionDefinition[] = [
    { id: 'hidden:toggle', surface: 'hidden_toggle', labelAr: 'الطلبات المخفية' },
    { id: 'hidden:break_inventory', surface: 'hidden_break_inventory', labelAr: 'طلب كسر الأقفال' },
    ...(Object.keys(HIDDEN_PERSONAL_LABELS) as HiddenPersonalCoerciveRequestKey[]).map(
        (key): FollowupRegistryActionDefinition => ({
            id: `hidden_personal:${key}`,
            surface: 'hidden_personal_coercive',
            labelAr: HIDDEN_PERSONAL_LABELS[key],
            catalogKey: key,
        }),
    ),
    ...(Object.keys(HIDDEN_GUARANTOR_LABELS) as HiddenGuarantorRequestKey[]).map(
        (key): FollowupRegistryActionDefinition => ({
            id: `hidden_guarantor:${key}`,
            surface: 'hidden_guarantor',
            labelAr: HIDDEN_GUARANTOR_LABELS[key],
            catalogKey: key,
        }),
    ),
];

export const FOLLOWUP_REGISTRY_ACTION_IDS = FOLLOWUP_ACTION_REGISTRY.map((entry) => entry.id);

export function registryIdForHiddenPersonalKey(
    key: HiddenPersonalCoerciveRequestKey,
): FollowupRegistryActionId {
    return `hidden_personal:${key}`;
}

export function registryIdForHiddenGuarantorKey(key: HiddenGuarantorRequestKey): FollowupRegistryActionId {
    return `hidden_guarantor:${key}`;
}

import type { FollowupScenarioInput } from './followupScenarioResolver';
import { resolveFollowupScenario } from './followupScenarioResolver';
import { resolveFollowupHiddenActions } from './resolveFollowupHiddenActions';
import {
    readFollowupModalPersist,
    resolveFollowupTabOnOpen,
    writeFollowupModalPersist,
} from '@/app/components/lawyer/ExecutionDashboard/utils/followupModalPersistUtils';

export type FollowupModalJourneyStep = {
    action: 'open' | 'switch_tab' | 'close';
    tab?: string;
    routeSeizureRequests?: boolean;
};

export type FollowupModalJourneyResult = {
    scenarioTabIds: string[];
    hiddenToggleVisible: boolean;
    steps: FollowupModalJourneyStep[];
    finalTab: string | null;
    persistTabAfterClose: string | undefined;
};

/**
 * محاكاة open → tab → persist → reopen لسيناريو محضر المتابعة (بدون DOM).
 */
export function simulateFollowupModalJourney(
    input: FollowupScenarioInput,
    journeyTabs: string[],
    storageKey = 'hami-followup-modal:journey-test',
): FollowupModalJourneyResult {
    const scenario = resolveFollowupScenario(input);
    const hidden = resolveFollowupHiddenActions(input);
    const allowedTabOrder = scenario.effectiveSectionTabOrder;

    const steps: FollowupModalJourneyStep[] = [];
    let currentTab: string | null = null;

    for (const requestedTab of journeyTabs) {
        if (requestedTab === '__open__') {
            const open = resolveFollowupTabOnOpen({
                savedTab: readFollowupModalPersist(storageKey).tab,
                allowedTabOrder,
            });
            steps.push({
                action: 'open',
                tab: open.tab,
                routeSeizureRequests: open.routeSeizureRequests,
            });
            currentTab = open.routeSeizureRequests ? 'seizure_requests' : open.tab;
            continue;
        }
        if (requestedTab === '__close__') {
            writeFollowupModalPersist(storageKey, {
                tab: currentTab ?? undefined,
                scroll: 0,
            });
            steps.push({ action: 'close', tab: currentTab });
            currentTab = null;
            continue;
        }
        const resolved = resolveFollowupTabOnOpen({
            explicitTab: requestedTab as never,
            allowedTabOrder,
        });
        steps.push({
            action: 'switch_tab',
            tab: resolved.tab,
            routeSeizureRequests: resolved.routeSeizureRequests,
        });
        currentTab = resolved.routeSeizureRequests ? 'seizure_requests' : resolved.tab;
        if (currentTab) {
            writeFollowupModalPersist(storageKey, { tab: currentTab });
        }
    }

    const persistTabAfterClose = readFollowupModalPersist(storageKey).tab;

    return {
        scenarioTabIds: scenario.effectiveTabIds,
        hiddenToggleVisible: hidden.hiddenToggleVisible,
        steps,
        finalTab: currentTab,
        persistTabAfterClose,
    };
}

