import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { loadInitialLawsuitFilesAsync } from '@/app/domain/lawsuit/lawsuitFilesRepository';
import {
    lawsuitStorageMayHaveUnreadData,
    migrateLawsuitMonolithicToSegmentsIfNeeded,
} from '@/app/domain/lawsuit/lawsuitSegmentStorage';
import { emptyLawsuitLifecycleIndex } from '@/app/domain/lawsuit/lawsuitLifecycleIndex';
import { flushLawsuitWorkspacePersist, resetLawsuitCommitSchedulerForTests } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import { clearLawsuitPendingCreatesForTests } from '@/app/domain/lawsuit/lawsuitPendingCreateStore';

vi.mock('@/app/utils/lawsuitFilesStorage', () => ({
    loadLawsuitFilesRaw: vi.fn(() => []),
    saveLawsuitFilesRaw: vi.fn(),
}));

const file = (id: number): FileData => ({
    id,
    type: 'lawsuit',
    status: 'active',
    caseNo: `2026/ب/${id}`,
    court: 'بداءة الكرخ',
    parties: [],
    history: [],
    notes: [],
    images: [],
    date: '2026-01-01',
});

describe('lawsuit persistence reload safety', () => {
    beforeEach(async () => {
        resetLawsuitCommitSchedulerForTests();
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        await SecureStoreService.waitForAllPendingPersist();
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        clearLawsuitPendingCreatesForTests();
        try {
            SecureStoreService.deleteItemSync('hami_lawsuit_write_journal_v1');
        } catch {
            /* ignore */
        }
        localStorage.removeItem('hami_lawsuit_write_journal_v1');
        vi.clearAllMocks();
    });

    it('lawsuitStorageMayHaveUnreadData true when active key is cold encrypted', async () => {
        await SecureStoreService.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1)]));
        SecureStoreService.clearDecryptedMemoryCache();
        expect(SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)).toBe(true);
        expect(lawsuitStorageMayHaveUnreadData(emptyLawsuitLifecycleIndex())).toBe(true);
    });

    it('migrate does not import monolith while lawsuit segments are still unread', async () => {
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        await SecureStoreService.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([]));
        await SecureStoreService.setItem(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 1, archived: 0, trash: 0 },
            }),
        );
        SecureStoreService.clearDecryptedMemoryCache();
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([file(7)]);

        const boot = migrateLawsuitMonolithicToSegmentsIfNeeded();
        expect(boot.active).toHaveLength(0);
    });

    it('loadInitialLawsuitFilesAsync awaits ensureLawsuitKeysReady before read', async () => {
        const ready = vi
            .spyOn(SecureStoreService, 'ensureLawsuitKeysReady')
            .mockResolvedValue(undefined);
        const fullReady = vi
            .spyOn(SecureStoreService, 'ensurePersistedReady')
            .mockResolvedValue(undefined);
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(3)]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 1, archived: 0, trash: 0 },
            }),
        );

        const loaded = await loadInitialLawsuitFilesAsync();
        expect(ready).toHaveBeenCalled();
        expect(loaded).toHaveLength(1);
        expect(loaded[0]?.id).toBe(3);
        expect(fullReady).toHaveBeenCalled();
        ready.mockRestore();
        fullReady.mockRestore();
    });

    it('flushLawsuitWorkspacePersist waits for lawsuit durable keys', async () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(5)]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 1, archived: 0, trash: 0 },
            }),
        );
        const ok = await flushLawsuitWorkspacePersist();
        expect(ok).toBe(true);
        expect(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)).toBeTruthy();
    });

    it('flushLawsuitWorkspacePersist returns false on timeout without hanging', async () => {
        const pending = new Promise<void>(() => undefined);
        const spy = vi
            .spyOn(SecureStoreService, 'waitForPendingSetItem')
            .mockImplementation(() => pending);
        const ok = await flushLawsuitWorkspacePersist(40);
        expect(ok).toBe(false);
        spy.mockRestore();
    });

    it('commitLawsuitWorkspacePersist verifies active file survives clearDecryptedMemoryCache+warm', async () => {
        const { commitLawsuitWorkspacePersist } = await import(
            '@/app/domain/lawsuit/lawsuitPersistFlush'
        );
        const { persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        const row = file(42);
        persistLawsuitActiveSegment([row]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([row], [], []));

        const commit = await commitLawsuitWorkspacePersist({
            timeoutMs: 5_000,
            requireActiveFileId: 42,
        });
        expect(commit.ok).toBe(true);

        SecureStoreService.clearDecryptedMemoryCache();
        await SecureStoreService.warmKeys([LAWSUIT_FILES_ACTIVE_KEY, LAWSUIT_FILES_INDEX_KEY]);
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        expect(raw).toBeTruthy();
        expect(JSON.parse(raw!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 42 })]),
        );
    });

    it('setItemSync rejects cold empty overwrite on protected lawsuit key', async () => {
        await SecureStoreService.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(2)]));
        SecureStoreService.clearDecryptedMemoryCache();
        const ok = SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        expect(ok).toBe(false);
        await SecureStoreService.warmKeys([LAWSUIT_FILES_ACTIVE_KEY]);
        expect(JSON.parse(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)!)).toHaveLength(1);
    });

    it('applyLawsuitMonolithicMergeToSegments refuses empty wipe over existing segments', async () => {
        const { applyLawsuitMonolithicMergeToSegments, persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } =
            await import('@/app/domain/lawsuit/lawsuitSegmentStorage');
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        persistLawsuitActiveSegment([file(11)]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([file(11)], [], []));

        const result = applyLawsuitMonolithicMergeToSegments([]);
        expect(result.active).toHaveLength(1);
        expect(result.active[0]?.id).toBe(11);
        expect(JSON.parse(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)!)).toHaveLength(1);
    });

    it('writeJsonArray does not empty persistence when setItemSync rejects wipe', async () => {
        const { persistLawsuitActiveSegment } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(8)]));
        const rejected = SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        expect(rejected).toBe(false);
        persistLawsuitActiveSegment([]);
        expect(JSON.parse(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)!)).toHaveLength(1);
    });

    it('commitLawsuitWorkspacePersist verifies active file survives dropMemoryMirrorsForTests (reload sim)', async () => {
        const { commitLawsuitWorkspacePersist } = await import(
            '@/app/domain/lawsuit/lawsuitPersistFlush'
        );
        const { persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        const row = file(99);
        persistLawsuitActiveSegment([row]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([row], [], []));

        const commit = await commitLawsuitWorkspacePersist({
            timeoutMs: 5_000,
            requireActiveFileId: 99,
        });
        expect(commit.ok).toBe(true);

        SecureStoreService.dropMemoryMirrorsForTests([
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_INDEX_KEY,
            LAWSUIT_FILES_STORAGE_KEY,
        ]);
        const fromDisk = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        expect(fromDisk).toBeTruthy();
        expect(JSON.parse(fromDisk!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 99 })]),
        );
        await SecureStoreService.warmKeys([LAWSUIT_FILES_ACTIVE_KEY]);
        expect(JSON.parse(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 99 })]),
        );
    });

    it('commitLawsuitWorkspacePersist fails when disk verify cannot see required id', async () => {
        const { commitLawsuitWorkspacePersist } = await import(
            '@/app/domain/lawsuit/lawsuitPersistFlush'
        );
        const { persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        persistLawsuitActiveSegment([file(7)]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([file(7)], [], []));
        await flushLawsuitWorkspacePersist(5_000);

        const spy = vi
            .spyOn(SecureStoreService, 'getItemFromDisk')
            .mockResolvedValue(JSON.stringify([file(1)]));
        const commit = await commitLawsuitWorkspacePersist({
            timeoutMs: 2_000,
            requireActiveFileId: 7,
        });
        expect(commit.ok).toBe(false);
        expect(
            commit.reason === 'verify-failed'
                || commit.reason === 'write-failed'
                || commit.reason === 'timeout',
        ).toBe(true);
        spy.mockRestore();
    });

    it('setItemSync refuses to poison memory with [] when protected key absent from mirror', () => {
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        const ok = SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        expect(ok).toBe(false);
        expect(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)).toBeNull();
    });

    it('setItem prefers disk data over poisoned empty memory mirror', async () => {
        await SecureStoreService.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(55)]));
        await flushLawsuitWorkspacePersist(5_000);

        SecureStoreService.dropMemoryMirrorsForTests([LAWSUIT_FILES_ACTIVE_KEY]);
        SecureStoreService.poisonMemoryMirrorForTests(LAWSUIT_FILES_ACTIVE_KEY, '[]');

        await SecureStoreService.setItem(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        await flushLawsuitWorkspacePersist(5_000);
        const surviving = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        expect(surviving).toBeTruthy();
        expect(JSON.parse(surviving!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 55 })]),
        );
    });

    it('awaitLawsuitWorkspaceCommit cancels debounce and verifies disk', async () => {
        const {
            scheduleLawsuitWorkspaceCommit,
            awaitLawsuitWorkspaceCommit,
        } = await import('@/app/domain/lawsuit/lawsuitPersistFlush');
        const { persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        persistLawsuitActiveSegment([file(77)]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([file(77)], [], []));
        scheduleLawsuitWorkspaceCommit({ requireActiveFileId: 77, debounceMs: 60_000 });
        const commit = await awaitLawsuitWorkspaceCommit({
            timeoutMs: 5_000,
            requireActiveFileId: 77,
        });
        expect(commit.ok).toBe(true);
        SecureStoreService.dropMemoryMirrorsForTests([LAWSUIT_FILES_ACTIVE_KEY]);
        const disk = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        expect(JSON.parse(disk!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 77 })]),
        );
    });

    it('commit without requireId does not soft-succeed when disk still has payload after memory drop', async () => {
        const { commitLawsuitWorkspacePersist } = await import(
            '@/app/domain/lawsuit/lawsuitPersistFlush'
        );
        const { persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        persistLawsuitActiveSegment([file(88)]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([file(88)], [], []));
        await flushLawsuitWorkspacePersist(5_000);
        SecureStoreService.dropMemoryMirrorsForTests([
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_INDEX_KEY,
            LAWSUIT_FILES_STORAGE_KEY,
            LAWSUIT_FILES_ARCHIVED_KEY,
        ]);
        const commit = await commitLawsuitWorkspacePersist({ timeoutMs: 5_000 });
        expect(commit.ok).toBe(true);
        const disk = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        expect(JSON.parse(disk!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 88 })]),
        );
    });

    it('archive last active file empties active segment on disk via verified empty', async () => {
        const { executeLawsuitLifecycleTransaction } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleTransaction'
        );
        const { awaitLawsuitWorkspaceCommit } = await import(
            '@/app/domain/lawsuit/lawsuitPersistFlush'
        );
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        const { persistLawsuitActiveSegment, persistLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitSegmentStorage'
        );
        const row = file(12);
        persistLawsuitActiveSegment([row]);
        persistLawsuitLifecycleIndex(buildLawsuitLifecycleIndex([row], [], []));
        await awaitLawsuitWorkspaceCommit({ timeoutMs: 5_000, requireActiveFileId: 12 });

        const result = await executeLawsuitLifecycleTransaction(
            {
                active: [row],
                archived: [],
                trash: [],
                index: buildLawsuitLifecycleIndex([row], [], []),
            },
            'archive',
            [12],
        );
        expect(result.ok).toBe(true);
        const next = result.next!;
        expect(next.active).toHaveLength(0);
        expect(next.archived).toHaveLength(1);
        SecureStoreService.dropMemoryMirrorsForTests([
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_ARCHIVED_KEY,
        ]);
        const diskActive = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        const diskArchived = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ARCHIVED_KEY);
        expect(JSON.parse(diskActive ?? '[]')).toHaveLength(0);
        expect(JSON.parse(diskArchived!)).toEqual(
            expect.arrayContaining([expect.objectContaining({ id: 12 })]),
        );
    });
});

import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import { CryptoService } from '@/app/services/CryptoService';
import SecureStoreService from '@/app/services/SecureStoreService';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { shouldRejectDossierWipe } from '@/app/services/dossierPersistence/dossierWipeGuard';
import { persistLawsuitActiveSegment } from '@/app/domain/lawsuit/lawsuitSegmentStorage';
import {
    LAWSUIT_PENDING_CREATES_KEY,
    clearLawsuitPendingCreatesForTests,
    listPendingLawsuitCreates,
    stagePendingLawsuitCreate,
} from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import {
    LAWSUIT_WRITE_JOURNAL_KEY,
    listLawsuitJournalEntries,
    mergeLawsuitJournalInto,
    stageLawsuitJournalRecords,
} from '@/app/domain/lawsuit/lawsuitWriteJournal';
import type { FileData } from '../lawsuitFileTypes';

const CRYPTO_PASSPHRASE = 'lawsuit-reload-durability-test';

const file = (id: number): FileData =>
    ({
        id,
        type: 'lawsuit',
        status: 'active',
        caseNo: `2026/${id}`,
        court: 'أحوال',
        parties: [],
        history: [],
        notes: [],
        images: [],
        date: '2026-01-01',
    }) as FileData;

async function ensureCryptoReady(): Promise<void> {
    if (!CryptoService.hasMasterKey()) {
        await CryptoService.initialize(CRYPTO_PASSPHRASE);
    }
    expect(CryptoService.hasMasterKey()).toBe(true);
}

async function flushPendingPersist(): Promise<void> {
    await SecureStoreService.waitForAllPendingPersist().catch(() => undefined);
}

describe('lawsuit reload durability — root causes', () => {
    beforeAll(async () => {
        await CryptoService.initialize(CRYPTO_PASSPHRASE);
        CryptoService.pinMasterKeyForAtomicWrite();
        expect(CryptoService.hasMasterKey()).toBe(true);
    });

    afterAll(async () => {
        await flushPendingPersist();
        CryptoService.unpinMasterKeyForAtomicWrite();
        CryptoService.destroy();
    });

    beforeEach(async () => {
        await flushPendingPersist();
        await ensureCryptoReady();
        SecureStoreService.dropMemoryMirrorsForTests?.();
        try {
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_ACTIVE_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_INDEX_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_STORAGE_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_WRITE_JOURNAL_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_PENDING_CREATES_KEY);
        } catch {
            /* ignore */
        }
        clearLawsuitPendingCreatesForTests();
        localStorage.removeItem(LAWSUIT_WRITE_JOURNAL_KEY);
        await flushPendingPersist();
        try {
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_ACTIVE_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_INDEX_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_STORAGE_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_WRITE_JOURNAL_KEY);
            SecureStoreService.deleteItemSync(LAWSUIT_PENDING_CREATES_KEY);
        } catch {
            /* ignore */
        }
        SecureStoreService.dropMemoryMirrorsForTests?.();
        await ensureCryptoReady();
    });

    afterEach(async () => {
        await flushPendingPersist();
    });

    it('wipe guard rejects poorer non-empty lawyer_files_active write', () => {
        const existing = JSON.stringify([file(1), file(2), file(3)]);
        const incoming = JSON.stringify([file(9)]);
        expect(shouldRejectDossierWipe(LAWSUIT_FILES_ACTIVE_KEY, incoming, existing)).toBe(true);
    });

    it('wipe guard rejects any overwrite of unreadable/encrypted lawyer payload', () => {
        const cipher = 'hami_enc_v2:not-json-ciphertext';
        const incoming = JSON.stringify([file(1)]);
        expect(shouldRejectDossierWipe(LAWSUIT_FILES_ACTIVE_KEY, incoming, cipher)).toBe(true);
    });

    it('persist poorer list does not shrink readable active segment', async () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1), file(2)]));
        persistLawsuitActiveSegment([file(9)]);
        await flushPendingPersist();
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        const ids = parsed.map((r) => r.id).sort((a, b) => a - b);
        expect(ids).toEqual([1, 2, 9]);
    });

    it('persistLawsuitFiles skips index/mirror when active segment is cold', async () => {
        const { LAWSUIT_FILES_INDEX_KEY, LAWSUIT_FILES_STORAGE_KEY } = await import(
            '@/app/services/dossierPersistence/dossierStorageKeys'
        );
        const { persistLawsuitFiles } = await import('@/app/domain/lawsuit/lawsuitFilesRepository');

        const cipher = 'hami_enc_v2:cold-active-segment';
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, cipher);
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                counts: { active: 3, archived: 0, trash: 0 },
                entries: {},
            }),
        );
        SecureStoreService.setItemSync(LAWSUIT_FILES_STORAGE_KEY, cipher);
        SecureStoreService.clearDecryptedMemoryCache();
        await ensureCryptoReady();

        persistLawsuitFiles([file(99)]);
        await flushPendingPersist();

        const indexRaw = SecureStoreService.getItemSync(LAWSUIT_FILES_INDEX_KEY);
        expect(String(indexRaw)).toContain('"active":3');
        const activeRaw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        expect(activeRaw == null || activeRaw === cipher).toBe(true);
        expect(String(activeRaw ?? '')).not.toContain('"id":99');
        expect(
            activeRaw === cipher || SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY),
        ).toBe(true);
    });

    it('create → drop memory (reload) → boot still returns the personal-status file from pending', async () => {
        const { persistLawsuitFiles, loadInitialLawsuitFiles } = await import(
            '@/app/domain/lawsuit/lawsuitFilesRepository'
        );
        const { resetLawsuitPageWriteGuardForTests } = await import(
            '@/app/domain/lawsuit/lawsuitPageWriteGuard'
        );

        stagePendingLawsuitCreate(file(42));
        persistLawsuitFiles([file(42)]);
        await flushPendingPersist();
        SecureStoreService.dropMemoryMirrorsForTests?.([LAWSUIT_FILES_ACTIVE_KEY]);

        const afterReload = loadInitialLawsuitFiles();
        expect(afterReload.map((f) => Number(f.id))).toContain(42);

        resetLawsuitPageWriteGuardForTests();
        expect(listPendingLawsuitCreates().map((f) => Number(f.id))).toContain(42);
    });

    it('reload keeps personal pending when disk only has a different civil file', async () => {
        const { persistLawsuitFiles, loadInitialLawsuitFiles } = await import(
            '@/app/domain/lawsuit/lawsuitFilesRepository'
        );
        const personal = {
            ...file(77),
            lawsuitJurisdiction: 'personal',
            court: 'عفغ',
            parties: [{ id: 1, name: 'فغعفغ', role: 'المدعي', isClient: true }],
        } as FileData;

        persistLawsuitFiles([file(1)]);
        await flushPendingPersist();
        stagePendingLawsuitCreate(personal);
        SecureStoreService.dropMemoryMirrorsForTests?.([LAWSUIT_FILES_ACTIVE_KEY]);

        const afterReload = loadInitialLawsuitFiles();
        const ids = afterReload.map((f) => Number(f.id));
        expect(ids).toContain(1);
        expect(ids).toContain(77);
    });

    it('write journal survives memory drop and merges back into active list', async () => {
        stageLawsuitJournalRecords([file(43)]);
        await flushPendingPersist();
        expect(listLawsuitJournalEntries()).toHaveLength(1);

        SecureStoreService.dropMemoryMirrorsForTests?.([LAWSUIT_FILES_ACTIVE_KEY]);
        const merged = mergeLawsuitJournalInto([]);
        expect(merged.map((f) => Number(f.id))).toEqual([43]);
    });

    it('allowShrink permits intentional archive shrink past wipe guard', async () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1), file(2)]));
        persistLawsuitActiveSegment([file(1)], { allowShrink: true });
        await flushPendingPersist();
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        expect(JSON.parse(String(raw))).toHaveLength(1);
    });
});

/**
 * مقطع دعاوى واحد فوق ENCRYPT_MAX_BYTES — تحذير DEV دون كسر الكتابة/الإقلاع.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';
import { ENCRYPT_MAX_BYTES } from '@/app/services/secureStorageKeys';
import { warnIfLawsuitSegmentExceedsEncryptLimit } from '@/app/domain/lawsuit/lawsuitSegmentStorage';

describe('warnIfLawsuitSegmentExceedsEncryptLimit', () => {
    afterEach(() => {
        vi.restoreAllMocks();
    });

    it('does not warn under the encrypt size cap', () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        warnIfLawsuitSegmentExceedsEncryptLimit(
            'lawyer_files_active',
            'x'.repeat(ENCRYPT_MAX_BYTES),
        );
        expect(warn).not.toHaveBeenCalled();
    });

    it('warns once-shaped message when a single segment exceeds the cap', () => {
        const warn = vi.spyOn(console, 'warn').mockImplementation(() => {});
        const over = 'x'.repeat(ENCRYPT_MAX_BYTES + 8);
        warnIfLawsuitSegmentExceedsEncryptLimit('lawyer_files_archived', over);
        expect(warn).toHaveBeenCalledTimes(1);
        expect(String(warn.mock.calls[0]?.[0])).toContain('lawyer_files_archived');
        expect(String(warn.mock.calls[0]?.[0])).toContain('ENCRYPT_MAX_BYTES');
    });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import type { FileData } from '../lawsuitFileTypes';
import SecureStoreService from '@/app/services/SecureStoreService';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_TRASH_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { loadLawsuitFilesRaw, saveLawsuitFilesRaw } from '@/app/utils/lawsuitFilesStorage';
import { clearLawsuitPendingCreatesForTests } from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import {
    applyLawsuitMonolithicMergeToSegments,
    collectLawsuitLocalRowsForSync,
    findLawsuitFileAcrossSegments,
    loadLawsuitBootState,
    migrateLawsuitMonolithicToSegmentsIfNeeded,
    persistLawsuitActiveSegment,
    readLawsuitActiveSegment,
    readLawsuitArchivedSegment,
    readLawsuitTrashSegment,
    resolveLazyLawsuitSegmentForMirror,
    mirrorLawsuitSegmentsSafe,
} from '@/app/domain/lawsuit/lawsuitSegmentStorage';
import { buildLawsuitLifecycleIndex } from '@/app/domain/lawsuit/lawsuitLifecycleIndex';
import { markLawsuitDossierTombstone, LAWSUIT_DOSSIER_TOMBSTONES_KEY } from '@/app/utils/lawsuitDossierTombstones';
import {
    loadInitialLawsuitFiles,
    applyLawsuitTrashSegments,
    applyLawsuitConsolidationSegments,
    emptyLawsuitFileSegments,
} from '@/app/domain/lawsuit/lawsuitFilesRepository';

vi.mock('@/app/utils/lawsuitFilesStorage', () => ({
    loadLawsuitFilesRaw: vi.fn(() => []),
    saveLawsuitFilesRaw: vi.fn(),
}));

const file = (id: number, status: FileData['status'] = 'active'): FileData => ({
    id,
    type: 'lawsuit',
    status,
    caseNo: `2026/ب/${id}`,
    court: 'بداءة الكرخ',
    parties: [],
    history: [],
    notes: [],
    images: [],
    date: '2026-01-01',
});

describe('lawsuitSegmentStorage boot', () => {
    beforeEach(() => {
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([]);
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        clearLawsuitPendingCreatesForTests();
        try {
            SecureStoreService.deleteItemSync('hami_lawsuit_write_journal_v1');
        } catch {
            /* ignore */
        }
        localStorage.removeItem('hami_lawsuit_write_journal_v1');
        localStorage.removeItem(LAWSUIT_FILES_ACTIVE_KEY);
        localStorage.removeItem(LAWSUIT_FILES_ARCHIVED_KEY);
        localStorage.removeItem(LAWSUIT_FILES_INDEX_KEY);
        localStorage.removeItem(LAWSUIT_FILES_STORAGE_KEY);
        localStorage.removeItem(LAWSUIT_FILES_TRASH_KEY);
        try {
            SecureStoreService.deleteItemSync(LAWSUIT_DOSSIER_TOMBSTONES_KEY);
        } catch {
            /* ignore */
        }
        localStorage.removeItem(LAWSUIT_DOSSIER_TOMBSTONES_KEY);
    });

    it('loadLawsuitBootState returns active only with null lazy segments', () => {
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_ACTIVE_KEY,
            JSON.stringify([file(1), file(2)]),
        );
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 2, archived: 0, trash: 0 },
            }),
        );
        const boot = loadLawsuitBootState();
        expect(boot.active).toHaveLength(2);
        expect(boot.archived).toBeNull();
        expect(boot.trash).toBeNull();
    });

    it('migrate splits monolithic lawyer_files into segments', async () => {
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([
            file(1),
            file(2, 'archived'),
            file(3, 'deleted'),
        ]);
        const boot = migrateLawsuitMonolithicToSegmentsIfNeeded();
        expect(boot.migrated).toBe(true);
        expect(readLawsuitActiveSegment()).toHaveLength(1);
        expect(readLawsuitArchivedSegment()).toHaveLength(1);
        expect(readLawsuitTrashSegment()).toHaveLength(1);
    });

    it('empty active does not resurrect from stale monolith when trash already exists', async () => {
        const trashed = file(1, 'deleted');
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        SecureStoreService.setItemSync(LAWSUIT_FILES_ARCHIVED_KEY, '[]');
        SecureStoreService.setItemSync(LAWSUIT_FILES_TRASH_KEY, JSON.stringify([trashed]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify(buildLawsuitLifecycleIndex([], [], [trashed])),
        );
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([file(1)]);

        const boot = migrateLawsuitMonolithicToSegmentsIfNeeded();

        expect(boot.active).toHaveLength(0);
        expect(readLawsuitActiveSegment()).toEqual([]);
        expect(readLawsuitTrashSegment()).toEqual([
            expect.objectContaining({ id: 1, status: 'deleted' }),
        ]);
    });

    it('persistLawsuitActiveSegment يرفض إفراغ النشط بدون allowShrink', () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1), file(2)]));
        persistLawsuitActiveSegment([]);
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        expect(raw).toBeTruthy();
        const parsed = JSON.parse(String(raw)) as unknown[];
        expect(parsed).toHaveLength(2);
    });

    it('persistLawsuitActiveSegment يدمج قائمة جزئية مع القرص الأغنى', () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1), file(2)]));
        persistLawsuitActiveSegment([file(3)]);
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        const ids = parsed.map((r) => r.id).sort((a, b) => a - b);
        expect(ids).toEqual([1, 2, 3]);
    });

    it('persistLawsuitActiveSegment يسمح بالإفراغ مع allowShrink', () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1)]));
        persistLawsuitActiveSegment([], { allowShrink: true, allowVerifiedEmpty: true });
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        expect(JSON.parse(String(raw))).toEqual([]);
    });

    it('loadLawsuitBootState لا يفرّغ النشط عند تكرار سلة∩نشط', () => {
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_ACTIVE_KEY,
            JSON.stringify([file(1), file(2)]),
        );
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_TRASH_KEY,
            JSON.stringify([file(1, 'deleted'), file(2, 'deleted')]),
        );
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 2, archived: 0, trash: 2 },
            }),
        );
        const boot = loadLawsuitBootState();
        expect(boot.active.map((f) => Number(f.id)).sort((a, b) => a - b)).toEqual([1, 2]);
        expect(readLawsuitActiveSegment().map((f) => Number(f.id)).sort((a, b) => a - b)).toEqual([
            1, 2,
        ]);
    });

    it('loadInitialLawsuitFiles returns active segment only', () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1)]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_ARCHIVED_KEY,
            JSON.stringify([file(2, 'archived')]),
        );
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 1, archived: 1, trash: 0 },
            }),
        );
        expect(loadInitialLawsuitFiles()).toHaveLength(1);
    });

    it('applyLawsuitTrashSegments moves file between segments in memory', () => {
        const segments = {
            ...emptyLawsuitFileSegments(),
            active: [file(1), file(2)],
            trash: [],
            index: {
                v: 1 as const,
                entries: {},
                counts: { active: 2, archived: 0, trash: 0 },
            },
        };
        const next = applyLawsuitTrashSegments(segments, 1);
        expect(next.active).toHaveLength(1);
        expect(next.trash).toHaveLength(1);
        expect(next.index.counts.trash).toBe(1);
        expect(next.index.counts.active).toBe(1);
    });

    it('applyLawsuitMonolithicMergeToSegments يرفض الدمج الفارغ فوق بيانات موجودة', () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(3)]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 1, archived: 0, trash: 0 },
            }),
        );
        const kept = applyLawsuitMonolithicMergeToSegments([]);
        expect(kept.active).toHaveLength(1);
        expect(kept.active[0]?.id).toBe(3);
    });

    it('applyLawsuitMonolithicMergeToSegments لا يمسح إضابات القرص بقائمة سحابة أقصر', () => {
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_ACTIVE_KEY,
            JSON.stringify([file(1), file(2)]),
        );
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify({
                v: 1,
                entries: {},
                counts: { active: 2, archived: 0, trash: 0 },
            }),
        );
        const next = applyLawsuitMonolithicMergeToSegments([file(1), file(9)]);
        const ids = next.active.map((f) => Number(f.id)).sort((a, b) => a - b);
        expect(ids).toEqual([1, 2, 9]);
        expect(readLawsuitActiveSegment().map((f) => Number(f.id)).sort((a, b) => a - b)).toEqual([
            1, 2, 9,
        ]);
    });

    it('applyLawsuitMonolithicMergeToSegments يعيد تقسيم المرآة إلى مقاطع', () => {
        applyLawsuitMonolithicMergeToSegments([
            file(1),
            file(2, 'archived'),
            file(3, 'deleted'),
        ]);
        expect(readLawsuitActiveSegment()).toHaveLength(1);
        expect(readLawsuitArchivedSegment()).toHaveLength(1);
        expect(readLawsuitTrashSegment()).toHaveLength(1);
        expect(saveLawsuitFilesRaw).toHaveBeenCalled();
        expect(findLawsuitFileAcrossSegments(2)?.status).toBe('archived');
        expect(findLawsuitFileAcrossSegments(3)?.status).toBe('deleted');
    });

    it('mirrorLawsuitSegmentsSafe لا يبني مرآة من أرشيف غير مقروء', async () => {
        await SecureStoreService.setItem(
            LAWSUIT_FILES_ARCHIVED_KEY,
            JSON.stringify([file(9, 'archived')]),
        );
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1)]));
        SecureStoreService.clearDecryptedMemoryCache();
        expect(SecureStoreService.isUnreadSync(LAWSUIT_FILES_ARCHIVED_KEY)).toBe(true);

        vi.mocked(saveLawsuitFilesRaw).mockClear();
        mirrorLawsuitSegmentsSafe([file(1)], null, []);
        expect(saveLawsuitFilesRaw).not.toHaveBeenCalled();
    });

    it('resolveLazyLawsuitSegmentForMirror لا يستبدل null بمصفوفة فارغة', () => {
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_ARCHIVED_KEY,
            JSON.stringify([file(9, 'archived')]),
        );
        const resolved = resolveLazyLawsuitSegmentForMirror(null, readLawsuitArchivedSegment);
        expect(resolved).toHaveLength(1);
        expect(resolved[0]?.id).toBe(9);
    });

    it('applyLawsuitTrashSegments مع trash=null لا يمسح المهملات على القرص', () => {
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_TRASH_KEY,
            JSON.stringify([file(90, 'deleted')]),
        );
        const segments = {
            ...emptyLawsuitFileSegments(),
            active: [file(1), file(2)],
            trash: null,
            index: {
                v: 1 as const,
                entries: {},
                counts: { active: 2, archived: 0, trash: 1 },
            },
        };
        const next = applyLawsuitTrashSegments(segments, 1);
        expect(next.trash).toHaveLength(2);
        expect(next.trash?.map((f) => f.id).sort()).toEqual([1, 90]);
        expect(readLawsuitTrashSegment()).toHaveLength(1);
        expect(readLawsuitTrashSegment().map((f) => f.id)).toEqual([90]);
    });

    it('applyLawsuitConsolidationSegments يضع الثانوية في archived لا active', () => {
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_ARCHIVED_KEY,
            JSON.stringify([file(9, 'archived')]),
        );
        const primary = file(1);
        const secondary = { ...file(2), status: 'archived' as const };
        const segments = {
            ...emptyLawsuitFileSegments(),
            active: [primary, file(2)],
            archived: null,
            trash: null,
            index: {
                v: 1 as const,
                entries: {},
                counts: { active: 2, archived: 1, trash: 0 },
            },
        };
        const next = applyLawsuitConsolidationSegments(segments, primary, secondary);
        expect(next.active.map((f) => f.id)).toEqual([1]);
        expect(next.active.every((f) => f.status !== 'archived')).toBe(true);
        expect(next.archived?.map((f) => f.id).sort()).toEqual([2, 9]);
        expect(readLawsuitArchivedSegment().map((f) => f.id).sort()).toEqual([2, 9]);
        expect(readLawsuitActiveSegment().map((f) => f.id)).toEqual([1]);
    });

    it('يرحّل leftover المقطع النشط ويمحوه', () => {
        localStorage.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(77)]));
        expect(readLawsuitActiveSegment().some((f) => String(f.id) === '77')).toBe(true);
        expect(localStorage.getItem(LAWSUIT_FILES_ACTIVE_KEY)).toBeNull();
        expect(SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY)).toContain('"id":77');
    });

    it('لا يسمّ leftover فوق أصل unread', () => {
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, 'hami_enc_v2:lawsuit-cold');
        SecureStoreService.clearDecryptedMemoryCache();
        localStorage.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(1)]));
        expect(readLawsuitActiveSegment()).toEqual([]);
        expect(localStorage.getItem(LAWSUIT_FILES_ACTIVE_KEY)).not.toBeNull();
    });

    it('بعد كتابة المقطع تُمحى مرآة localStorage', () => {
        localStorage.setItem(LAWSUIT_FILES_ACTIVE_KEY, JSON.stringify([file(9)]));
        persistLawsuitActiveSegment([file(3)]);
        expect(localStorage.getItem(LAWSUIT_FILES_ACTIVE_KEY)).toBeNull();
        expect(readLawsuitActiveSegment().some((f) => Number(f.id) === 3)).toBe(true);
    });

    it('دمج السحابة لا يُعيد إضبارة عليها شاهد حذف', () => {
        persistLawsuitActiveSegment([file(1)]);
        markLawsuitDossierTombstone(2);
        applyLawsuitMonolithicMergeToSegments([file(1), file(2)]);
        expect(readLawsuitActiveSegment().map((f) => Number(f.id))).toEqual([1]);
        expect(
            collectLawsuitLocalRowsForSync()
                .map((f) => Number(f.id))
                .sort((a, b) => a - b),
        ).toEqual([1]);
    });

    it('collectLawsuitLocalRowsForSync يستبعد شواهد الحذف من كل المقاطع', () => {
        persistLawsuitActiveSegment([file(1)]);
        SecureStoreService.setItemSync(LAWSUIT_FILES_TRASH_KEY, JSON.stringify([file(9, 'deleted')]));
        markLawsuitDossierTombstone(9);
        const ids = collectLawsuitLocalRowsForSync().map((f) => Number(f.id));
        expect(ids).toEqual([1]);
    });
});

import { beforeEach, describe, expect, it, vi } from 'vitest';
import type { FileData } from '../lawsuitFileTypes';
import SecureStoreService from '@/app/services/SecureStoreService';
import { resetLawsuitCommitSchedulerForTests } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import { clearLawsuitPendingCreatesForTests } from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import { LAWSUIT_WRITE_JOURNAL_KEY } from '@/app/domain/lawsuit/lawsuitWriteJournal';

vi.mock('@/app/utils/lawsuitFilesStorage', () => ({
    loadLawsuitFilesRaw: vi.fn(() => []),
    saveLawsuitFilesRaw: vi.fn(),
}));

vi.mock('@/app/services/dossierPersistence/dossierBackupStore', () => ({
    listDossierBackups: vi.fn(async () => []),
    readLatestDossierBackup: vi.fn(async () => null),
}));

vi.mock('@/app/services/cloudSyncEngine', () => ({
    performCloudSyncBucket: vi.fn(async () => ({ ok: true, skipped: true })),
}));

vi.mock('@/app/services/cloud/workCloudCheckpoint', () => ({
    restoreLastWorkCloudCheckpoint: vi.fn(async () => ({
        applied: false,
        lawsuits: 0,
        execution: 0,
        notes: 0,
        calendar: 0,
        failed: false,
    })),
}));

const file = (id: number): FileData => ({
    id,
    type: 'lawsuit',
    status: 'active',
    caseNo: `2026/ب/${id}`,
    court: 'أحوال',
    parties: [],
    history: [],
    notes: [],
    images: [],
    date: '2026-01-01',
});

describe('recoverLawsuitWorkspaceFromLocalDisk', () => {
    beforeEach(async () => {
        resetLawsuitCommitSchedulerForTests();
        try {
            localStorage.removeItem(LAWSUIT_WRITE_JOURNAL_KEY);
            clearLawsuitPendingCreatesForTests();
        } catch {
            /* ignore */
        }
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        await SecureStoreService.waitForAllPendingPersist();
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        vi.clearAllMocks();
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([]);
        const { listDossierBackups } = await import(
            '@/app/services/dossierPersistence/dossierBackupStore'
        );
        vi.mocked(listDossierBackups).mockResolvedValue([]);
    });

    it('never throws and reports empty diagnosis', async () => {
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk();
        expect(result.ok).toBe(false);
        expect(result.source).toBe('none');
        expect(result.message.length).toBeGreaterThan(10);
    });

    it('recovers from monolithic when segments empty', async () => {
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([file(42)]);

        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk();
        expect(result.ok).toBe(true);
        expect(['monolithic', 'active']).toContain(result.source);
        expect(result.segments.active.some((f) => String(f.id) === '42')).toBe(true);
    });

    it('لا يستورد المرآة إلى النشط إن وُجدت سلة على القرص', async () => {
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        const {
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_INDEX_KEY,
            LAWSUIT_FILES_TRASH_KEY,
        } = await import('@/app/services/dossierPersistence/dossierStorageKeys');
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        const trashed = { ...file(42), status: 'deleted' as const, deletedAt: 1 };
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        SecureStoreService.setItemSync(LAWSUIT_FILES_TRASH_KEY, JSON.stringify([trashed]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify(buildLawsuitLifecycleIndex([], [], [trashed])),
        );
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([file(42)]);

        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk({ includeCloud: false });
        expect(result.ok).toBe(true);
        expect(result.segments.active.some((f) => String(f.id) === '42')).toBe(false);
        expect(result.segments.trash?.some((f) => String(f.id) === '42')).toBe(true);
    });

    it('recovers from dossier backup list', async () => {
        const { listDossierBackups } = await import(
            '@/app/services/dossierPersistence/dossierBackupStore'
        );
        vi.mocked(listDossierBackups).mockResolvedValue([
            {
                meta: {
                    domain: 'lawsuit',
                    revision: 3,
                    savedAt: new Date().toISOString(),
                    itemCount: 1,
                },
                payload: [file(99)],
            },
        ]);

        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk();
        expect(result.ok).toBe(true);
        expect(result.source).toBe('backup');
        expect(result.segments.active.some((f) => String(f.id) === '99')).toBe(true);
    });

    it('includeCloud:false لا يستدعي المزامنة على مسار فتح المخزن', async () => {
        const { performCloudSyncBucket } = await import('@/app/services/cloudSyncEngine');
        const { restoreLastWorkCloudCheckpoint } = await import(
            '@/app/services/cloud/workCloudCheckpoint'
        );
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        await recoverLawsuitWorkspaceFromLocalDisk({
            includeCloud: false,
            fullPersistReady: false,
        });
        expect(performCloudSyncBucket).not.toHaveBeenCalled();
        expect(restoreLastWorkCloudCheckpoint).not.toHaveBeenCalled();
    });

    it('includeCloud الافتراضي يحاول استعادة نقطة العمل قبل مزامنة السلة', async () => {
        const { restoreLastWorkCloudCheckpoint } = await import(
            '@/app/services/cloud/workCloudCheckpoint'
        );
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        await recoverLawsuitWorkspaceFromLocalDisk({ fullPersistReady: false });
        expect(restoreLastWorkCloudCheckpoint).toHaveBeenCalled();
    });

