import type { FileData } from './lawsuitFileTypes';
import type { Party } from '@/app/components/lawyer/lawyerShared/fileDataTypes';
import { computeLawsuitStageOptions } from './lawsuitStageOptions';
import { partitionPartiesBySide } from '@/app/components/lawyer/smart-modal/smartFile/partyRoleClassification';

/** طرف نموذج الإنشاء — حقول النواة فقط، بلا استيراد LawyerNewCase. */
export type IncidentalSpawnFormParty = {
    id: string;
    name: string;
    status: string;
    isClient: boolean;
    phone: string;
    address: string;
};

export type IncidentalSpawnStageOverride = {
    stageIndex: number;
    stageName: string;
    court: string;
    judge: string;
    docType: string;
    retrialTargetStage?: string;
    parties: Party[];
};

export type IncidentalSpawnContext = {
    parentFileId: number;
    parentCaseNo: string;
    incidentalId: string;
    type: 'joined' | 'counter';
    details?: string;
    stageOverride?: IncidentalSpawnStageOverride;
    filingPartyId?: string;
    filingPartyName?: string;
};

type IncidentalSpawnParentSnapshot = {
    court: string;
    judge: string;
    docType: string;
    stage: string;
    retrialTargetStage?: string;
    plaintiffs: IncidentalSpawnFormParty[];
    defendants: IncidentalSpawnFormParty[];
};

export type IncidentalSpawnContextEnriched = IncidentalSpawnContext & {
    parent: IncidentalSpawnParentSnapshot;
};

export type IncidentalSpawnPartySelection = {
    filingPartyId?: string | null;
    opposingPartyId?: string | null;
};

export type IncidentalSpawnPrefill = {
    caseDetails: {
        number: string;
        court: string;
        type: string;
        judge: string;
        firstHearingDate: string;
        stage: string;
        claimValue: string;
        totalAgreedFees: string;
        retrialTargetStage: string;
    };
    parties1: IncidentalSpawnFormParty[];
    parties2: IncidentalSpawnFormParty[];
    stageOptions: string[];
    requiresFilingPartyPick: boolean;
    requiresOpposingPartyPick: boolean;
    filingPartyCandidates: IncidentalSpawnFormParty[];
    opposingPartyCandidates: IncidentalSpawnFormParty[];
    filingPartySide: 'plaintiff' | 'defendant';
    headerBadge: { label: string; tone: 'joined' | 'counter' };
};

const COUNTER_ALLOWED_STAGE_MARKERS = [
    'بداءة',
    'اعتراض على الحكم الغيابي',
    'اعتراض الغير',
] as const;

export function isCounterClaimAllowedStage(stage: string): boolean {
    const s = String(stage ?? '').trim();
    if (!s) return false;
    if (/استئناف/i.test(s)) return false;
    if (/إعادة\s*(لل)?المحاكمة/i.test(s)) return false;
    return COUNTER_ALLOWED_STAGE_MARKERS.some((marker) => s.includes(marker));
}

type IncidentalSpawnConfirmPreview = {
    court: string;
    judge: string;
    stage: string;
    plaintiffs: IncidentalSpawnFormParty[];
    defendants: IncidentalSpawnFormParty[];
};

export function buildIncidentalSpawnConfirmPreview(
    stage: {
        stageName?: string;
        court?: string;
        judge?: string;
        parties?: Party[];
    },
    spawnType: 'joined' | 'counter',
): IncidentalSpawnConfirmPreview {
    const parties = Array.isArray(stage.parties) ? stage.parties : [];
    const { plaintiffs, defendants } = partitionPartiesBySide(parties);
    const plaintiffsForm = plaintiffs.map(toFormParty);
    const defendantsForm = defendants.map(toFormParty);

    return {
        court: String(stage.court ?? '').trim(),
        judge: String(stage.judge ?? '').trim(),
        stage: String(stage.stageName ?? '').trim(),
        plaintiffs: spawnType === 'joined' ? plaintiffsForm : defendantsForm,
        defendants: spawnType === 'joined' ? defendantsForm : plaintiffsForm,
    };
}

function resolveParentActiveStageSnapshot(
    file: FileData,
    stageIndex?: number,
): {
    court: string;
    judge: string;
    docType: string;
    stage: string;
    retrialTargetStage?: string;
    parties: Party[];
} {
    const fallbackIdx =
        typeof file.activeStageIndex === 'number' && file.activeStageIndex >= 0
            ? file.activeStageIndex
            : 0;
    const idx =
        typeof stageIndex === 'number' && stageIndex >= 0
            ? stageIndex
            : fallbackIdx;
    const stage = Array.isArray(file.stages) ? file.stages[idx] : undefined;

    return {
        court: String(stage?.court ?? file.court ?? '').trim(),
        judge: String(stage?.judge ?? file.judge ?? '').trim(),
        docType: String(stage?.docType ?? file.docType ?? '').trim(),
        stage: String(stage?.stageName ?? file.currentStage ?? '').trim(),
        retrialTargetStage: String(
            stage?.retrialTargetStage ?? file.retrialTargetStage ?? '',
        ).trim() || undefined,
        parties: (stage?.parties ?? file.parties ?? []) as Party[],
    };
}

function toFormParty(party: Party, index: number): IncidentalSpawnFormParty {
    const id = String(party.id ?? `p_${index}`);
    return {
        id,
        name: String(party.name ?? '').trim(),
        status: String(party.role ?? '').trim(),
        isClient: Boolean(party.isClient),
        phone: party.phone ?? '',
        address: party.address ?? '',
    };
}

function cloneFormParties(parties: IncidentalSpawnFormParty[]): IncidentalSpawnFormParty[] {
    return parties.map((p, idx) => ({
        ...p,
        id: `${p.id}_spawn_${idx}`,
    }));
}

export function buildIncidentalSpawnParentSnapshot(
    file: FileData,
    stageIndex?: number,
): IncidentalSpawnParentSnapshot {
    const snap = resolveParentActiveStageSnapshot(file, stageIndex);
    const { plaintiffs, defendants } = partitionPartiesBySide(snap.parties);

    return {
        court: snap.court,
        judge: snap.judge,
        docType: snap.docType,
        stage: snap.stage,
        retrialTargetStage: snap.retrialTargetStage,
        plaintiffs: plaintiffs.map(toFormParty),
        defendants: defendants.map(toFormParty),
    };
}

function buildParentSnapshotFromStageOverride(
    override: NonNullable<IncidentalSpawnContext['stageOverride']>,
): IncidentalSpawnParentSnapshot {
    const { plaintiffs, defendants } = partitionPartiesBySide(override.parties);
    return {
        court: override.court,
        judge: override.judge,
        docType: override.docType,
        stage: override.stageName,
        retrialTargetStage: override.retrialTargetStage,
        plaintiffs: plaintiffs.map(toFormParty),
        defendants: defendants.map(toFormParty),
    };
}

export function enrichIncidentalSpawnContext(
    parentFile: FileData,
    ctx: IncidentalSpawnContext,
): IncidentalSpawnContextEnriched {
    const parent = ctx.stageOverride
        ? buildParentSnapshotFromStageOverride(ctx.stageOverride)
        : buildIncidentalSpawnParentSnapshot(parentFile);
    return {
        ...ctx,
        parent,
    };
}

function computeIncidentalSpawnStageOptions(
    court: string,
    spawnType: 'joined' | 'counter',
    parentStage: string,
): string[] {
    if (spawnType === 'joined') {
        const base = computeLawsuitStageOptions(court);
        return parentStage && base.includes(parentStage) ? [parentStage] : base;
    }
    const base = computeLawsuitStageOptions(court).filter(isCounterClaimAllowedStage);
    return parentStage && base.includes(parentStage) ? [parentStage] : base;
}

function resolveSelectedId(
    candidates: IncidentalSpawnFormParty[],
    selectedId: string | null | undefined,
): string | null {
    if (candidates.length <= 1) return candidates[0]?.id ?? null;
    if (selectedId && candidates.some((p) => p.id === selectedId)) return selectedId;
    return null;
}

function filterToSelected(
    list: IncidentalSpawnFormParty[],
    selectedId: string | null,
    requiresPick: boolean,
): IncidentalSpawnFormParty[] {
    if (!requiresPick || !selectedId) return list;
    const picked = list.filter((p) => p.id === selectedId);
    return picked.length > 0 ? picked : list;
}

export function buildIncidentalSpawnPrefill(
    ctx: IncidentalSpawnContextEnriched,
    selection: IncidentalSpawnPartySelection = {},
): IncidentalSpawnPrefill {
    const { parent, type } = ctx;
    const stageOptions = computeIncidentalSpawnStageOptions(parent.court, type, parent.stage);

    const parentPlaintiffs = cloneFormParties(parent.plaintiffs);
    const parentDefendants = cloneFormParties(parent.defendants);

    let filingPartyCandidates: IncidentalSpawnFormParty[];
    let opposingPartyCandidates: IncidentalSpawnFormParty[];

    if (type === 'joined') {
        filingPartyCandidates = parentPlaintiffs;
        opposingPartyCandidates = parentDefendants;
    } else {
        filingPartyCandidates = parentDefendants;
        opposingPartyCandidates = parentPlaintiffs;
    }

    const requiresFilingPartyPick = filingPartyCandidates.length > 1;
    const requiresOpposingPartyPick = opposingPartyCandidates.length > 1;

    const resolvedFilingId = resolveSelectedId(filingPartyCandidates, selection.filingPartyId);
    const resolvedOpposingId = resolveSelectedId(opposingPartyCandidates, selection.opposingPartyId);

    let parties1: IncidentalSpawnFormParty[];
    let parties2: IncidentalSpawnFormParty[];

    if (type === 'joined') {
        parties1 = filterToSelected(parentPlaintiffs, resolvedFilingId, requiresFilingPartyPick);
        parties2 = filterToSelected(parentDefendants, resolvedOpposingId, requiresOpposingPartyPick);
    } else {
        parties1 = filterToSelected(parentDefendants, resolvedFilingId, requiresFilingPartyPick);
        parties2 = filterToSelected(parentPlaintiffs, resolvedOpposingId, requiresOpposingPartyPick);
    }

    if (resolvedFilingId) {
        parties1 = parties1.map((p) => ({
            ...p,
            isClient: p.id === resolvedFilingId ? p.isClient || true : p.isClient,
        }));
    }

    return {
        caseDetails: {
            number: '',
            court: parent.court,
            type: parent.docType,
            judge: parent.judge,
            firstHearingDate: '',
            stage: parent.stage,
            claimValue: '',
            totalAgreedFees: '',
            retrialTargetStage: parent.retrialTargetStage ?? '',
        },
        parties1: parties1.length > 0 ? parties1 : [{ id: 'p1_1', name: '', status: '', isClient: false, phone: '', address: '' }],
        parties2: parties2.length > 0 ? parties2 : [{ id: 'p2_1', name: '', status: '', isClient: false, phone: '', address: '' }],
        stageOptions,
        requiresFilingPartyPick,
        requiresOpposingPartyPick,
        filingPartyCandidates,
        opposingPartyCandidates,
        filingPartySide: type === 'joined' ? 'plaintiff' : 'defendant',
        headerBadge:
            type === 'joined'
                ? { label: 'دعوى منضمة', tone: 'joined' }
                : { label: 'دعوى متقابلة', tone: 'counter' },
    };
}

export function validateIncidentalSpawnSave(
    ctx: IncidentalSpawnContextEnriched,
    selection: IncidentalSpawnPartySelection,
): string | null {
    if (ctx.type === 'counter' && !isCounterClaimAllowedStage(ctx.parent.stage)) {
        return 'لا يمكن إنشاء دعوى متقابلة في مرحلة الاستئناف أو إعادة المحاكمة';
    }
    const prefill = buildIncidentalSpawnPrefill(ctx, selection);
    if (prefill.requiresFilingPartyPick && !selection.filingPartyId) {
        return ctx.type === 'joined'
            ? 'يرجى اختيار مقدّم الدعوى المنضمة'
            : 'يرجى اختيار مقدّم الدعوى المتقابلة';
    }
    if (prefill.requiresOpposingPartyPick && !selection.opposingPartyId) {
        return ctx.type === 'joined'
            ? 'يرجى اختيار المدعى عليه في الدعوى المنضمة'
            : 'يرجى اختيار المدعي في الدعوى المتقابلة';
    }
    return null;
}

/**
 * تفريع الأضابير (قرار المنتج):
 * - أول طعن من نوعه (اعتراض / استئناف) يمتد داخل الإضبارة الأساس.
 * - طعن لاحق من طرف آخر مؤهل → إضبارة مخزن مستقلة (بطاقة + رقم مرتبط) — يختار المستخدم الأطراف.
 * - لا ضمّ معترض لاحق لنفس المرحلة، ولا مسار «استئناف متقابل» كبديل عن الاستقلال.
 *
 * مسار إضافي سابق: انقلاب المراكز بعد اعتراض مع رول استئناف مستخرج.
 */
import type {
    CaseLinkRecord,
    FileData,
    IndependentChallengeLink,
} from '@/app/components/lawyer/lawyerShared/fileDataTypes';
import type { CaseStage, TimelineEvent } from '@/app/components/lawyer/lawyerShared/stageTimelineTypes';
import { isGhayabiObjectionAppealType } from '@/app/domain/lawsuit/challengeAppellantEligibility';
import {
    classifyAbsentObjectionOutcome,
    plaintiffMustFileNewOriginalAppeal,
} from '@/app/domain/lawsuit/objectionAppealConsequence';
import { getLocalTodayYmd } from '@/app/utils/localYmd';

export const INDEPENDENT_CHALLENGE_LINK_REASON = 'طعن مستقل — طرف لاحق';

export type { IndependentChallengeLink };

function stageNameOf(stage?: CaseStage | null): string {
    return String(stage?.stageName ?? stage?.name ?? '').trim();
}

export function isAbsentObjectionStageName(name: string): boolean {
    const n = String(name ?? '').trim();
    if (!n || n.includes('اعتراض الغير')) return false;
    return (
        n.includes('اعتراض على الحكم الغيابي')
        || n.includes('الاعتراض على الحكم الغيابي')
        || n.includes('اعتراض غيابي')
        || (n.includes('اعتراض') && n.includes('غيابي'))
    );
}

function isExtractedAppealStageName(name: string): boolean {
    if (!name) return false;
    if (name.includes('اعتراض الغير') || name.includes('حكم الغير')) return false;
    if (name.includes('إعادة المحاكمة') || name.includes('إعادة محاكمة')) return false;
    if (isAbsentObjectionStageName(name)) return false;
    return name.includes('استئناف') && !name.includes('التمييز');
}

function isCassationStageName(name: string): boolean {
    return name === 'التمييز' || (name.includes('تمييز') && !name.includes('استئناف'));
}

function isSequentialHopSource(name: string): boolean {
    return isExtractedAppealStageName(name) || isCassationStageName(name);
}

function isOpenChallengeStage(stage?: CaseStage | null): boolean {
    if (!stage) return false;
    if (stage.status === 'locked' || stage.status === 'completed') return false;
    if (String(stage.finalDecision ?? '').trim()) return false;
    return true;
}

export function findExtractedAppealStageIndex(stages?: CaseStage[] | null): number {
    if (!Array.isArray(stages)) return -1;
    return stages.findIndex((stage) => isExtractedAppealStageName(stageNameOf(stage)));
}

export function findOpenAbsentObjectionStageIndex(stages?: CaseStage[] | null): number {
    if (!Array.isArray(stages)) return -1;
    return stages.findIndex((stage) => {
        if (!isAbsentObjectionStageName(stageNameOf(stage))) return false;
        return isOpenChallengeStage(stage);
    });
}

export function findOpenExtractedAppealStageIndex(stages?: CaseStage[] | null): number {
    if (!Array.isArray(stages)) return -1;
    return stages.findIndex((stage) => {
        if (!isExtractedAppealStageName(stageNameOf(stage))) return false;
        return isOpenChallengeStage(stage);
    });
}

/**
 * انقلاب المراكز: من مرحلة الاعتراض بعد إبطال الحكم الغيابي
 * يصبح المدعي مستأنفاً ضد المعترض بينما يبقى مستأنفاً عليه في الرول المستخرج.
 */
export function hasIndependentChallengeCenterInversion(params: {
    sourceStage?: CaseStage | null;
}): boolean {
    const source = params.sourceStage;
    if (!source || !isAbsentObjectionStageName(stageNameOf(source))) return false;
    const outcome = classifyAbsentObjectionOutcome(
        source.finalDecision ?? source.lastJudgmentType ?? null,
    );
    return plaintiffMustFileNewOriginalAppeal(outcome);
}

/**
 * هل يجب فتح إضبارة مستقلة بدل الامتداد/الضم؟
 * - اعتراض غيابي لاحق وأخرى قائمة مفتوحة
 * - استئناف لاحق ورول استئناف مفتوح قائم
 * - انقلاب مراكز الاعتراض مع رول مستخرج (السلوك السابق)
 */
export function shouldSpawnIndependentChallengeDossier(params: {
    stages?: CaseStage[] | null;
    sourceStage?: CaseStage | null;
    appealType?: string | null;
}): boolean {
    const appealType = String(params.appealType ?? '').trim();
    if (!appealType) return false;
    if (appealType.includes('إعادة محاكمة') || appealType.includes('إعادة المحاكمة')) {
        return false;
    }

    const isObjection =
        isGhayabiObjectionAppealType(appealType)
        || (appealType.includes('اعتراض') && !appealType.includes('استئناف'));

    if (isObjection) {
        return findOpenAbsentObjectionStageIndex(params.stages) >= 0;
    }

    if (appealType.includes('تمييز')) {
        return false;
    }

    if (appealType.includes('استئناف')) {
        const openAppeal = findOpenExtractedAppealStageIndex(params.stages);
        if (openAppeal >= 0) {
            const sourceId = String(params.sourceStage?.id ?? '');
            const open = params.stages?.[openAppeal];
            if (!sourceId || !open || String(open.id) !== sourceId) {
                return true;
            }
        }
        const sourceName = stageNameOf(params.sourceStage);
        if (isSequentialHopSource(sourceName)) return false;
        const extractedIndex = findExtractedAppealStageIndex(params.stages);
        if (extractedIndex < 0) return false;
        const extracted = params.stages?.[extractedIndex];
        const sourceId = String(params.sourceStage?.id ?? '');
        if (sourceId && extracted && String(extracted.id) === sourceId) return false;
        return hasIndependentChallengeCenterInversion({ sourceStage: params.sourceStage });
    }

    return false;
}

export function allocateLawsuitFileId(existing: Array<{ id?: number | string }>, now = Date.now()): number {
    const ids = new Set(
        existing
            .map((file) => Number(file.id))
            .filter((id) => Number.isFinite(id)),
    );
    let id = now;
    while (ids.has(id)) id += 1;
    return id;
}

function fileIdOf(file: FileData): number {
    const id = Number(file.id);
    return Number.isFinite(id) ? id : 0;
}

function buildLinkRecord(params: {
    originFileId: number;
    peerFileId: number;
    peerCaseNo: string;
    date: string;
}): CaseLinkRecord {
    return {
        id: `ind_ch_${params.originFileId}_${params.peerFileId}_${params.date}`,
        peerFileId: params.peerFileId,
        peerCaseNo: params.peerCaseNo,
        linkDate: params.date,
        reason: INDEPENDENT_CHALLENGE_LINK_REASON,
        isExternal: false,
        originFileId: params.originFileId,
        peerDossierKind: 'lawsuit',
    };
}

function lockSourceStage(params: {
    sourceStage: CaseStage;
    filingDate: string;
    newCaseNumber: string;
    appealType: string;
    createdFileId: number;
}): CaseStage {
    const event: TimelineEvent = {
        id: `independent_challenge_${params.createdFileId}_${params.filingDate}`,
        type: 'milestone',
        date: params.filingDate,
        title: 'إنشاء طعن استئنافي مستقل',
        details: `أُنشئت إضبارة ${params.appealType} مستقلة برقم ${params.newCaseNumber || '—'} دون تعديل رول الاستئناف المستخرج في هذا الملف.`,
        isSystemLog: true,
        isNew: true,
    };
    return {
        ...params.sourceStage,
        status: 'locked',
        isPleadingsClosed: true,
        awaitingOpponentAppeal: false,
        timeline: [event, ...(params.sourceStage.timeline ?? [])],
    };
}

export function applyIndependentChallengeSpawn(params: {
    sourceFile: FileData;
    sourceStageIndex: number;
    createdId: number;
    appealStage: CaseStage;
    appealType: string;
    filingDate: string;
    newCaseNumber: string;
    newCourt?: string;
}): { sourceFile: FileData; createdFile: FileData } {
    const filingDate = params.filingDate || getLocalTodayYmd();
    const sourceId = fileIdOf(params.sourceFile);
    const sourceStages = [...(params.sourceFile.stages ?? [])];
    const sourceStage = sourceStages[params.sourceStageIndex];
    if (!sourceStage) {
        throw new Error('[domain_lawsuit:applyindependentch] applyIndependentChallengeSpawn: source stage missing');
    }

    const relatedAppealIndex = findExtractedAppealStageIndex(sourceStages);
    const relatedAppealStageId =
        relatedAppealIndex >= 0 ? String(sourceStages[relatedAppealIndex]?.id ?? '') : undefined;

    sourceStages[params.sourceStageIndex] = lockSourceStage({
        sourceStage,
        filingDate,
        newCaseNumber: params.newCaseNumber,
        appealType: params.appealType,
        createdFileId: params.createdId,
    });

    const sourceCaseNo = String(params.sourceFile.caseNo ?? '').trim();
    const createdCaseNo = String(params.newCaseNumber || params.appealStage.caseNo || '').trim();
    const sourceLink = buildLinkRecord({
        originFileId: sourceId,
        peerFileId: params.createdId,
        peerCaseNo: createdCaseNo || '—',
        date: filingDate,
    });
    const createdLink = buildLinkRecord({
        originFileId: params.createdId,
        peerFileId: sourceId,
        peerCaseNo: sourceCaseNo,
        date: filingDate,
    });

    const sourceFile: FileData = {
        ...params.sourceFile,
        stages: sourceStages,
        activeStageIndex: params.sourceStageIndex,
        caseLinks: [...(params.sourceFile.caseLinks ?? []), sourceLink],
    };

    const link: IndependentChallengeLink = {
        sourceFileId: sourceId,
        sourceCaseNo,
        sourceStageName: stageNameOf(sourceStage),
        ...(relatedAppealStageId ? { relatedAppealStageId } : {}),
    };

    const appealStageName = stageNameOf(params.appealStage) || 'الاستئناف';
    const appealCourt = String(params.newCourt ?? '').trim();
    const createdFile: FileData = {
        id: params.createdId,
        type: 'lawsuit',
        status: 'active',
        caseNo: createdCaseNo,
        court: appealCourt,
        judge: params.appealStage.judge,
        docType: params.appealStage.docType ?? params.sourceFile.docType,
        parties: params.appealStage.parties ?? [],
        representedParty: params.sourceFile.representedParty ?? undefined,
        currentStage: appealStageName,
        history: [
            {
                id: `ind_open_${params.createdId}`,
                type: 'milestone',
                date: filingDate,
                title: `فتح إضبارة ${appealStageName}`,
                details: `طعن مستقل عن الإضبارة ${sourceCaseNo || '—'} — رول الاستئناف المستخرج لم يُعدَّل.`,
                isNew: true,
            },
        ],
        notes: [],
        images: [],
        date: filingDate,
        parentId: sourceId,
        independentChallengeLink: link,
        caseLinks: [createdLink],
        stages: [
            {
                ...params.appealStage,
                caseNo: createdCaseNo,
                court: appealCourt,
            },
        ],
        activeStageIndex: 0,
        lawsuitJurisdiction: params.sourceFile.lawsuitJurisdiction,
        applicableLaw: params.sourceFile.applicableLaw,
        disputeIntegrity: params.sourceFile.disputeIntegrity,
        claimValue: params.sourceFile.claimValue,
        isUndeterminedValue: params.sourceFile.isUndeterminedValue,
        isFixedFee: params.sourceFile.isFixedFee,
        clientPhone: params.sourceFile.clientPhone,
        feesTotal: '0',
        feesPaid: '0',
    };

    return { sourceFile, createdFile };
}

export function readIndependentChallengeLink(
    file: FileData | Record<string, unknown> | null | undefined,
): IndependentChallengeLink | null {
    const raw = file && typeof file === 'object' ? (file as FileData).independentChallengeLink : undefined;
    if (!raw || typeof raw !== 'object') return null;
    const sourceFileId = Number(raw.sourceFileId);
    if (!Number.isFinite(sourceFileId)) return null;
    return {
        sourceFileId,
        sourceCaseNo: String(raw.sourceCaseNo ?? '').trim(),
        sourceStageName: String(raw.sourceStageName ?? '').trim(),
        relatedAppealStageId: raw.relatedAppealStageId ? String(raw.relatedAppealStageId) : undefined,
    };
}

export function areIndependentChallengePeers(
    left?: FileData | null,
    right?: FileData | null,
): boolean {
    if (!left || !right) return false;
    const leftId = Number(left.id);
    const rightId = Number(right.id);
    if (!Number.isFinite(leftId) || !Number.isFinite(rightId) || leftId === rightId) return false;
    const leftLink = readIndependentChallengeLink(left);
    const rightLink = readIndependentChallengeLink(right);
    if (leftLink && Number(leftLink.sourceFileId) === rightId) return true;
    if (rightLink && Number(rightLink.sourceFileId) === leftId) return true;
    return false;
}

export type IndependentChallengeSpawnInput = {
    sourceFileId: number;
    sourceStages: CaseStage[];
    sourceStageIndex: number;
    appealStage: CaseStage;
    appealType: string;
    filingDate: string;
    newCaseNumber: string;
    newCourt?: string;
    /** نسخة الإضبارة المفتوحة — لا يعتمد الإنشاء على قائمة مخزن قد تكون متأخرة */
    sourceFile?: FileData;
};

import type { FileData } from './lawsuitFileTypes';
import {
    rebuildActiveSegmentInIndex,
    type LawsuitLifecycleIndex,
} from '@/app/domain/lawsuit/lawsuitLifecycleIndex';
import {
    mirrorLawsuitSegmentsSafe,
    persistLawsuitActiveSegment,
    persistLawsuitLifecycleIndex,
} from '@/app/domain/lawsuit/lawsuitSegmentPersist';
import { stageLawsuitJournalRecords, mergeLawsuitJournalInto } from '@/app/domain/lawsuit/lawsuitWriteJournal';
import { mergePendingLawsuitCreatesInto } from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import {
    excludeLawsuitIdsBySet,
    lawsuitActiveIdSet,
    mergeRicherLawsuitActive,
    parseLawsuitActiveFiles,
} from '@/app/domain/lawsuit/lawsuitActiveDurability';
import { collectHeldOutOfActiveIds } from '@/app/domain/lawsuit/lawsuitFilesStatePolicy';
import { readLawsuitLifecycleHeldFenceIds } from '@/app/domain/lawsuit/lawsuitLifecycleMutationFence';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';

export type LawsuitActivePersistOptions = {
    allowVerifiedEmpty?: boolean;
    allowShrink?: boolean;
};

export type LawsuitActivePersistResult = {
    /** نجحت كتابة المقطع النشط — يُسمح بعدها بالفهرس والمرآة */
    ok: boolean;
    active: FileData[];
};

/**
 * اثبات تقلّص نشط: كل معرّف أُزيل من القرص يجب أن يكون في سلة/أرشيف/tombstone
 * وليس في المقترح النشط. بدون ذلك لا يُسمح بـ allowShrink.
 */
function proveLawsuitActiveShrink(
    proposed: FileData[],
    diskActive: FileData[],
    trash: FileData[] | null | undefined,
    archived: FileData[] | null | undefined,
): { ok: boolean; recovered: FileData[] } {
    const proposedIds = lawsuitActiveIdSet(proposed);
    const held = collectHeldOutOfActiveIds({
        trash,
        archived,
        includeTombstones: true,
        preferActiveIds: proposed,
    });
    const illicit: FileData[] = [];
    for (const row of diskActive) {
        const id = String(row.id ?? '').trim();
        if (!id || proposedIds.has(id)) continue;
        if (held.has(id)) continue;
        illicit.push(row);
    }
    if (illicit.length === 0) {
        return { ok: true, recovered: proposed };
    }
    return {
        ok: false,
        recovered: mergeRicherLawsuitActive(proposed, illicit),
    };
}

/**
 * بوابة الكتابة الموحّدة للمقطع النشط + الفهرس + المرآة.
 * كل مسارات الحفظ (إنشاء، autosave، تعديل إضبارة) تمر من هنا.
 */
export function persistLawsuitActiveBundle(input: {
    active: FileData[];
    index: LawsuitLifecycleIndex;
    archived?: FileData[] | null;
    trash?: FileData[] | null;
    options?: LawsuitActivePersistOptions;
}): LawsuitActivePersistResult {
    /*
     * ادمج المعلّق/السجل دائماً — حتى مع allowShrink (أرشفة/سلة).
     * المسارات تلك تُزيل المعرّف من overlay قبل الكتابة؛ بدون الدمج
     * تُفقد إضبارة منشأة ما زالت في pending بينما المدنية تُكتب وحدها.
     */
    /*
     * لا تمنح pending/WAL القديم حق إعادة ملف خرج من النشط. النشط الذي مرره
     * المستدعي وحده يملك أولوية active؛ أما overlay لم يُنظَّف بسبب مفتاح بارد
     * فيُحجب بحالة السلة/الأرشيف/الفهرس.
     */
    const fencedOutOfActive = readLawsuitLifecycleHeldFenceIds();
    const baseActive = excludeLawsuitIdsBySet(input.active, fencedOutOfActive);
    const heldAgainstOverlays = collectHeldOutOfActiveIds({
        trash: input.trash,
        archived: input.archived,
        index: input.index,
        includeTombstones: true,
        preferActiveIds: baseActive,
    });
    for (const id of fencedOutOfActive) heldAgainstOverlays.add(id);
    let active = excludeLawsuitIdsBySet(
        mergeLawsuitJournalInto(mergePendingLawsuitCreatesInto(baseActive)),
        heldAgainstOverlays,
    );
    if (active.length > 0) {
        stageLawsuitJournalRecords(active);
    }

    const diskActive = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
    );
    const preferActive = lawsuitActiveIdSet(active);
    const heldOutOfActive = collectHeldOutOfActiveIds({
        trash: input.trash,
        archived: input.archived,
        includeTombstones: true,
        preferActiveIds: preferActive,
    });

    let writeOptions = input.options;
    if (writeOptions?.allowShrink || writeOptions?.allowVerifiedEmpty) {
        const proof = proveLawsuitActiveShrink(
            active,
            diskActive,
            input.trash,
            input.archived,
        );
        if (!proof.ok) {
            /*
             * تقلّص بلا إثبات نقل — ادمج المفقود وارفض التفريغ.
             * يمنع allowShrink الأعمى من مسار الدمج/الإقلاع.
             */
            active = proof.recovered;
            writeOptions = {
                ...writeOptions,
                allowShrink: false,
                allowVerifiedEmpty: false,
            };
        } else if (active.length === 0 && diskActive.length > 0) {
            /*
             * تفريغ كامل: فقط إن كل معرّفات القرص held (سلة/أرشيف/tombstone).
             */
            let allHeld = true;
            for (const row of diskActive) {
                const id = String(row.id ?? '').trim();
                if (id && !heldOutOfActive.has(id)) {
                    allHeld = false;
                    break;
                }
            }
            if (!allHeld || !writeOptions.allowVerifiedEmpty) {
                active = excludeLawsuitIdsBySet(diskActive, heldOutOfActive);
                writeOptions = {
                    ...writeOptions,
                    allowShrink: active.length < diskActive.length,
                    allowVerifiedEmpty: active.length === 0,
                };
                if (active.length === 0 && !input.options?.allowVerifiedEmpty) {
                    return { ok: false, active: diskActive };
                }
            }
        }
    }

    const activeWritten = persistLawsuitActiveSegment(active, writeOptions);
    if (!activeWritten) {
        return { ok: false, active };
    }
    /*
     * اكتب الفهرس/المرآة من القائمة التي استقرّت على القرص لا من المقترح —
     * writeJsonArray قد يدمج الأغنى، والمرآة بالقائمة الأفقر كانت تسمّم lawyer_files.
     *
     * عند النقل العمدي (allowShrink): لا تُعد إحياء معرّفات خارج المقترح النشط
     * (سلة/أرشيف/tombstone) — لكن تكرار سلة∩نشط لا يُخرج النشط.
     */
    const diskAfter = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
    );
    const heldAfter = collectHeldOutOfActiveIds({
        trash: input.trash,
        archived: input.archived,
        includeTombstones: true,
        preferActiveIds: lawsuitActiveIdSet(active),
    });
    const diskSansHeld = excludeLawsuitIdsBySet(diskAfter, heldAfter);
    const canonical =
        writeOptions?.allowShrink || writeOptions?.allowVerifiedEmpty
            ? excludeLawsuitIdsBySet(
                  diskSansHeld.length > 0 ? diskSansHeld : active,
                  heldAfter,
              )
            : diskSansHeld.length > 0
              ? mergeRicherLawsuitActive(active, diskSansHeld)
              : active;
    /*
     * حارس أخير: لا تسمح لمرآة/فهرس فارغين إذا كان المقترح أو القرص يحمل بيانات
     * ولم يُطلب تفريغ موثّق صراحةً.
     */
    if (
        canonical.length === 0 &&
        (active.length > 0 || diskActive.length > 0) &&
        !writeOptions?.allowVerifiedEmpty
    ) {
        const fallback =
            active.length > 0 ? active : excludeLawsuitIdsBySet(diskActive, heldAfter);
        if (fallback.length > 0) {
            const index = rebuildActiveSegmentInIndex(input.index, fallback);
            persistLawsuitLifecycleIndex(index);
            mirrorLawsuitSegmentsSafe(fallback, input.archived ?? null, input.trash ?? null);
            return { ok: true, active: fallback };
        }
    }
    const index =
        canonical.length === input.active.length
            ? input.index
            : rebuildActiveSegmentInIndex(input.index, canonical);
    persistLawsuitLifecycleIndex(index);
    mirrorLawsuitSegmentsSafe(canonical, input.archived ?? null, input.trash ?? null);
    return { ok: true, active: canonical };
}

/**
 * تحديث الفهرس + المرآة دون إعادة كتابة المقطع النشط
 * (حذف نهائي من السلة، تحميل مقاطع كسولة).
 */
export function persistLawsuitLifecycleMirrorBundle(input: {
    active: FileData[];
    index: LawsuitLifecycleIndex;
    archived?: FileData[] | null;
    trash?: FileData[] | null;
}): void {
    persistLawsuitLifecycleIndex(input.index);
    mirrorLawsuitSegmentsSafe(input.active, input.archived ?? null, input.trash ?? null);
}

