function emptySegments(): LawsuitFileSegments {
    try {
        return reloadLawsuitFilesFromStorage();
    } catch {
        return {
            active: [],
            archived: null,
            trash: null,
            index: {
                v: 1,
                entries: {},
                counts: { active: 0, archived: 0, trash: 0 },
            },
        };
    }
}

function parseFilesArray(raw: string | null | undefined): FileData[] {
    if (!raw) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? (parsed as FileData[]) : [];
    } catch {
        return [];
    }
}

async function safeGetItem(key: string): Promise<string | null> {
    try {
        return await SecureStoreService.getItem(key);
    } catch {
        return null;
    }
}

async function safePeek(key: string): Promise<string | null> {
    try {
        return await SecureStoreService.peekRawFromDisk(key);
    } catch {
        return null;
    }
}

async function safeGetFromDisk(key: string): Promise<string | null> {
    try {
        return await SecureStoreService.getItemFromDisk(key);
    } catch {
        return null;
    }
}

function readLegacyLocalStorageArrays(): FileData[] {
    if (typeof window === 'undefined') return [];
    const keys = [LAWSUIT_FILES_STORAGE_KEY, ...LAWSUIT_FILES_STORAGE_KEYS_LEGACY];
    const merged: FileData[] = [];
    const seen = new Set<string>();
    try {
        for (const key of keys) {
            const raw = readSecureOrDrainLegacySync(key);
            if (!raw || raw.startsWith(ENCRYPTED_PREFIX)) continue;
            const rows = parseFilesArray(raw);
            for (const row of rows) {
                const id = String(row?.id ?? '');
                if (!id || seen.has(id)) continue;
                seen.add(id);
                merged.push(row);
            }
        }
    } catch {
        /* ignore */
    }
    return merged;
}

async function readEmergencyBackupArrays(): Promise<FileData[]> {
    const keys = [
        `emergency_backup_${LAWSUIT_FILES_STORAGE_KEY}`,
        `backup_${LAWSUIT_FILES_STORAGE_KEY}`,
        `emergency_backup_${LAWSUIT_FILES_ACTIVE_KEY}`,
        `backup_${LAWSUIT_FILES_ACTIVE_KEY}`,
    ];
    for (const key of keys) {
        const raw = await safeGetItem(key);
        if (!raw) continue;
        try {
            const parsed: unknown = JSON.parse(raw);
            if (Array.isArray(parsed)) return parsed as FileData[];
            if (parsed && typeof parsed === 'object' && 'data' in parsed) {
                const data = (parsed as { data: unknown }).data;
                if (Array.isArray(data)) return data as FileData[];
            }
        } catch {
            /* continue */
        }
    }
    return [];
}

function hasRecoveredRows(segments: LawsuitFileSegments): boolean {
    return (
        segments.active.length > 0 ||
        segments.index.counts.active > 0 ||
        segments.index.counts.archived > 0 ||
        segments.index.counts.trash > 0
    );
}

async function applyRecoveredPayload(
    files: FileData[],
    source: LawsuitRecoveryResult['source'],
): Promise<LawsuitRecoveryResult | null> {
    if (!Array.isArray(files) || files.length === 0) return null;
    try {
        await ensureLawsuitDossierTombstonesReadable();
        const stripped = excludeTombstonedLawsuitFiles(files);
        if (stripped.length === 0) return null;
        applyLawsuitMonolithicMergeToSegments(stripped);
    } catch {
        return null;
    }

    /*
     * التحقّق يقرأ المقاطع فوراً بعد الدمج. تثبيت الديمومة يُفرّغ المرآة المتزامنة
     * مؤقتاً أثناء إعادة الكتابة، فقراءة ما بعده كانت تُبلّغ فشل استعادة زائفاً
     * ثم تُنسب البيانات لمصدر لاحق (السحابة).
     */
    let segments = reloadLawsuitFilesFromStorage();
    if (!hasRecoveredRows(segments)) return null;

    try {
        await awaitLawsuitWorkspaceCommit({ timeoutMs: 8_000 });
        const committed = reloadLawsuitFilesFromStorage();
        if (hasRecoveredRows(committed) && committed.active.length >= segments.active.length) {
            segments = committed;
        }
    } catch {
        /* الديمومة أفضل جهد — الدمج والتحقّق نجحا بالفعل */
    }
    return {
        ok: true,
        segments,
        source,
        diagnosis: {
            diskCipherPresent: false,
            diskActiveCount: segments.active.length,
            memoryActiveCount: segments.active.length,
            monolithicCount: files.length,
            backupCount: 0,
            cloudCount: 0,
            legacyLocalCount: 0,
            decryptLikelyBroken: false,
        },
        message:
            segments.active.length > 0
                ? `تمت استعادة ${segments.active.length} إضبارة نشطة`
                : 'تمت الاستعادة — راجع الأرشيف أو السلة من الفلاتر',
    };
}

/**
 * استعادة جذرية متعددة المصادر — لا ترمي أبداً.
 */
export async function recoverLawsuitWorkspaceFromLocalDisk(
    options?: LawsuitRecoveryOptions,
): Promise<LawsuitRecoveryResult> {
    const diagnosis: LawsuitRecoveryDiagnosis = {
        diskCipherPresent: false,
        diskActiveCount: 0,
        memoryActiveCount: 0,
        monolithicCount: 0,
        backupCount: 0,
        cloudCount: 0,
        legacyLocalCount: 0,
        decryptLikelyBroken: false,
    };

    const fail = (message: string): LawsuitRecoveryResult => ({
        ok: false,
        segments: emptySegments(),
        source: 'none',
        diagnosis,
        message,
    });

    const includeCloud = options?.includeCloud !== false;
    const fullPersistReady = options?.fullPersistReady === true;

    try {
        try {
            await SecureStoreService.ensureLawsuitKeysReady();
        } catch {
            /* continue */
        }
        if (fullPersistReady) {
            try {
                await SecureStoreService.ensurePersistedReady();
            } catch {
                /* continue */
            }
        }

        for (const key of LAWSUIT_SEGMENT_WARM_KEYS) {
            await safeGetItem(key);
        }

        const peeks = await Promise.all(
            [...LAWSUIT_SEGMENT_WARM_KEYS].map(async (key) => ({
                key,
                raw: await safePeek(key),
            })),
        );
        diagnosis.diskCipherPresent = peeks.some((p) => p.raw?.startsWith(ENCRYPTED_PREFIX));

        /*
         * معلّقات الإنشاء + سجل WAL (SecureStore مشفّر، مع ترحيل بقايا صريحة).
         * كانت تُتجاهل فتظهر الخزنة فارغة رغم وجود إضبارة معلّقة.
         */
        try {
            const {
                flushLawsuitDurabilityOverlaysToActive,
                mergeLawsuitDurabilityOverlaysInto,
                lawsuitDurabilityHasUncommittedWrites,
            } = await import('@/app/domain/lawsuit/lawsuitDurabilityOverlay');
            const { listPendingLawsuitCreates } = await import(
                '@/app/domain/lawsuit/lawsuitPendingCreateStore',
            );
            const pending = listPendingLawsuitCreates();
            if (lawsuitDurabilityHasUncommittedWrites()) {
                await flushLawsuitDurabilityOverlaysToActive();
                let bootPending = reloadLawsuitFilesFromStorage();
                bootPending = {
                    ...bootPending,
                    active: mergeLawsuitDurabilityOverlaysInto(bootPending.active),
                };
                if (bootPending.active.length > 0) {
                    return {
                        ok: true,
                        segments: bootPending,
                        source: 'emergency',
                        diagnosis: {
                            ...diagnosis,
                            diskActiveCount: bootPending.active.length,
                            memoryActiveCount: bootPending.active.length,
                            legacyLocalCount: pending.length,
                        },
                        message: `تمت استعادة ${bootPending.active.length} إضبارة (منها معلّقات إنشاء)`,
                    };
                }
                const appliedPending = await applyRecoveredPayload(pending, 'emergency');
                if (appliedPending) {
                    return {
                        ...appliedPending,
                        diagnosis: {
                            ...diagnosis,
                            ...appliedPending.diagnosis,
                            legacyLocalCount: pending.length,
                        },
                    };
                }
            }
        } catch {
            /* ignore */
        }

        const diskActivePlain = parseFilesArray(await safeGetFromDisk(LAWSUIT_FILES_ACTIVE_KEY));
        const diskMonoPlain = parseFilesArray(await safeGetFromDisk(LAWSUIT_FILES_STORAGE_KEY));
        diagnosis.diskActiveCount = diskActivePlain.length;
        diagnosis.memoryActiveCount = parseFilesArray(
            readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
        ).length;

        if (diskActivePlain.length > diagnosis.memoryActiveCount) {
            try {
                SecureStoreService.setItemSync(
                    LAWSUIT_FILES_ACTIVE_KEY,
                    JSON.stringify(diskActivePlain),
                    { allowShrink: true },
                );
            } catch {
                /* ignore */
            }
        }

        let boot = reloadLawsuitFilesFromStorage();
        try {
            const { mergeLawsuitDurabilityOverlaysInto } = await import(
                '@/app/domain/lawsuit/lawsuitDurabilityOverlay',
            );
            boot = {
                ...boot,
                active: mergeLawsuitDurabilityOverlaysInto(boot.active),
            };
        } catch {
            /* ignore */
        }
        if (bootHasLawsuitRecords(boot) || boot.active.length > 0) {
            return {
                ok: true,
                segments: boot,
                source: 'active',
                diagnosis: {
                    ...diagnosis,
                    diskActiveCount: boot.active.length,
                    memoryActiveCount: boot.active.length,
                },
                message:
                    boot.active.length > 0
                        ? `تمت استعادة ${boot.active.length} إضبارة نشطة`
                        : 'المقاطع على القرص هي مصدر الحقيقة — لا استيراد من المرآة',
            };
        }

        const monoSync = loadLawsuitFilesRaw() as FileData[];
        diagnosis.monolithicCount = monoSync.length;
        if (monoSync.length > 0) {
            const applied = await applyRecoveredPayload(monoSync, 'monolithic');
            if (applied) return { ...applied, diagnosis: { ...diagnosis, ...applied.diagnosis } };
        }

        if (diskMonoPlain.length > 0) {
            const applied = await applyRecoveredPayload(diskMonoPlain, 'monolithic');
            if (applied) return { ...applied, diagnosis: { ...diagnosis, ...applied.diagnosis } };
        }

        try {
            const { listDossierBackups } = await import(
                '@/app/services/dossierPersistence/dossierBackupStore'
            );
            const backups = await listDossierBackups('lawsuit');
            diagnosis.backupCount = backups.reduce((n, b) => n + (b.payload?.length ?? 0), 0);
            for (const backup of backups) {
                const rows = backup.payload as FileData[];
                if (!rows.length) continue;
                const applied = await applyRecoveredPayload(rows, 'backup');
                if (applied) {
                    return {
                        ...applied,
                        diagnosis: { ...diagnosis, backupCount: diagnosis.backupCount },
                    };
                }
            }
        } catch {
            /* ignore */
        }

        const emergency = await readEmergencyBackupArrays();
        if (emergency.length > 0) {
            const applied = await applyRecoveredPayload(emergency, 'emergency');
            if (applied) return { ...applied, diagnosis };
        }

        const legacy = readLegacyLocalStorageArrays();
        diagnosis.legacyLocalCount = legacy.length;
        if (legacy.length > 0) {
            const applied = await applyRecoveredPayload(legacy, 'legacy-ls');
            if (applied) return { ...applied, diagnosis };
        }

        if (includeCloud) {
            try {
                const { restoreLastWorkCloudCheckpoint } = await import(
                    '@/app/services/cloud/workCloudCheckpoint'
                );
                const restored = await restoreLastWorkCloudCheckpoint();
                if (restored.applied && restored.lawsuits > 0) {
                    boot = reloadLawsuitFilesFromStorage();
                    diagnosis.cloudCount = boot.active.length + boot.index.counts.archived;
                    if (boot.active.length > 0 || boot.index.counts.active > 0 || boot.index.counts.archived > 0) {
                        return {
                            ok: true,
                            segments: boot,
                            source: 'cloud',
                            diagnosis,
                            message: `تمت الاستعادة من آخر نقطة سحابية — ${boot.active.length} إضبارة`,
                        };
                    }
                }
            } catch {
                /* ignore */
            }
            try {
                const { performCloudSyncBucket } = await import('@/app/services/cloudSyncEngine');
                const pulled = await performCloudSyncBucket(LAWSUIT_FILES_STORAGE_KEY);
                /* سلة معطّلة أو مزامنة ممتنعة = لا شيء نزل من الشبكة؛ لا تنسب النتيجة للسحابة */
                if (pulled.ok && pulled.skipped !== true) {
                    boot = reloadLawsuitFilesFromStorage();
                    diagnosis.cloudCount = boot.active.length + boot.index.counts.archived;
                    if (
                        boot.active.length > 0 ||
                        boot.index.counts.active > 0 ||
                        boot.index.counts.archived > 0
                    ) {
                        return {
                            ok: true,
                            segments: boot,
                            source: 'cloud',
                            diagnosis,
                            message:
                                boot.active.length > 0
                                    ? `تمت الاستعادة من السحابة — ${boot.active.length} إضبارة`
                                    : 'تمت الاستعادة من السحابة — راجع الأرشيف/السلة',
                        };
                    }
                }
            } catch {
                /* cloud may be offline / unauthenticated */
            }
        }

        diagnosis.decryptLikelyBroken =
            diagnosis.diskCipherPresent &&
            diagnosis.diskActiveCount === 0 &&
            diagnosis.monolithicCount === 0 &&
            diagnosis.backupCount === 0;

        if (diagnosis.decryptLikelyBroken) {
            return fail(
                'وُجدت بيانات مشفّرة محلياً لكن مفتاح الفكّ غير جاهز — أعد فتح التطبيق أو استورد نسخة العمل من الإعدادات. السحابة اختيارية للمزامنة فقط',
            );
        }

        if (diagnosis.backupCount === 0 && diagnosis.cloudCount === 0 && diagnosis.legacyLocalCount === 0) {
            return fail(
                'لا توجد دعاوى في التخزين المحلي ولا في النسخ الاحتياطية — استورد نسخة من الإعدادات إن توفّرت',
            );
        }

        return fail('تعذّر تطبيق بيانات الاستعادة — جرّب نسخة احتياطية من الإعدادات');
    } catch {
        return fail('حدث خطأ أثناء الاستعادة — أعد المحاولة أو استورد نسخة من الإعدادات');
    }
}

import type { FileData } from './lawsuitFileTypes';
import { mergeRicherLawsuitActive } from '@/app/domain/lawsuit/lawsuitActiveDurability';
import { awaitLawsuitWorkspaceCommit } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import SecureStoreService from '@/app/services/SecureStoreService';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import { markLawsuitJournaledThisPage } from '@/app/domain/lawsuit/lawsuitPageWriteGuard';
import {
    clearSecureJsonValue,
    readSecureJsonRawSync,
    writeSecureJsonValue,
} from '@/app/services/storage/syncSecureJson';

/**
 * سجل كتابة append-only — مشفّر في SecureStore (نسخ FileData: أسماء وأرقام دعاوى).
 * ليس في قشرة الإقلاع ولا PROTECTED_WARM (الحمولة قد تكون ثقيلة).
 * `flushLawsuitJournalToActive` يفكّ المفتاح إن كان بارداً ثم يدمج.
 * يُمسح فقط بعد إثبات القرص.
 */
export const LAWSUIT_WRITE_JOURNAL_KEY = 'hami_lawsuit_write_journal_v1';

const JOURNAL_CAP = 80;

export type LawsuitWriteJournalEntry = {
    v: 1;
    fileId: string;
    file: FileData;
    ts: number;
};

function parseEntries(raw: string | null): LawsuitWriteJournalEntry[] {
    if (!raw?.trim()) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(
            (row): row is LawsuitWriteJournalEntry =>
                !!row &&
                typeof row === 'object' &&
                (row as LawsuitWriteJournalEntry).v === 1 &&
                typeof (row as LawsuitWriteJournalEntry).fileId === 'string' &&
                !!(row as LawsuitWriteJournalEntry).file,
        );
    } catch {
        return [];
    }
}

function readRaw(): LawsuitWriteJournalEntry[] {
    return parseEntries(readSecureJsonRawSync(LAWSUIT_WRITE_JOURNAL_KEY));
}

function writeRaw(entries: LawsuitWriteJournalEntry[]): void {
    if (entries.length === 0) {
        if (SecureStoreService.isUnreadSync(LAWSUIT_WRITE_JOURNAL_KEY)) return;
        clearSecureJsonValue(LAWSUIT_WRITE_JOURNAL_KEY);
        return;
    }
    writeSecureJsonValue(LAWSUIT_WRITE_JOURNAL_KEY, entries);
}

export function clearLawsuitWriteJournalForTests(): void {
    clearSecureJsonValue(LAWSUIT_WRITE_JOURNAL_KEY);
}

export async function settleLawsuitJournalPersist(): Promise<void> {
    await SecureStoreService.waitForPendingSetItem(LAWSUIT_WRITE_JOURNAL_KEY);
}

export function listLawsuitJournalEntries(): LawsuitWriteJournalEntry[] {
    return readRaw();
}

export function hasUnverifiedLawsuitJournal(): boolean {
    return readRaw().length > 0;
}

export function isLawsuitJournalStillOpen(fileId: string | number): boolean {
    const id = String(fileId);
    return readRaw().some((entry) => entry.fileId === id);
}

/** تسجيل محاولة كتابة قبل active segment — WAL */
export function stageLawsuitJournalRecords(files: readonly FileData[]): void {
    if (!files.length) return;
    const byId = new Map(readRaw().map((entry) => [entry.fileId, entry]));
    const ts = Date.now();
    for (const file of files) {
        const fileId = String(file.id ?? '');
        if (!fileId) continue;
        markLawsuitJournaledThisPage(fileId);
        byId.set(fileId, { v: 1, fileId, file, ts });
    }
    writeRaw(Array.from(byId.values()).slice(-JOURNAL_CAP));
}

export function mergeLawsuitJournalInto(active: FileData[]): FileData[] {
    const entries = readRaw();
    if (entries.length === 0) return active;
    return mergeRicherLawsuitActive(
        active,
        entries.map((entry) => entry.file),
    );
}

export function pruneLawsuitJournalForFileIds(fileIds: readonly (string | number)[]): void {
    const ids = new Set(fileIds.map(String));
    if (ids.size === 0) return;
    writeRaw(readRaw().filter((entry) => !ids.has(entry.fileId)));
}

/**
 * بعد تسخين المفاتيح: ادمج السجل في النشط وثبّت القرص.
 * يُمسح السجل فقط بعد تحقق القرص.
 */
export async function flushLawsuitJournalToActive(): Promise<number> {
    if (SecureStoreService.isUnreadSync(LAWSUIT_WRITE_JOURNAL_KEY)) {
        await SecureStoreService.getItem(LAWSUIT_WRITE_JOURNAL_KEY);
    }
    const entries = readRaw();
    if (entries.length === 0) return 0;
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)) return 0;

    const {
        loadLawsuitBootSegments,
        persistLawsuitFiles,
    } = await import('@/app/domain/lawsuit/lawsuitFilesRepository');
    const boot = loadLawsuitBootSegments().active;
    const merged = mergeLawsuitJournalInto(boot);
    persistLawsuitFiles(merged);

    /* ديناميكي: كسر دائرة Journal → Verify → Journal عند تهيئة الوحدة */
    const { tryFinalizeLawsuitJournalAfterProof } = await import(
        '@/app/domain/lawsuit/lawsuitDurabilityVerify'
    );
    let cleared = 0;
    for (const entry of entries) {
        const commit = await awaitLawsuitWorkspaceCommit({
            timeoutMs: 8_000,
            requireActiveFileId: entry.fileId,
        });
        const didClear = await tryFinalizeLawsuitJournalAfterProof(entry.fileId, commit);
        if (didClear) cleared += 1;
    }
    return cleared;
}

import { appendPendingExecutorSeizureDecision } from '@/app/utils/executorSeizureDecisionQueue';
import {
    isInvalidSeizureWorkflowDossierId,
    resolveSeizureWorkflowDossierId,
} from '@/app/components/lawyer/ExecutionDashboard/utils/seizureWorkflowDossierUtils';
import { isDecisionPending } from './seizureWorkflowStatus';
import type { SeizureBasicRequestInput, SeizureBasicRequestResult } from './seizureSimpleKindPlugins';

export function findPendingSeizureDecisionBySubtype(
    decisions: Array<Record<string, unknown>>,
    subtype: string,
): Record<string, unknown> | null {
    const st = String(subtype || '').trim();
    if (!st) return null;
    const hits = decisions.filter((r) => {
        if (String(r?.requestKind || '') !== 'seizure') return false;
        if (String(r?.seizureSubtype || '').trim() !== st) return false;
        return isDecisionPending(r);
    });
    if (!hits.length) return null;
    return hits.reduce((acc, cur) => {
        const a = String(
            (acc as { resolvedAt?: string; date?: string }).resolvedAt ??
                (acc as { date?: string }).date ??
                '',
        );
        const b = String(
            (cur as { resolvedAt?: string; date?: string }).resolvedAt ??
                (cur as { date?: string }).date ??
                '',
        );
        return b.localeCompare(a, undefined, { numeric: true }) > 0 ? cur : acc;
    }, hits[0]!);
}

/** إرسال طلب حجز بسيط (راتب / غير / إشارة / مبدئي) عبر dossier موحّد */
export function submitBasicSeizurePendingRequest(
    input: SeizureBasicRequestInput,
): SeizureBasicRequestResult {
    const dossierId = resolveSeizureWorkflowDossierId(input.dossierInput);
    if (isInvalidSeizureWorkflowDossierId(dossierId)) {
        return { ok: false, decisionId: null, error: 'invalid_dossier' };
    }
    const subtype = String(input.subtype || '').trim();
    const decisions = input.decisions ?? [];
    if (decisions.length && findPendingSeizureDecisionBySubtype(decisions, subtype)) {
        return { ok: false, decisionId: null, dossierId, error: 'duplicate' };
    }
    const payloadJson =
        input.payloadExtra && Object.keys(input.payloadExtra).length
            ? JSON.stringify(input.payloadExtra)
            : undefined;
    const decisionId = appendPendingExecutorSeizureDecision({
        executionId: dossierId,
        requestTitle: `${input.title} — قيد البت لدى المنفذ`,
        requestBody: input.body,
        seizureSubtype: subtype as never,
        ...(payloadJson ? { seizurePayloadJson: payloadJson } : {}),
    });
    if (!decisionId) {
        return { ok: false, decisionId: null, dossierId, error: 'duplicate' };
    }
    return { ok: true, decisionId, dossierId };
}

export function resolveSeizureDossierId(input: SeizureBasicRequestInput['dossierInput']): string {
    return resolveSeizureWorkflowDossierId(input);
}

import {
    computeUrgentCaseStatus,
    type UrgentCase,
} from '@/app/components/lawyer/Component_Urgent_Card';
import { uuidv4 } from '@/app/services/urgent-actions-db';
import { resolveProcedureCategory } from './procedureCategory';
import type { UrgentFormSavePayload } from './types';

const DEFAULT_MS_PER_DAY = 1000 * 60 * 60 * 24;

function resolveRepresentedParty(data: UrgentFormSavePayload): 'client' | 'opponent' | null {
    const p1 = Array.isArray(data.allParty1) ? data.allParty1 : [];
    const p2 = Array.isArray(data.allParty2) ? data.allParty2 : [];
    const p1Rep = p1.some((p) => {
        const row = p && typeof p === 'object' ? (p as Record<string, unknown>) : null;
        return !!row?.isRepresented || !!row?.isClient;
    });
    const p2Rep = p2.some((p) => {
        const row = p && typeof p === 'object' ? (p as Record<string, unknown>) : null;
        return !!row?.isRepresented || !!row?.isClient;
    });
    if (p1Rep && !p2Rep) return 'client';
    if (p2Rep && !p1Rep) return 'opponent';
    if (data.representedParty === 'client' || data.representedParty === 'opponent') return data.representedParty;
    return null;
}

type CreateCaseFromFormOptions = {
    now?: Date;
    msPerDay?: number;
};

/** يبني UrgentCase جديداً من حمولة Form_Urgent_Actions بعد الحفظ */
export function createCaseFromForm(data: UrgentFormSavePayload, opts?: CreateCaseFromFormOptions): UrgentCase {
    const now = opts?.now ?? new Date();
    const msPerDay = opts?.msPerDay ?? DEFAULT_MS_PER_DAY;
    const nowYmd = now.toISOString().slice(0, 10);
    const requestDateRaw = typeof data.requestDate === 'string' ? data.requestDate : null;
    const requestDate = requestDateRaw ? new Date(requestDateRaw) : now;
    const specificActionType =
        typeof data.specificActionType === 'string' ? data.specificActionType.trim() : 'طلب مستعجل';
    const procedureCategory =
        data.procedureCategory === 'petition_orders' || data.procedureCategory === 'urgent_judiciary'
            ? data.procedureCategory
            : resolveProcedureCategory(null, specificActionType);
    const pathway =
        procedureCategory === 'urgent_judiciary' ||
        data.actionType === 'urgent_discovery' ||
        data.actionType === 'acknowledgment'
            ? 'urgent_action'
            : 'state_order';
    const startAtGrievance = data?.initialEntryMode === 'grievance';
    const startDefenderPhase2 = data?.initialEntryMode === 'defender_phase2';
    const startDefenderPhase3 = data?.initialEntryMode === 'defender_phase3';
    const judgeDecisionDate =
        typeof data?.initialJudgeDecisionDate === 'string' && data.initialJudgeDecisionDate
            ? data.initialJudgeDecisionDate
            : nowYmd;
    const hasIntervention = data?.hasIntervention === true;
    const guaranteeKind =
        data?.guaranteeKind === 'cash' ||
        data?.guaranteeKind === 'personal' ||
        data?.guaranteeKind === 'real_estate' ||
        data?.guaranteeKind === 'none'
            ? data.guaranteeKind
            : null;
    const guaranteeDetailsText = typeof data?.guaranteeDetailsText === 'string' ? data.guaranteeDetailsText : null;
    const defaultDeadlineDays = pathway === 'state_order' ? 3 : 7;
    const deadlineDays =
        typeof data.deadlineDays === 'number' && Number.isFinite(data.deadlineDays) && data.deadlineDays > 0
            ? data.deadlineDays
            : defaultDeadlineDays;
    const derivedDeadline = new Date(requestDate.getTime() + deadlineDays * msPerDay);
    const firstHearingYmd =
        typeof data.firstHearingDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.firstHearingDate.trim())
            ? data.firstHearingDate.trim()
            : null;

    const newCaseBase: UrgentCase = {
        id: uuidv4(),
        type: pathway === 'state_order' ? 'state_order' : 'urgent_action',
        actionType: specificActionType,
        applicantName: typeof data.party1Name === 'string' ? data.party1Name : 'مقدم الطلب',
        court: typeof data.courtName === 'string' ? data.courtName : 'غير محدد',
        requestNumber: typeof data.requestNumber === 'string' ? data.requestNumber : '',
        requestDate: typeof data.requestDate === 'string' ? data.requestDate : '',
        courtName: typeof data.courtName === 'string' ? data.courtName : '',
        judgeName: typeof data.judgeName === 'string' ? data.judgeName : '',
        specificActionType,
        procedureCategory,
        procedureDetails: typeof data.procedureDetails === 'string' ? data.procedureDetails.trim() : '',
        requestSubject: typeof data.requestSubject === 'string' ? data.requestSubject : '',
        urgentReason: typeof data.urgentReason === 'string' ? data.urgentReason : '',
        legalBasis: typeof data.legalBasis === 'string' ? data.legalBasis : '',
        requestNotes: typeof data.notes === 'string' ? data.notes : '',
        hasIntervention,
        guaranteeKind,
        guaranteeDetailsText,
        feeReceiptNumber: typeof data.feeReceiptNumber === 'string' ? data.feeReceiptNumber : null,
        feeReceiptDate: typeof data.feeReceiptDate === 'string' ? data.feeReceiptDate : null,
        initialNotificationMethod:
