import { beforeEach, describe, expect, it, vi } from 'vitest';

const fetchSecure = vi.fn();
const revokeDeviceTrust = vi.fn();

vi.mock('@/app/services/SecureAPIClient', () => ({
    SecureAPIClient: { fetchSecure: (...a: unknown[]) => fetchSecure(...a) },
}));

