import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { PushNotificationService } from '@/app/services/PushNotificationService';
import { savePushSubscription } from '@/app/services/pushSubscriptionStore';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import {
    canSendPushNotifications,
    filterAlertsByNotificationSettings,
} from '@/app/services/settings/settingsRuntime';
import { getLawyerSettingsSnapshot } from '@/app/services/settings/settingsSnapshot';
import { alertNotificationChannel } from '@/app/services/notifications/notificationAlertPolicy';
import { showHamiNotification } from '@/app/services/notifications/HamiNotificationBridge';
import { debug } from '@/app/utils/debug';

const SEEN_KEY = 'hami:alert-push-seen:v1';
const MAX_SEEN = 400;
// مدة احتفاظ الـ seen في localStorage — 7 أيام تمنع إعادة-push للتنبيه نفسه عبر تحديثات الصفحة
const SEEN_TTL_MS = 7 * 24 * 60 * 60 * 1000;

type SeenEntry = { id: string; ts: number };

function loadSeen(): Map<string, number> {
    try {
        // مهاجرة من sessionStorage السابق (إن وُجدت): نقرأ القائمة القديمة ونحوّلها مرة واحدة
        const legacyRaw =
            typeof sessionStorage !== 'undefined' ? sessionStorage.getItem(SEEN_KEY) : null;
        const raw =
            typeof localStorage !== 'undefined' ? localStorage.getItem(SEEN_KEY) : null;
        const now = Date.now();
        const out = new Map<string, number>();
        if (raw) {
            const parsed: unknown = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                for (const item of parsed) {
                    if (item && typeof item === 'object') {
                        const e = item as Partial<SeenEntry>;
                        if (typeof e.id === 'string' && typeof e.ts === 'number') {
                            if (now - e.ts <= SEEN_TTL_MS) out.set(e.id, e.ts);
                        }
                    } else if (typeof item === 'string') {
                        // legacy shape داخل localStorage أيضاً
                        out.set(item, now);
                    }
                }
            }
        }
        if (legacyRaw && typeof localStorage !== 'undefined') {
            try {
                const parsed: unknown = JSON.parse(legacyRaw);
                if (Array.isArray(parsed)) {
                    for (const item of parsed) {
                        if (typeof item === 'string' && !out.has(item)) out.set(item, now);
                    }
                }
                sessionStorage.removeItem(SEEN_KEY);
            } catch { /* ignore */ }
        }
        return out;
    } catch {
        return new Map();
    }
}

function saveSeen(seen: Map<string, number>): void {
    try {
        if (typeof localStorage === 'undefined') return;
        const now = Date.now();
        const arr: SeenEntry[] = Array.from(seen.entries())
            .filter(([, ts]) => now - ts <= SEEN_TTL_MS)
            .slice(-MAX_SEEN)
            .map(([id, ts]) => ({ id, ts }));
        localStorage.setItem(SEEN_KEY, JSON.stringify(arr));
    } catch {
        /* ignore */
    }
}

/** لا نطلب صلاحية المتصفح تلقائياً — التنبيهات داخل التطبيق تكفي حتى يفعّل المستخدم الإشعارات من الإعدادات. */
export async function ensurePushPermissionForCriticalAlerts(_alerts: SecretaryAlert[]): Promise<void> {
    return;
}

/** إشعار محلي للتنبيهات الحرجة الجديدة فقط (بدون تكرار في الجلسة) */
const PUSH_SUB_ATTEMPTED = 'hami:push-sub-attempted';

async function persistPushSubscription(lawyerId: string | null): Promise<void> {
    if (!lawyerId) return;
    if (isCapacitorNativePlatform()) return;
    try {
        if (sessionStorage.getItem(PUSH_SUB_ATTEMPTED) === lawyerId) return;
        const sub = await PushNotificationService.subscribeToPush();
        // سجّل المحاولة حتى عند الفشل — يمنع مئات التحذيرات عند كل refresh للتنبيهات
        sessionStorage.setItem(PUSH_SUB_ATTEMPTED, lawyerId);
        if (sub) {
            await savePushSubscription(lawyerId, sub.toJSON());
        }
    } catch {
        try {
            sessionStorage.setItem(PUSH_SUB_ATTEMPTED, lawyerId);
        } catch {
            /* ignore */
        }
    }
}

export async function syncPushForNewCriticalAlerts(
    alerts: SecretaryAlert[],
    lawyerId?: string | null,
): Promise<void> {
    if (typeof window === 'undefined' || !('Notification' in window)) return;

    const settings = getLawyerSettingsSnapshot();
    if (!canSendPushNotifications(settings)) return;

    const channelFiltered = filterAlertsByNotificationSettings(alerts, settings);
    await ensurePushPermissionForCriticalAlerts(channelFiltered);
    if (PushNotificationService.getPermission() === 'granted' && lawyerId) {
        void persistPushSubscription(lawyerId);
    }
    const nativePush = isCapacitorNativePlatform();
    if (!nativePush && PushNotificationService.getPermission() !== 'granted') return;

    const critical = channelFiltered.filter((a) => a.priority <= 1);
    if (critical.length === 0) return;

    const seen = loadSeen();
    let changed = false;
    const now = Date.now();

    for (const a of critical) {
        if (seen.has(a.id)) continue;
        const channel = alertNotificationChannel(a) ?? 'secretary';
        try {
            await showHamiNotification(
                channel,
                {
                    title: a.title,
                    body: a.summary,
                    tag: a.id,
                    data: { alertId: a.id, target: a.target, entityId: a.entityId },
                    requireInteraction: a.type === 'HEARING' || a.type === 'URGENT',
                },
                a.priority <= 1,
            );
            seen.set(a.id, now);
            changed = true;
        } catch (err) {
            debug.warn('[appAlertPushSync] push failed:', err);
        }
    }

    if (changed) saveSeen(seen);
}

export function markAlertSeenForPush(alertId: string): void {
    const seen = loadSeen();
    seen.set(alertId, Date.now());
    saveSeen(seen);
}

import { parseJsonResponse } from '@/app/utils/bffJsonResponse';
import { getOrCreateDeviceId } from '@/app/security/deviceId';
import { getWifeNativeFetch } from '@/app/security/wifeNativeFetch';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import { AUTH_OTP_CODE_LEN } from '@/app/api/auth/otp/authOtpTypes';

/** طول الرمز المُصدَر — الخادم يرفض أي طول مختلف، فالواجهة تمنعه قبل الشبكة. */
export const AUTH_OTP_CODE_LENGTH = AUTH_OTP_CODE_LEN;

export type AuthOtpPurpose = 'password_reset' | 'email_confirm';
export type AuthOtpChannel = 'email' | 'whatsapp';
export type AuthOtpDelivery = 'otp' | 'link';

export type AuthOtpRequestResult = {
    delivery: AuthOtpDelivery;
    message: string;
    resendAfterSec: number;
    phoneTail: string | null;
};

export type AuthOtpChannelsStatus = {
    email: boolean;
    whatsapp: boolean;
};

export type AuthOtpAccountPreview = {
    /** لا يصل من المعاينة — يُملأ من نتيجة إرسال فعلي فقط. */
    phoneTail: string | null;
    hasWhatsAppNumber: boolean;
    emailReady: boolean;
    whatsappSendReady: boolean;
    adminWhatsappUrl: string | null;
};

function nativeFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    return getWifeNativeFetch()(input, init);
}

function deviceHeaders(): Record<string, string> {
    const deviceId = typeof window === 'undefined' ? '' : getOrCreateDeviceId();
    return deviceId ? { 'x-wife-device-id': deviceId } : {};
}

function recoveryRedirect(): string | undefined {
    if (typeof window === 'undefined') return undefined;
    return isCapacitorNativePlatform()
        ? 'iq.hami.legal:///?hami_auth=recovery'
        : `${window.location.origin}/?hami_auth=recovery`;
}

function readPhoneTail(value: unknown): string | null {
    if (typeof value !== 'string') return null;
    const tail = value.replace(/\D/g, '');
    return tail.length === 2 ? tail : null;
}

export async function previewAuthOtpAccount(input: {
    email: string;
    purpose: AuthOtpPurpose;
}): Promise<AuthOtpAccountPreview> {
    const response = await nativeFetch('/api/auth/otp/preview', {
        method: 'POST',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            ...deviceHeaders(),
        },
        body: JSON.stringify({
            email: input.email.trim().toLowerCase(),
            purpose: input.purpose,
        }),
    });
    const payload = await parseJsonResponse<{
        ok?: boolean;
        hasWhatsAppNumber?: boolean;
        emailReady?: boolean;
        whatsappSendReady?: boolean;
        adminWhatsappUrl?: unknown;
        error?: string;
    }>(response);
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر التحقق من البريد');
    }
    const adminUrl =
        typeof payload.adminWhatsappUrl === 'string' && payload.adminWhatsappUrl.startsWith('https://')
            ? payload.adminWhatsappUrl
            : null;
    return {
        phoneTail: null,
        hasWhatsAppNumber: payload.hasWhatsAppNumber === true,
        emailReady: payload.emailReady === true,
        whatsappSendReady: payload.whatsappSendReady === true,
        adminWhatsappUrl: adminUrl,
    };
}

export async function requestAuthOtp(input: {
    email: string;
    channel: AuthOtpChannel;
    purpose: AuthOtpPurpose;
}): Promise<AuthOtpRequestResult> {
    const response = await nativeFetch('/api/auth/otp/request', {
        method: 'POST',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            ...deviceHeaders(),
        },
        body: JSON.stringify({
            email: input.email.trim().toLowerCase(),
            channel: input.channel,
            purpose: input.purpose,
            redirectTo: recoveryRedirect(),
        }),
    });
    const payload = await parseJsonResponse<{
        ok?: boolean;
        delivery?: AuthOtpDelivery;
        message?: string;
        resendAfterSec?: number;
        phoneTail?: unknown;
        error?: string;
    }>(response);
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر إرسال رمز التحقق');
    }
    return {
        delivery: payload.delivery === 'link' ? 'link' : 'otp',
        message: payload.message ?? 'أُرسل رمز التحقق.',
        resendAfterSec:
            typeof payload.resendAfterSec === 'number' && payload.resendAfterSec > 0
                ? payload.resendAfterSec
                : 60,
        phoneTail: readPhoneTail(payload.phoneTail),
    };
}

export async function completeAuthOtp(input: {
    email: string;
    code: string;
    purpose: AuthOtpPurpose;
    newPassword?: string;
}): Promise<string> {
    const response = await nativeFetch('/api/auth/otp/complete', {
        method: 'POST',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            ...deviceHeaders(),
        },
        body: JSON.stringify({
            email: input.email.trim().toLowerCase(),
            code: input.code.replace(/\D/g, ''),
            purpose: input.purpose,
            newPassword: input.newPassword,
        }),
    });
    const payload = await parseJsonResponse<{ ok?: boolean; message?: string; error?: string }>(
        response,
    );
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر إكمال التحقق');
    }
    return payload.message ?? 'تم بنجاح';
}

export async function fetchAuthOtpChannels(): Promise<AuthOtpChannelsStatus> {
    const response = await nativeFetch('/api/auth/otp/channels', {
        method: 'GET',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            ...deviceHeaders(),
        },
    });
    const payload = await parseJsonResponse<{
        ok?: boolean;
        email?: boolean;
        whatsapp?: boolean;
        error?: string;
    }>(response);
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر معرفة قنوات التحقق');
    }
    return {
        email: payload.email === true,
        whatsapp: payload.whatsapp === true,
    };
}

