    { id: 'evidence', label: 'قانون الإثبات' },
    { id: 'penal', label: 'قانون العقوبات' },
    { id: 'criminal_procedure', label: 'قانون أصول المحاكمات الجزائية' },
] as const;

/** يلتقط: المادة 32، مادة 32، م 32، المادة (32) */
export const LAW_ARTICLE_REGEX = /(?:المادة|مادة|م)\s*\(?\s*(\d+)\s*\)?/gi;

const LINK_CLASS =
    'smart-law-link text-[#E6C673] underline decoration-dotted decoration-[#E6C673]/55 cursor-pointer';
const PENDING_CLASS = 'smart-law-link--pending ring-1 ring-[#E6C673]/25';

export function inferLawsuitTypeFromDocType(docType?: string | null): NonNullable<
    Extract<DossierNoteContext, { kind: 'lawsuit' }>['lawsuitType']
> {
    const raw = String(docType ?? '').trim().toLowerCase();
    if (/جزائ|جنائ|criminal/.test(raw)) return 'criminal';
    if (/أحوال|personal|أسرة|زوج/.test(raw)) return 'personal_status';
    if (/تجار|commercial/.test(raw)) return 'commercial';
    if (/إدار|admin/.test(raw)) return 'administrative';
    if (/مدن|civil/.test(raw)) return 'civil';
    return 'civil';
}

export function isSmartLawLinksEnabled(ctx: DossierNoteContext): boolean {
    return ctx.kind !== 'repository';
}

export function resolveDefaultSmartLawId(ctx: DossierNoteContext): SmartLawId | null {
    if (ctx.kind === 'execution') return 'execution';
    if (ctx.kind === 'repository') return null;
    switch (ctx.lawsuitType) {
        case 'criminal':
            return 'penal';
        case 'civil':
        case 'commercial':
        case 'administrative':
        case 'personal_status':
        case 'other':
        default:
            return 'civil_procedure';
    }
}

export function smartLawIdToCivilTab(lawId: SmartLawId): CivilLawCodeType | null {
    if (lawId === 'civil_procedure' || lawId === 'evidence') return lawId;
    return null;
}

export function smartLawIdToCriminalTab(lawId: SmartLawId): LegalCodeType | null {
    if (lawId === 'penal') return 'penal';
    if (lawId === 'criminal_procedure') return 'procedure';
    return null;
}

export function lawLabelForId(lawId: SmartLawId): string {
    return SMART_LAW_PICKER_OPTIONS.find((o) => o.id === lawId)?.label ?? lawId;
}

export function parseSmartLawId(raw: string | null | undefined): SmartLawId | null {
    const value = String(raw ?? '').trim() as SmartLawId;
    return SMART_LAW_PICKER_OPTIONS.some((o) => o.id === value) ? value : null;
}

function escapeHtmlAttr(value: string): string {
    return value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}

function buildLawLinkSpan(matchText: string, articleNum: number, lawId: SmartLawId | null): string {
    const lawAttr = lawId ? ` data-law-id="${lawId}"` : '';
    const pending = lawId ? '' : ` ${PENDING_CLASS}`;
    return `<span class="${LINK_CLASS}${pending}" data-law-article="${articleNum}"${lawAttr}>${escapeHtmlAttr(matchText)}</span>`;
}

export function decorateLawArticlesInPlainText(text: string, ctx: DossierNoteContext): string {
    if (!isSmartLawLinksEnabled(ctx)) return text;
    const defaultLawId = resolveDefaultSmartLawId(ctx);
    LAW_ARTICLE_REGEX.lastIndex = 0;
    return text.replace(LAW_ARTICLE_REGEX, (match, num) => {
        const articleNum = Number(num);
        if (!Number.isFinite(articleNum)) return match;
        return buildLawLinkSpan(match, articleNum, defaultLawId);
    });
}

/** يزيل نصوص tooltips القديمة — لا تُخزَّن في قاعدة البيانات. */
export function stripStoredLawTipAttributes(html: string): string {
    if (!html.includes('data-law-tip')) return html;
    if (typeof document === 'undefined') {
        return html.replace(/\s*data-law-tip="[^"]*"/gi, '');
    }
    const root = document.createElement('div');
    root.innerHTML = html;
    root.querySelectorAll('[data-law-tip]').forEach((el) => el.removeAttribute('data-law-tip'));
    return root.innerHTML;
}

export function normalizeSmartLawLinkHtml(html: string): string {
    return stripStoredLawTipAttributes(html);
}

export function decorateLawArticlesInHtml(html: string, ctx: DossierNoteContext): string {
    if (!isSmartLawLinksEnabled(ctx)) return html;
    if (!html.trim()) return html;
    if (typeof document === 'undefined') return html;

    const cleaned = stripStoredLawTipAttributes(html);
    const root = document.createElement('div');
    root.innerHTML = cleaned;
    const defaultLawId = resolveDefaultSmartLawId(ctx);

    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    const textNodes: Text[] = [];
    let node = walker.nextNode();
    while (node) {
        const parent = (node as Text).parentElement;
        if (parent?.closest('.smart-law-link, [data-law-article]')) {
            node = walker.nextNode();
            continue;
        }
        const source = (node as Text).textContent ?? '';
        LAW_ARTICLE_REGEX.lastIndex = 0;
        if (LAW_ARTICLE_REGEX.test(source)) textNodes.push(node as Text);
        node = walker.nextNode();
    }

    for (const textNode of textNodes) {
        const source = textNode.textContent ?? '';
        LAW_ARTICLE_REGEX.lastIndex = 0;
        const parts: Array<{ type: 'text' | 'link'; value: string; articleNum?: number }> = [];
        let lastIndex = 0;
        for (const match of source.matchAll(LAW_ARTICLE_REGEX)) {
            const idx = match.index ?? 0;
            if (idx > lastIndex) parts.push({ type: 'text', value: source.slice(lastIndex, idx) });
            const articleNum = Number(match[1]);
            parts.push({ type: 'link', value: match[0], articleNum });
            lastIndex = idx + match[0].length;
        }
        if (parts.length === 0) continue;
        if (lastIndex < source.length) parts.push({ type: 'text', value: source.slice(lastIndex) });

        const frag = document.createDocumentFragment();
        for (const part of parts) {
            if (part.type === 'text') {
                frag.appendChild(document.createTextNode(part.value));
            } else if (part.articleNum != null) {
                const span = document.createElement('span');
                span.className = LINK_CLASS + (defaultLawId ? '' : ` ${PENDING_CLASS}`);
                span.dataset.lawArticle = String(part.articleNum);
                if (defaultLawId) span.dataset.lawId = defaultLawId;
                span.textContent = part.value;
                frag.appendChild(span);
            }
        }
        textNode.replaceWith(frag);
    }

    if (defaultLawId) {
        root.querySelectorAll('[data-law-article]:not([data-law-id])').forEach((el) => {
            if (!(el instanceof HTMLElement)) return;
            el.dataset.lawId = defaultLawId;
            el.classList.remove('smart-law-link--pending');
        });
    }

    return root.innerHTML;
}

/** @deprecated — للتوافق؛ النص الكامل يُجلب عند Hover */
export function resolveLawArticleTooltip(articleNum: number, ctx: DossierNoteContext): string {
    const lawId = resolveDefaultSmartLawId(ctx);
    if (!lawId) return `المادة ${articleNum} — اختر القانون`;
    return `المادة ${articleNum} — ${lawLabelForId(lawId)}`;
}

export function assignSmartLawIdToElement(el: HTMLElement, lawId: SmartLawId): void {
    el.dataset.lawId = lawId;
    el.classList.remove('smart-law-link--pending');
    el.removeAttribute('data-law-tip');
}

export function readSmartLawLinkFromElement(el: HTMLElement): {
    articleNum: number;
    lawId: SmartLawId | null;
} | null {
    const articleRaw = el.getAttribute('data-law-article');
    const articleNum = Number(articleRaw);
    if (!Number.isFinite(articleNum)) return null;
    return { articleNum, lawId: parseSmartLawId(el.getAttribute('data-law-id')) };
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { normalizeClientPhone } from '@/app/components/lawyer/NeuralAlertsCard/alertContactUtils';

function readStr(o: Record<string, unknown>, key: string): string {
    const v = o[key];
    return typeof v === 'string' ? v.trim() : '';
}

function phoneFromLawsuit(file: FileData): string | null {
    const direct = normalizeClientPhone(file.clientPhone);
    if (direct) return direct;
    for (const p of file.parties ?? []) {
        if (!p.isClient) continue;
        const ph = normalizeClientPhone(p.phone);
        if (ph) return ph;
    }
    for (const p of file.parties ?? []) {
        const ph = normalizeClientPhone(p.phone);
        if (ph) return ph;
    }
    return null;
}

function phoneFromExecution(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const f = raw as Record<string, unknown>;
    const debtors = Array.isArray(f.debtors) ? f.debtors : [];
    for (const d of debtors) {
        if (!d || typeof d !== 'object') continue;
        const ph = normalizeClientPhone(readStr(d as Record<string, unknown>, 'phone'));
        if (ph) return ph;
    }
    return normalizeClientPhone(readStr(f, 'clientPhone'));
}

function phoneFromCriminal(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const c = raw as Record<string, unknown>;
    const defendants = Array.isArray(c.defendants) ? c.defendants : [];
    for (const d of defendants) {
        if (!d || typeof d !== 'object') continue;
        const o = d as Record<string, unknown>;
        if (o.isOurClient !== true && o.isClient !== true) continue;
        const ph =
            normalizeClientPhone(readStr(o, 'phone')) ||
            normalizeClientPhone(readStr(o, 'mobile'));
        if (ph) return ph;
    }
    return null;
}

function phoneFromUrgent(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const c = raw as Record<string, unknown>;
    return (
        normalizeClientPhone(readStr(c, 'applicantPhone')) ||
        normalizeClientPhone(readStr(c, 'clientPhone')) ||
        normalizeClientPhone(readStr(c, 'phone'))
    );
}

/** يكمّل رقم الموكل من الإضابيرة إن لم يُمرَّر من التقويم */
export function enrichAlertClientPhone(
    alert: SecretaryAlert,
    ctx: {
        lawsuitFiles?: FileData[];
        executionFiles?: unknown[];
        criminalCases?: unknown[];
        urgentCases?: unknown[];
    },
): SecretaryAlert {
    if (normalizeClientPhone(alert.clientPhone)) return alert;

    const id = alert.entityId ? String(alert.entityId) : '';
    if (!id) return alert;

    let phone: string | null = null;
    const dossier = alert.calendarSource?.dossierModule;
    const dossierId = alert.calendarSource?.dossierId;

    const resolveId = dossierId ?? id;

    if (alert.target === 'lawsuit' || dossier === 'lawsuit') {
        const file = ctx.lawsuitFiles?.find((f) => String(f.id) === resolveId);
        if (file) phone = phoneFromLawsuit(file);
    } else if (alert.target === 'execution' || dossier === 'execution') {
        const file = ctx.executionFiles?.find((f) => String((f as { id?: unknown }).id ?? '') === resolveId);
        if (file) phone = phoneFromExecution(file);
    } else if (alert.target === 'criminal' || dossier === 'criminal') {
        const row = ctx.criminalCases?.find((c) => String((c as { id?: unknown }).id ?? '') === resolveId);
        if (row) phone = phoneFromCriminal(row);
    } else if (alert.target === 'urgent' || dossier === 'urgent') {
        const row = ctx.urgentCases?.find((c) => String((c as { id?: unknown }).id ?? '') === resolveId);
        if (row) phone = phoneFromUrgent(row);
    }

    if (!phone) return alert;
    return { ...alert, clientPhone: phone };
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { resolveFileSearchLifecycle, type SearchLifecycle } from '@/app/services/searchLifecycle';
import { normalizeArabic } from '@/app/components/lawyer/LawyerShared';
import { storageCache } from '@/app/utils/storageCache';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';
import {
    executionDocumentsStorageKey,
    executionStorageKey,
} from '@/app/utils/executionStorageKeys';
import { readExecutionDossierBlobScanningScopes } from '@/app/utils/executionDossierBlobPersistence';

function norm(text: string): string {
    return normalizeArabic(text).toLowerCase();
}

function blob(parts: (string | undefined | null)[]): string {
    return norm(parts.filter(Boolean).join(' '));
}

function readStorageJson(key: string): unknown {
    try {
        const cached = storageCache.get(key);
        if (cached != null) return cached;
        const raw = readSecureOrDrainLegacySync(key);
        if (!raw) return null;
        return JSON.parse(raw) as unknown;
    } catch {
        return null;
    }
}

/**
 * بلوب الإضبارة للفهرسة — عبر القارئ المدرك لنطاق المستخدم.
 *
 * الكتابة تُقيّد مفتاح البلوب الرئيسي بـ`:u:<uid>`، والقراءة هنا كانت بالمفتاح
 * الحرّ `execution_<id>`. فما دامت الجلسة قائمة تُغطّي الذاكرة المؤقتة الفرق،
 * لكنها تخلو بعد أول إعادة تحميل: فيعود `getItemSync` فارغاً، ويصمت البحث
 * العميق عن كل أحداث السجل الزمني رغم وجودها على القرص. القارئ المقيّد يجرّب
 * مفتاح المستخدم أولاً ثم يمسح النطاقات المرئية له.
 */
function readDossierPayload(id: string): Record<string, unknown> | null {
    const cached = storageCache.get(executionStorageKey(id));
    if (cached && typeof cached === 'object') return cached as Record<string, unknown>;
    return readExecutionDossierBlobScanningScopes(id);
}

type EntryDraft = Omit<GlobalSearchEntry, 'lifecycle'>;

/** أحداث السجل الزمني ومستندات مخزن كل إضبارة تنفيذ */
export function buildExecutionDeepSearchEntries(
    executionFiles: (FileData & { executionTrashDeletedAt?: string | null })[],
    stamp: (draft: EntryDraft, lifecycle: SearchLifecycle) => GlobalSearchEntry,
): GlobalSearchEntry[] {
    const out: GlobalSearchEntry[] = [];

    for (const f of executionFiles) {
        const id = String(f.id);
        const lifecycle = resolveFileSearchLifecycle(f);
        const fileLabel = f.caseNo || f.parties?.[0]?.name || id;

        const payload = readDossierPayload(id);
        const haystackParts: string[] = [];
        let firstTitle = '';
        let firstSnippet = '';

        if (payload && typeof payload === 'object') {
            const rec = payload as Record<string, unknown>;
            const events = Array.isArray(rec.timelineEvents) ? rec.timelineEvents : [];
            for (const rawEv of events) {
                if (!rawEv || typeof rawEv !== 'object') continue;
                const ev = rawEv as Record<string, unknown>;
                if (ev.trashedAt) continue;
                const title = String(ev.title ?? '').trim();
                if (!title) continue;
                const desc = String(ev.description ?? ev.details ?? '').trim();
                haystackParts.push(title, desc, String(ev.type ?? ''));
                if (!firstTitle) {
                    firstTitle = title;
                    firstSnippet = desc;
                }
            }

            const notesLog = Array.isArray(rec.caseNotesLog) ? rec.caseNotesLog : [];
            for (const rawNote of notesLog) {
                if (!rawNote || typeof rawNote !== 'object') continue;
                const n = rawNote as Record<string, unknown>;
                if (n.isDeleted || n.trashedAt) continue;
                const text = String(n.text ?? n.content ?? '').trim();
                if (!text) continue;
                haystackParts.push(text);
                if (!firstTitle) {
                    firstTitle = text.slice(0, 80);
                    firstSnippet = text;
                }
            }
        }

        const docsRaw = readStorageJson(executionDocumentsStorageKey(id));
        if (Array.isArray(docsRaw)) {
            for (const rawDoc of docsRaw) {
                if (!rawDoc || typeof rawDoc !== 'object') continue;
                const d = rawDoc as Record<string, unknown>;
                if (d.trashedAt) continue;
                const name = String(d.name ?? d.originalFileName ?? '').trim();
                if (!name) continue;
                haystackParts.push(name, String(d.folderId ?? ''));
                if (!firstTitle) firstTitle = name;
            }
        }

        if (haystackParts.length === 0) continue;

        const haystack = haystackParts.join(' ');
        out.push(
            stamp(
                {
                    id: `ex-deep-${id}`,
                    category: 'execution',
                    title: firstTitle || fileLabel,
                    subtitle: `إضبارة تنفيذ — ${fileLabel}`,
                    snippet: firstSnippet || undefined,
                    _searchStr: blob([haystack.slice(0, 8_000), fileLabel]),
                    navigate: { type: 'file', fileId: f.id },
                },
                lifecycle,
            ),
        );
    }

    return out;
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import type { ForumNotification } from '@/app/services/forum/forumTypes';
import { emitForumUnreadCount } from '@/app/services/forum/forumNotificationEvents';
import { notifyForumActivity } from '@/app/services/notifications/domainNotifications';
import { canReachProtectedServerNetwork } from '@/app/services/secureApiNetworkFeatures';
import { isAppForeground, subscribeAppForeground } from '@/app/runtime/appForegroundGate';
import { readPersistedSupabaseAuth } from '@/app/utils/authStorage';

export type ForumStreamPayload = {
    type?: 'connected';
    unreadCount: number;
    latestId?: string | null;
    notification?: ForumNotification | null;
};

type StreamHandler = (payload: ForumStreamPayload) => void;

let running = false;
let refCount = 0;
let streamUserId: string | null = null;
let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
let lastPushedId: string | null = null;
let releaseForegroundGate: (() => void) | null = null;
/** الخلفية تُغلق البثّ لكنها لا تُلغي الاشتراك — العودة تعيد فتحه لنفس المشتركين. */
let suspendedForBackground = false;
const handlers = new Set<StreamHandler>();

function canStartForumStream(userId: string): boolean {
    const persisted = readPersistedSupabaseAuth();
    const meta = (persisted.user?.user_metadata ?? null) as Record<string, unknown> | null;
    return canReachProtectedServerNetwork(userId, meta);
}

function isExpectedStreamDenial(err: unknown): boolean {
    if (!(err instanceof Error)) return false;
    if (err.message.startsWith('stream 403')) return true;
    if (err.message.includes('NETWORK_FEATURES_DENIED')) return true;
    return false;
}

function parseSseChunk(buffer: string): { events: ForumStreamPayload[]; rest: string } {
    const events: ForumStreamPayload[] = [];
    const parts = buffer.split('\n\n');
    const rest = parts.pop() ?? '';
    for (const part of parts) {
        for (const line of part.split('\n')) {
            if (!line.startsWith('data:')) continue;
            const raw = line.slice(5).trim();
            if (!raw) continue;
            try {
                events.push(JSON.parse(raw) as ForumStreamPayload);
            } catch {
                /* skip */
            }
        }
    }
    return { events, rest };
}

async function consumeStream(onPayload: StreamHandler, signal: AbortSignal): Promise<void> {
    const response = await SecureAPIClient.fetchSecureResponse('/api/forum/notifications/stream', {
        method: 'GET',
        signal,
        headers: { Accept: 'text/event-stream' },
    });

    if (!response.ok || !response.body) {
        throw new Error(`stream ${response.status}`);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (!signal.aborted) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const { events, rest } = parseSseChunk(buffer);
        buffer = rest;
        for (const ev of events) onPayload(ev);
    }
}

function dispatchPayload(payload: ForumStreamPayload): void {
    if (typeof payload.unreadCount === 'number') {
        emitForumUnreadCount(payload.unreadCount, { refresh: true });
    }

    const notif = payload.notification;
    if (notif && !notif.read && notif.id && notif.id !== lastPushedId) {
        lastPushedId = notif.id;
        void notifyForumActivity({
            title: notif.title,
            message: notif.message,
            postId: notif.postId,
            type: notif.type,
        });
    }

    for (const h of handlers) h(payload);
}

function scheduleReconnect(userId: string): void {
    if (reconnectTimer) clearTimeout(reconnectTimer);
    reconnectTimer = setTimeout(() => {
        reconnectTimer = null;
        /* إعادة الوصل للمقدّمة فقط: في الخلفية تتحوّل إلى دورة إشعال للراديو */
        if (running && refCount > 0 && isAppForeground()) {
            void ForumNotificationStreamService.start(userId);
        }
    }, 3_000);
}

function abortActiveStream(): void {
    const abort = (ForumNotificationStreamService as { _abort?: AbortController })._abort;
    abort?.abort();
    (ForumNotificationStreamService as { _abort?: AbortController })._abort = undefined;
}

/*
 * البثّ لا يُترك مفتوحاً والتطبيق في الخلفية: الاتصال المفتوح يُبقي الراديو مستيقظاً،
 * والنظام يقطعه فتدخل `scheduleReconnect` دورة إعادة وصل كل ٣ ثوانٍ بلا نهاية.
 * التسليم في الخلفية يمرّ عبر دفع FCM، فلا يُفقد تنبيه بإغلاق البثّ هنا.
 */
function bindForegroundGate(): void {
    if (releaseForegroundGate) return;
    releaseForegroundGate = subscribeAppForeground({
        onSuspend: () => {
            if (!running && !reconnectTimer) return;
            suspendedForBackground = true;
            ForumNotificationStreamService.stop();
        },
        onResume: () => {
            if (!suspendedForBackground) return;
            suspendedForBackground = false;
            const userId = streamUserId;
            if (refCount > 0 && userId) void ForumNotificationStreamService.start(userId);
        },
    });
}

function unbindForegroundGate(): void {
    releaseForegroundGate?.();
    releaseForegroundGate = null;
    suspendedForBackground = false;
}

export const ForumNotificationStreamService = {
    isRunning(): boolean {
        return running;
    },

    subscribe(handler: StreamHandler): () => void {
        handlers.add(handler);
        return () => handlers.delete(handler);
    },

    acquire(userId: string): () => void {
        if (!userId) return () => undefined;

        refCount += 1;
        const userChanged = streamUserId !== userId;
        streamUserId = userId;
        bindForegroundGate();

        if (userChanged && running) {
            abortActiveStream();
            running = false;
        }
        /* في الخلفية لا يُفتح بثّ عند الاشتراك — العودة للمقدّمة هي التي تفتحه */
        if (!running && isAppForeground()) {
            void ForumNotificationStreamService.start(userId);
        } else if (!running) {
            suspendedForBackground = true;
        }

        return () => {
            refCount = Math.max(0, refCount - 1);
            if (refCount === 0) {
                streamUserId = null;
                unbindForegroundGate();
                ForumNotificationStreamService.stop();
            }
        };
    },

    async start(userId: string | null): Promise<void> {
        if (!userId || typeof window === 'undefined') return;
        if (!canStartForumStream(userId)) {
            running = false;
            return;
        }
        if (!isAppForeground()) {
            /* فحص الصحّة الدوري قد ينادي `start` بعد الخلفية — لا يُفتح بثّ هناك */
            suspendedForBackground = true;
            running = false;
            return;
        }
        if (running && streamUserId === userId) return;

        abortActiveStream();
        if (reconnectTimer) {
            clearTimeout(reconnectTimer);
            reconnectTimer = null;
        }

        running = true;
        streamUserId = userId;

        const controller = new AbortController();
        (ForumNotificationStreamService as { _abort?: AbortController })._abort = controller;

        try {
            await consumeStream(dispatchPayload, controller.signal);
        } catch (err) {
            if (isExpectedStreamDenial(err)) {
                running = false;
                return;
            }
            /* reconnect below */
        } finally {
            if (running && !controller.signal.aborted && refCount > 0 && canStartForumStream(userId)) {
                scheduleReconnect(userId);
            }
        }
    },

    stop(): void {
        running = false;
        if (reconnectTimer) {
            clearTimeout(reconnectTimer);
            reconnectTimer = null;
        }
        abortActiveStream();
    },

    /** @internal — إعادة حالة الخدمة في الاختبارات فقط */
