export function buildForumEditPatch(
    post: CommunityPost,
    newContent: string,
): Pick<CommunityPost, 'content' | 'isEdited' | 'updatedAt' | 'editCount' | 'editHistory' | 'tags'> {
    const now = new Date().toISOString();
    return {
        content: newContent,
        isEdited: true,
        updatedAt: now,
        editCount: (post.editCount ?? 0) + 1,
        editHistory: [
