export async function requestHamiNotificationPermission(options?: {
    fromUserGesture?: boolean;
    userId?: string | null;
}): Promise<'granted' | 'denied' | 'default'> {
    const plugin = await loadNativePlugin();
    if (plugin) {
        try {
            const result = await plugin.requestPermissions();
            const display = result.display;
            const granted = display === 'granted';
            if (granted) {
                await initializeHamiNotificationBridge(options?.userId ?? null);
            }
            if (display === 'granted') return 'granted';
            if (display === 'denied') return 'denied';
            return 'default';
        } catch {
            return 'denied';
        }
    }
    const web = await PushNotificationService.requestPermission(options);
    return web;
}

/**
 * FCM — تسجيل الرمز واستقبال push عند إغلاق التطبيق (Android/iOS).
 * يتطلب google-services.json + FCM_SERVICE_ACCOUNT_JSON على الخادم.
 */
import { debug } from '@/app/utils/debug';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import { HAMI_NATIVE_NOTIFICATION_RECEIVED_EVENT } from '@/app/services/notifications/notificationOsTapEvents';
import { playNotificationArrivalCue } from '@/app/services/notifications/notificationArrivalSound';
import type { NotificationInboxChannelKey } from '@/app/services/settings/notificationSettings';
import { isNotificationInboxChannel } from '@/app/services/settings/notificationSettings';

let fcmInitialized = false;
let fcmListenersBound = false;
let lastRegisteredToken: string | null = null;
let fcmUserId: string | null = null;

function channelFromFcmData(data: Record<string, unknown>): NotificationInboxChannelKey {
    const raw = typeof data.channel === 'string' ? data.channel.trim() : '';
    if (isNotificationInboxChannel(raw)) return raw;
    const category = typeof data.category === 'string' ? data.category.trim() : '';
    if (category === 'forum') return 'community';
    return 'secretary';
}

function refreshInboxAfterPush(): void {
    const uid = fcmUserId?.trim();
    if (!uid) return;
    void import('@/app/services/notifications/notificationBackgroundSync')
        .then((m) =>
            m.refreshNotificationShellBadge(uid, {
                includeLegacyPurge: false,
            }),
        )
        .catch(() => undefined);
}

async function registerTokenWithServer(token: string, platform: 'android' | 'ios'): Promise<void> {
    if (lastRegisteredToken === token) return;
    await SecureAPIClient.fetchSecure('/api/notifications/fcm-register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, platform }),
    });
    lastRegisteredToken = token;
    debug.log('[HamiFcmBridge] token registered');
}

async function loadPushPlugin() {
    if (!isCapacitorNativePlatform()) return null;
    try {
        const { PushNotifications } = await import('@capacitor/push-notifications');
        return PushNotifications;
    } catch (error) {
        debug.warn('[HamiFcmBridge] push plugin unavailable:', error);
        return null;
    }
}

function bindFcmListeners(
    PushNotifications: typeof import('@capacitor/push-notifications').PushNotifications,
    platform: 'android' | 'ios',
): void {
    if (fcmListenersBound) return;
    fcmListenersBound = true;

    void PushNotifications.addListener('registration', (token) => {
        const value = token.value?.trim();
        if (!value) return;
        void registerTokenWithServer(value, platform).catch((err) => {
            debug.warn('[HamiFcmBridge] register failed:', err);
        });
    });

    void PushNotifications.addListener('registrationError', (err) => {
        debug.warn('[HamiFcmBridge] registrationError:', err);
    });

    void PushNotifications.addListener('pushNotificationReceived', (notification) => {
        const data = (notification.data ?? {}) as Record<string, unknown>;
        const channel = channelFromFcmData(data);
        void playNotificationArrivalCue(channel).catch(() => undefined);
        refreshInboxAfterPush();
    });

    void PushNotifications.addListener('pushNotificationActionPerformed', (action) => {
        const data = (action.notification.data ?? {}) as Record<string, unknown>;
        window.dispatchEvent(
            new CustomEvent(HAMI_NATIVE_NOTIFICATION_RECEIVED_EVENT, {
                detail: { data, extra: data },
            }),
        );
    });
}

export async function initializeHamiFcmBridge(userId: string | null): Promise<void> {
    if (fcmInitialized || !userId?.trim()) return;
    fcmUserId = userId.trim();

    const PushNotifications = await loadPushPlugin();
    if (!PushNotifications) return;

    const { Capacitor } = await import('@capacitor/core');
    const platform = Capacitor.getPlatform() === 'ios' ? 'ios' : 'android';

    try {
        const perm = await PushNotifications.requestPermissions();
        if (perm.receive !== 'granted') {
            debug.log('[HamiFcmBridge] push permission not granted');
            return;
        }

        bindFcmListeners(PushNotifications, platform);
        await PushNotifications.register();
        fcmInitialized = true;
        debug.log('[HamiFcmBridge] FCM register invoked');
    } catch (error) {
        debug.warn('[HamiFcmBridge] init failed:', error);
    }
}

import { useCallback, useEffect } from 'react';
import type { CalendarEvent } from '@/app/services/cloud/lawyerCalendarTypes';
import { CALENDAR_UPDATED_EVENT } from '@/app/services/calendarBridge.types';
import { getCachedCalendarEvents } from '@/app/services/calendar/calendarEventsCache';
import { peekLocalCalendarSnapshotSync } from '@/app/services/calendar/calendarLocalSnapshot';
import { buildCalendarNativeSchedules, buildCalendarSnoozeNativeSchedules } from '@/app/services/notifications/native/calendarNativeReminderScheduler';
import {
    initializeHamiNotificationBridge,
    syncNativeScheduledNotifications,
} from '@/app/services/notifications/HamiNotificationBridge';
import {
    HAMI_CALENDAR_NATIVE_SYNC_EVENT,
    readCalendarReminderSnoozes,
} from '@/app/services/calendar/calendarReminderSnoozeStore';
import { useVisibilityAwareInterval } from '@/app/hooks/useVisibilityAwareInterval';

function loadCalendarEvents(userId: string): CalendarEvent[] {
    const cached = getCachedCalendarEvents(userId);
    const list = cached ?? peekLocalCalendarSnapshotSync(userId);
    return Array.isArray(list) ? list : [];
}

const NATIVE_REMINDER_RESYNC_MS = 5 * 60_000;

/** يجدول تذكيرات التقويم على النظام — يعمل والتطبيق مغلق. إعادة المزامنة من JS تتوقف في الخلفية. */
export function useCalendarNativeReminderSync(userId: string, enabled: boolean): void {
    const sync = useCallback(async () => {
        if (!enabled || !userId) return;
        await initializeHamiNotificationBridge();
        const events = loadCalendarEvents(userId);
        const snoozes = readCalendarReminderSnoozes();
        const schedules = [
            ...buildCalendarNativeSchedules(events),
            ...buildCalendarSnoozeNativeSchedules(snoozes),
        ];
        await syncNativeScheduledNotifications(schedules);
    }, [enabled, userId]);

    useEffect(() => {
        if (!enabled || !userId) return;

        let cancelled = false;
        void sync().then(() => {
            if (cancelled) return;
        });

        const onCalendarUpdated = () => {
            void sync();
        };

        window.addEventListener(CALENDAR_UPDATED_EVENT, onCalendarUpdated);
        window.addEventListener('hami:settings-updated', onCalendarUpdated);
        window.addEventListener(HAMI_CALENDAR_NATIVE_SYNC_EVENT, onCalendarUpdated);

        return () => {
            cancelled = true;
            window.removeEventListener(CALENDAR_UPDATED_EVENT, onCalendarUpdated);
            window.removeEventListener('hami:settings-updated', onCalendarUpdated);
            window.removeEventListener(HAMI_CALENDAR_NATIVE_SYNC_EVENT, onCalendarUpdated);
        };
    }, [enabled, userId, sync]);

    useVisibilityAwareInterval(() => {
        void sync();
    }, NATIVE_REMINDER_RESYNC_MS, enabled && Boolean(userId));
}

