import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';

export type GeolocationPickResult = {
    latitude: number;
    longitude: number;
    label: string;
};

function geolocationErrorMessage(code: number): string {
    switch (code) {
        case 1:
            return 'تم رفض صلاحية الموقع — فعّلها من إعدادات التطبيق';
        case 2:
            return 'الموقع غير متاح حالياً — جرّب مرة أخرى أو أدخل العنوان يدوياً';
        case 3:
            return 'انتهت مهلة تحديد الموقع — تحقق من GPS أو أدخل العنوان يدوياً';
        default:
            return 'تعذر تحديد الموقع — تحقق من صلاحية الموقع أو أدخل العنوان يدوياً';
    }
}

function formatPick(latitude: number, longitude: number): GeolocationPickResult {
    return {
        latitude,
        longitude,
        label: `${latitude.toFixed(6)},${longitude.toFixed(6)}`,
    };
}

async function ensureCapacitorLocationPermission(): Promise<boolean> {
    const { Geolocation } = await import('@capacitor/geolocation');
    const current = await Geolocation.checkPermissions();
    if (current.location === 'granted' || current.location === 'limited') return true;
    const requested = await Geolocation.requestPermissions();
    return requested.location === 'granted' || requested.location === 'limited';
}

async function requestCapacitorLocationLabel(): Promise<GeolocationPickResult | null> {
    if (!isCapacitorNativePlatform()) return null;
    try {
        const granted = await ensureCapacitorLocationPermission();
        if (!granted) {
            throw Object.assign(new Error('denied'), { code: 1 });
        }
        const { Geolocation } = await import('@capacitor/geolocation');
        const pos = await Geolocation.getCurrentPosition({
            enableHighAccuracy: true,
            timeout: 10_000,
            maximumAge: 60_000,
        });
        return formatPick(pos.coords.latitude, pos.coords.longitude);
    } catch (err) {
        if (typeof err === 'object' && err !== null && 'code' in err) {
            throw err;
        }
        return null;
    }
}

export function requestCurrentLocationLabel(): Promise<GeolocationPickResult> {
    return new Promise((resolve, reject) => {
        void (async () => {
            try {
                const native = await requestCapacitorLocationLabel();
                if (native) {
                    resolve(native);
                    return;
                }
            } catch (err) {
                reject(err);
                return;
            }

            if (typeof navigator === 'undefined' || !navigator.geolocation) {
                reject(new Error('unsupported'));
                return;
            }

            if (typeof window !== 'undefined' && !window.isSecureContext) {
                reject(new Error('insecure'));
                return;
            }

            const onSuccess = (pos: GeolocationPosition) => {
                resolve(formatPick(pos.coords.latitude, pos.coords.longitude));
            };

            const nativeTimeout = isCapacitorNativePlatform() ? 10_000 : 14_000;
            const fallbackTimeout = isCapacitorNativePlatform() ? 12_000 : 20_000;

            const tryGet = (highAccuracy: boolean) => {
                navigator.geolocation.getCurrentPosition(
                    onSuccess,
                    (err) => {
                        if (highAccuracy && (err.code === 2 || err.code === 3)) {
                            tryGet(false);
                            return;
                        }
                        reject(err);
                    },
                    {
                        enableHighAccuracy: highAccuracy,
                        timeout: highAccuracy ? nativeTimeout : fallbackTimeout,
                        maximumAge: 120_000,
                    },
                );
            };

            tryGet(true);
        })();
    });
}

/** يختار موقعاً للملف — بدون toast (طبقة خدمة نقية؛ الواجهة تعلن الأخطاء) */
export async function pickCurrentLocationForProfile(): Promise<string | null> {
    const picked = await requestCurrentLocationLabel();
    return picked.label;
}

export function messageForGeolocationFailure(err: unknown): string {
    if (err instanceof Error && err.message === 'unsupported') {
        return 'المتصفح لا يدعم تحديد الموقع — أدخل الإحداثيات أو العنوان يدوياً';
    }
    if (err instanceof Error && err.message === 'insecure') {
        return 'تحديد الموقع يتطلب اتصالاً آمناً (HTTPS)';
    }
    if (typeof err === 'object' && err !== null && 'code' in err) {
        return geolocationErrorMessage(Number((err as GeolocationPositionError).code));
    }
    return 'تعذر تحديد الموقع — تحقق من صلاحية الموقع أو أدخل العنوان يدوياً';
}

/**
 * فتح/إغلاق الملف المهني لحظياً.
 * المصدر الوحيد للحقيقة البصرية: html[data-hami-profile-open]
 * أثناء الإغلاق: html[data-hami-profile-closing] يفرض إخفاء السطح حتى لو
 * React مسح inline styles وأبقى --active (سبب الشاشة السوداء + الهيدر).
 * React يُزامَن بـ flushSync في مسار الفتح/الإغلاق — بلا rAF معلّق.
 * التقويم يلغي إطاراً معلّقاً برمز جيل لأن Hostه قد لا يكون في DOM بعد.
 */

import { wasProfileOpenedThisPage } from '@/app/hooks/lawyerDashboard/profile/profileOpenSession';
import { isViteE2eHooksEnabled } from '@/app/utils/viteE2eHooks';

const PROFILE_SURFACE = '[data-testid="lawyer-dashboard-profile-surface"]';
const OPEN_ATTR = 'data-hami-profile-open';
const CLOSING_ATTR = 'data-hami-profile-closing';

function recordE2eSnapClose(blocked: boolean): void {
    if (!isViteE2eHooksEnabled() || typeof window === 'undefined') return;
    const w = window as Window & {
        __hamiE2eLastProfileSnapClose?: {
            blocked: boolean;
            at: number;
            stack: string;
        };
    };
    w.__hamiE2eLastProfileSnapClose = {
        blocked,
        at: Date.now(),
        stack: new Error().stack?.split('\n').slice(0, 14).join('\n') ?? '',
    };
}

export function isProfileShellSnappedOpen(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.getAttribute(OPEN_ATTR) === '1';
}

export function isProfileShellClosing(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.getAttribute(CLOSING_ATTR) === '1';
}

export function clearProfileShellClosing(): void {
    if (typeof document === 'undefined') return;
    document.documentElement.removeAttribute(CLOSING_ATTR);
}

/**
 * يضع علم الفتح فوراً حتى بلا سطح مركّب —
 * يخفي غطاء الرئيسية والهيدر بالـ CSS قبل اكتمال React/chunk.
 * @returns true إذا وُجد سطح الملف في DOM
 */
export function snapProfileShellOpen(): boolean {
    if (typeof document === 'undefined') return false;
    clearProfileShellClosing();
    document.documentElement.setAttribute(OPEN_ATTR, '1');
    const surface = document.querySelector(PROFILE_SURFACE);
    return surface instanceof HTMLElement;
}

export function snapProfileShellClose(): void {
    if (typeof document === 'undefined') return;
    /* جلسة فتح قائمة: لا تمسح snap من مسار جانبي (إعادة تركيب اللوحة / إغلاق دعاوى).
     * الإغلاق المقصود يصفّر النية أولاً (runProfileClosePaint / returnToLawyerHome). */
    if (wasProfileOpenedThisPage()) {
        recordE2eSnapClose(true);
        return;
    }
    const wasOpen = document.documentElement.getAttribute(OPEN_ATTR) === '1';
    recordE2eSnapClose(false);
    document.documentElement.removeAttribute(OPEN_ATTR);
    /* حزمة E2E تتخطى التلاشي — closing العالق كان يبقي z-index 200 فوق الرئيسية */
    const skipClosingFade =
        import.meta.env.VITE_E2E === '1' || import.meta.env.VITE_E2E === 'true';
    if (wasOpen && !skipClosingFade) {
        document.documentElement.setAttribute(CLOSING_ATTR, '1');
    }
}

/** للاختبارات */
export function resetProfileShellSnapForTests(): void {
    if (typeof document !== 'undefined') {
        document.documentElement.removeAttribute(OPEN_ATTR);
        document.documentElement.removeAttribute(CLOSING_ATTR);
    }
}

