    exactScanGlobalSearchHits,
    getGlobalSearchFuseDocs,
    getOrCreateGlobalSearchFuse,
    invalidateGlobalSearchFuseCache,
    mergeSearchHitLists,
    rankGlobalSearchHits,
} from '@/app/services/globalSearchFuse';
