function doc(overrides: Partial<SmartVaultDoc>): SmartVaultDoc {
    return {
        id: 'v1',
        title: 'عقد إيجار',
        type: 'pdf',
        tags: ['عقود'],
        authorId: 'u1',
        createdAt: 't',
