import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { djb2Hash } from '@/app/utils/djb2';

const MAX_FILE_SLICES = 2_500;

type FileSlice = {
    sig: string;
    entries: GlobalSearchEntry[];
};

const fileSliceCache = new Map<string, FileSlice>();

/** هاش لمحتوى الأطراف — يلتقط تعديل الاسم/الهاتف/الدور (مصدر عنوان النتيجة) */
function partiesContentHash(parties: FileData['parties']): number {
    if (!Array.isArray(parties) || parties.length === 0) return 0;
    const blob = parties
        .map((p) => `${p.id ?? ''}:${p.name ?? ''}:${p.phone ?? ''}:${p.role ?? ''}:${p.isClient ? 1 : 0}`)
        .join('|');
    return djb2Hash(blob);
}

/** هاش لنصوص ملاحظات الملف */
function notesContentHash(notes: FileData['notes']): number {
    if (!Array.isArray(notes) || notes.length === 0) return 0;
    return djb2Hash(notes.map((n) => `${n.id ?? ''}:${n.text ?? ''}`).join('|'));
}

/** هاش لعناوين/تفاصيل المهام */
function tasksContentHash(tasks: FileData['tasks']): number {
    if (!Array.isArray(tasks) || tasks.length === 0) return 0;
    return djb2Hash(
        tasks
            .map((t) => {
                const rec = t as { id?: unknown; title?: unknown; text?: unknown; details?: unknown };
                return `${String(rec.id ?? '')}:${String(rec.title ?? rec.text ?? '')}:${String(rec.details ?? '')}`;
            })
            .join('|'),
    );
}

/** هاش مضغوط لمحتوى المراحل (timeline / tasks / incidentals) — يلتقط تعديل الأحداث */
function stagesContentHash(stagesRaw: unknown): number {
    if (!Array.isArray(stagesRaw) || stagesRaw.length === 0) return 0;
    const parts: string[] = [];
    for (const stageRaw of stagesRaw) {
        if (!stageRaw || typeof stageRaw !== 'object') continue;
        const stage = stageRaw as Record<string, unknown>;
        parts.push(String(stage.id ?? ''), String(stage.stageName ?? stage.name ?? ''));
        const timeline = Array.isArray(stage.timeline) ? stage.timeline : [];
        for (const evRaw of timeline) {
            if (!evRaw || typeof evRaw !== 'object') continue;
            const ev = evRaw as Record<string, unknown>;
            parts.push(
                `e${String(ev.id ?? '')}:${String(ev.title ?? '')}:${String(ev.details ?? '')}:${ev.isDeleted ? 1 : 0}`,
            );
        }
        const stageTasks = Array.isArray(stage.tasks) ? stage.tasks : [];
        for (const tRaw of stageTasks) {
            if (!tRaw || typeof tRaw !== 'object') continue;
            const t = tRaw as Record<string, unknown>;
            parts.push(`t${String(t.id ?? '')}:${String(t.title ?? '')}`);
        }
        const incidentals = Array.isArray(stage.incidentalCases) ? stage.incidentalCases : [];
        for (const iRaw of incidentals) {
            if (!iRaw || typeof iRaw !== 'object') continue;
            const i = iRaw as Record<string, unknown>;
            parts.push(`i${String(i.id ?? '')}:${String(i.title ?? i.subject ?? '')}`);
        }
    }
    return djb2Hash(parts.join('|'));
}

export function fileSearchIndexSignature(f: FileData & { executionTrashDeletedAt?: string | null }): string {
    const id = String(f.id);
    const stagesRaw = (f as unknown as { stages?: unknown }).stages;
    return [
        id,
        f.type ?? '',
        f.status ?? '',
        f.caseNo ?? '',
        f.court ?? '',
        f.docType ?? '',
        f.judge ?? '',
        f.executionTrashDeletedAt ?? '',
        partiesContentHash(f.parties),
        notesContentHash(f.notes),
        tasksContentHash(f.tasks),
        stagesContentHash(stagesRaw),
    ].join('|');
}

export function getCachedFileSearchEntries(
    f: FileData & { executionTrashDeletedAt?: string | null },
): GlobalSearchEntry[] | null {
    const hit = fileSliceCache.get(String(f.id));
    if (!hit) return null;
    if (hit.sig !== fileSearchIndexSignature(f)) return null;
    return hit.entries;
}

export function rememberFileSearchEntries(
    f: FileData & { executionTrashDeletedAt?: string | null },
    entries: GlobalSearchEntry[],
): void {
    const id = String(f.id);
    fileSliceCache.set(id, { sig: fileSearchIndexSignature(f), entries });
    while (fileSliceCache.size > MAX_FILE_SLICES) {
        const oldest = fileSliceCache.keys().next().value;
        if (oldest === undefined) break;
        fileSliceCache.delete(oldest);
    }
}

export function invalidateFileSearchSliceCache(fileId?: string): void {
    if (fileId) {
        fileSliceCache.delete(String(fileId));
        return;
    }
    fileSliceCache.clear();
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { resolveFileSearchLifecycle } from '@/app/services/searchLifecycle';
import type { GlobalSearchCategory, GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import {
    clipSearchHaystack,
    norm,
    noteTexts,
    partyNames,
    withLifecycle,
} from '@/app/services/search/globalSearchIndexPureHelpers';
import { fileTasksSearchHaystack } from '@/app/services/search/globalSearchIndexFileTasks';
import { lawsuitStagesSearchHaystack } from '@/app/services/search/globalSearchIndexLawsuitStages';

export function fileToEntry(f: FileData & { executionTrashDeletedAt?: string | null }): GlobalSearchEntry[] {
    const lifecycle = resolveFileSearchLifecycle(f);
    const cat: GlobalSearchCategory =
        f.type === 'execution' ? 'execution' : f.type === 'transaction' ? 'transaction' : 'lawsuit';
    const client = f.parties?.find((p) => p.isClient)?.name || f.parties?.[0]?.name || '';
    const jurisdictionHint =
        f.lawsuitJurisdiction === 'personal'
            ? 'أحوال شخصية قضاء أحوال personal status'
            : f.lawsuitJurisdiction === 'civil'
              ? 'قضاء مدني civil'
              : '';
    const applicableLaw = String(
        (f as { applicableLaw?: string }).applicableLaw ??
            (f as { personalApplicableLaw?: string }).personalApplicableLaw ??
            '',
    ).trim();
    const searchBlob = clipSearchHaystack(
        [
            f.caseNo,
            f.court,
            f.docType,
            f.judge,
            client,
            partyNames(f.parties),
            noteTexts(f.notes),
            fileTasksSearchHaystack(f),
            f.type === 'execution' ? '' : lawsuitStagesSearchHaystack(f),
            jurisdictionHint,
            applicableLaw,
        ]
            .filter(Boolean)
            .join(' '),
    );

    const jurisdictionSubtitle =
        f.lawsuitJurisdiction === 'personal'
            ? 'أحوال شخصية'
            : f.lawsuitJurisdiction === 'civil'
              ? 'قضاء مدني'
              : null;

    return [
        withLifecycle(
            {
                id: `file-${f.id}`,
                category: cat,
                title:
                    f.type === 'transaction'
                        ? client || f.caseNo || 'معاملة'
                        : f.parties?.find((p) => p.isClient)?.name || f.caseNo || 'ملف',
                subtitle:
                    f.type === 'transaction'
                        ? f.caseNo
                            ? `إضبارة · ${f.caseNo}`
                            : 'إضبارة'
                        : jurisdictionSubtitle
                          ? `${jurisdictionSubtitle} • ${f.court} • ${f.caseNo}`
                          : `${f.court} • ${f.caseNo}`,
                _searchStr: norm(searchBlob),
                navigate: { type: 'file', fileId: f.id },
            },
            lifecycle,
        ),
    ];
}

import type { FileData, Task } from '@/app/components/lawyer/LawyerShared';

/** عناوين مهام الملف داخل وثيقة الملف — بلا وثيقة Fuse لكل مهمة. */
export function fileTasksSearchHaystack(f: FileData): string {
    const parts: string[] = [];
    for (const t of f.tasks ?? []) {
        const title = (t as Task).title?.trim() || (t as { text?: string }).text?.trim();
        if (title) parts.push(title);
        const details = (t as Task).details?.trim();
        if (details) parts.push(details);
    }
    return parts.join(' ');
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { sanitizeSearchDisplayText } from '@/app/services/search/searchDisplayText';

const STAGES_HAYSTACK_MAX = 4_000;

/** نصوص المراحل للبحث داخل وثيقة الملف — بلا وثيقة Fuse لكل حدث. */
export function lawsuitStagesSearchHaystack(f: FileData): string {
    const parts: string[] = [];
    const stagesRaw = (f as unknown as Record<string, unknown>).stages;
    const stages = Array.isArray(stagesRaw) ? stagesRaw : [];

    for (const stageRaw of stages) {
        if (!stageRaw || typeof stageRaw !== 'object') continue;
        const stage = stageRaw as Record<string, unknown>;
        const stageName = String(stage.stageName ?? stage.name ?? '').trim();
        if (stageName) parts.push(stageName);

        const timeline = Array.isArray(stage.timeline) ? stage.timeline : [];
        for (const evRaw of timeline) {
            if (!evRaw || typeof evRaw !== 'object') continue;
            const ev = evRaw as Record<string, unknown>;
            if (ev.isDeleted) continue;
            const title = sanitizeSearchDisplayText(String(ev.title ?? '').trim());
            const details = sanitizeSearchDisplayText(String(ev.details ?? '').trim());
            const tagsStr = Array.isArray(ev.tags) ? (ev.tags as unknown[]).join(' ') : '';
            parts.push(title, details, String(ev.type ?? ''), String(ev.subType ?? ''), tagsStr);
        }

        const stageTasks = Array.isArray(stage.tasks) ? stage.tasks : [];
        for (const tRaw of stageTasks) {
            if (!tRaw || typeof tRaw !== 'object') continue;
            const t = tRaw as Record<string, unknown>;
            parts.push(
                sanitizeSearchDisplayText(String(t.title ?? '').trim()),
                sanitizeSearchDisplayText(String(t.details ?? '').trim()),
            );
        }

        const incidentals = Array.isArray(stage.incidentalCases) ? stage.incidentalCases : [];
        for (const iRaw of incidentals) {
            if (!iRaw || typeof iRaw !== 'object') continue;
            const i = iRaw as Record<string, unknown>;
            parts.push(
                sanitizeSearchDisplayText(String(i.title ?? i.subject ?? '').trim()),
                sanitizeSearchDisplayText(String(i.details ?? '').trim()),
                String(i.type ?? ''),
            );
        }
    }

    const joined = parts.filter(Boolean).join(' ');
    return joined.length > STAGES_HAYSTACK_MAX ? joined.slice(0, STAGES_HAYSTACK_MAX) : joined;
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { SearchLifecycle } from '@/app/services/searchLifecycle';
import type { BuildGlobalSearchIndexInput, GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import {
    getCachedFileSearchEntries,
    rememberFileSearchEntries,
} from '@/app/services/search/globalSearchFileSliceCache';
import { caseToEntry } from '@/app/services/search/globalSearchIndexCaseEntries';
import { criminalToEntry } from '@/app/services/search/globalSearchIndexCriminalEntries';
import {
    calendarToEntry,
    communityPostToEntries,
    notificationToEntry,
    quantumTaskToEntry,
    threadingTaskToEntry,
    threadingTxToEntry,
    urgentToEntry,
} from '@/app/services/search/globalSearchIndexExtrasEntries';
import { fileToEntry } from '@/app/services/search/globalSearchIndexFileEntries';
import { lawsuitLifecycleIndexToSearchEntries } from '@/app/services/search/globalSearchIndexLawsuitLifecycleEntries';
import { blob, isSearchEntryVisible, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';
import {
    docsVaultEntriesFromPrepared,
    noteRowToEntry,
    repositoryToEntry,
    vaultToEntry,
} from '@/app/services/search/globalSearchIndexVaultEntries';

const LIFECYCLE_ACTIVE: SearchLifecycle = 'active';

/** فهرس موحّد — Worker-safe (بيانات JSON جاهزة من الخيط الرئيسي) */
export function buildGlobalSearchIndex(input: BuildGlobalSearchIndexInput): GlobalSearchEntry[] {
    const seen = new Set<string>();
    const list: GlobalSearchEntry[] = [];
    const fileLifecycleById = new Map<string, SearchLifecycle>();

    const push = (e: GlobalSearchEntry) => {
        if (!isSearchEntryVisible(e)) return;
        if (seen.has(e.id)) return;
        seen.add(e.id);
        list.push(e);
    };

    /** metadata من lifecycleIndex — يُسمح بـ deleted للوصول إلى المهملات غير المحمّلة */
    const pushLifecycleIndexEntry = (e: GlobalSearchEntry) => {
        if (seen.has(e.id)) return;
        seen.add(e.id);
        list.push(e);
    };

    const indexFile = (f: FileData & { executionTrashDeletedAt?: string | null }) => {
        const cached = getCachedFileSearchEntries(f);
        const entries = cached ?? fileToEntry(f);
        if (!cached) rememberFileSearchEntries(f, entries);
        if (entries.length > 0) {
            fileLifecycleById.set(String(f.id), entries[0].lifecycle);
        }
        for (const entry of entries) {
            push(entry);
        }
    };

    for (const f of input.files) {
        indexFile(f);
    }

    const indexedLawsuitIds = new Set<string>();
    for (const f of input.files) indexedLawsuitIds.add(String(f.id));
    for (const entry of lawsuitLifecycleIndexToSearchEntries(
        input.lawsuitLifecycleIndex,
        indexedLawsuitIds,
    )) {
        pushLifecycleIndexEntry(entry);
    }

    for (const f of input.executionFiles ?? []) {
        indexFile({ ...f, type: 'execution' });
    }

    for (const entry of input.preparedExecutionDeepEntries ?? []) {
        push(entry);
    }

    const fileIds = new Set<string>();
    for (const f of input.files) fileIds.add(String(f.id));
    for (const f of input.executionFiles ?? []) fileIds.add(String(f.id));

    for (const c of input.cases) {
        if (!fileIds.has(c.id)) caseToEntry(c).forEach(push);
    }

    for (const c of input.criminalCases ?? []) {
        criminalToEntry(c).forEach(push);
    }

    const seenNoteIds = new Set<string>();
    const preparedVaultNotes = input.preparedVaultNotes ?? [];
    const preparedStoredNotes = input.preparedStoredNotes ?? [];
    const preparedDocsVault = input.preparedDocsVault ?? [];

    for (const n of preparedVaultNotes) {
        seenNoteIds.add(String(n.id));
        const isVoice = n.type === 'voice';
        push(
            withLifecycle(
                {
                    id: `nv-${n.id}`,
                    category: isVoice ? 'voice' : 'note',
                    title: isVoice ? 'تسجيل صوتي' : n.content.slice(0, 80) || 'ملاحظة',
                    subtitle: isVoice ? 'مفكرة — صوت' : 'مفكرة الملاحظات',
                    snippet: isVoice ? undefined : n.content,
                    _searchStr: blob([n.content, isVoice ? 'صوت' : '']),
                    navigate: isVoice
                        ? { type: 'voice', noteId: String(n.id) }
                        : { type: 'note', noteId: String(n.id) },
                },
                LIFECYCLE_ACTIVE,
            ),
        );
    }

    for (const n of input.globalNotes) {
        if (seenNoteIds.has(String(n.id))) continue;
        seenNoteIds.add(String(n.id));
        push(noteRowToEntry(n, 'المفكرة العامة'));
    }

    for (const n of preparedStoredNotes) {
        if (seenNoteIds.has(String(n.id))) continue;
        seenNoteIds.add(String(n.id));
        push(noteRowToEntry(n, 'ملاحظات المحامي'));
    }

    docsVaultEntriesFromPrepared(preparedDocsVault, fileLifecycleById).forEach(push);

    for (const n of input.notifications ?? []) {
        if (n.title?.trim() || n.message?.trim()) push(notificationToEntry(n));
    }

    const extras = input.extras;
    if (extras) {
        extras.vaultDocs.forEach((d) => push(vaultToEntry(d)));
        extras.repositoryDocs.forEach((d) => push(repositoryToEntry(d)));
        extras.quantumTasks.forEach((t) => push(quantumTaskToEntry(t, fileLifecycleById)));
        extras.calendarEvents.forEach((e) => push(calendarToEntry(e, fileLifecycleById)));
        extras.urgentCases.forEach((c, i) => urgentToEntry(c, i).forEach(push));

        const txById = new Map(extras.threadingTransactions.map((t) => [t.id, t]));
        extras.threadingTransactions.forEach((tx) => push(threadingTxToEntry(tx)));
        for (const t of extras.threadingTasks) {
            const tx = txById.get(t.transactionId);
            push(threadingTaskToEntry(t, tx?.clientName || tx?.title || 'معاملة', t.transactionId));
        }
        extras.communityPosts.forEach((p) => communityPostToEntries(p).forEach(push));
    }

    if (input.profileLine?.trim()) {
        push(
            withLifecycle(
                {
                    id: 'profile-self',
                    category: 'profile',
                    title: 'الملف الشخصي',
                    subtitle: input.profileLine.trim(),
                    _searchStr: norm(input.profileLine),
                    navigate: { type: 'profile' },
                },
                LIFECYCLE_ACTIVE,
            ),
        );
    }

    return list;
}

import type { FileData, Party } from '@/app/components/lawyer/LawyerShared';
import { normalizeArabicSearch } from '@/app/services/search/normalizeArabicSearch';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import type { SearchLifecycle } from '@/app/services/searchLifecycle';

export function withLifecycle(
    entry: Omit<GlobalSearchEntry, 'lifecycle'>,
    lifecycle: SearchLifecycle,
): GlobalSearchEntry {
    return { ...entry, lifecycle };
}

export function isSearchEntryVisible(entry: Pick<GlobalSearchEntry, 'lifecycle'>): boolean {
    return entry.lifecycle !== 'deleted';
}

export function norm(text: string): string {
    return normalizeArabicSearch(text).toLowerCase();
}

export function blob(parts: (string | undefined | null)[]): string {
    return norm(parts.filter(Boolean).join(' '));
}

const FILE_SEARCH_HAYSTACK_MAX = 8_000;

export function clipSearchHaystack(text: string, max = FILE_SEARCH_HAYSTACK_MAX): string {
    if (text.length <= max) return text;
    return text.slice(0, max);
}

export function partyNames(parties: Party[] | undefined): string {
    return (parties ?? []).map((p) => `${p.name || ''} ${p.phone || ''} ${p.role || ''}`).join(' ');
}

export function noteTexts(notes: FileData['notes'] | undefined): string {
    return (notes ?? []).map((n) => n.text || '').join(' ');
}

/** فتح/إغلاق البحث الشامل لحظياً — علم على html */
import { purgeStaticBootShellAfterBoot } from '@/app/bootstrap/bootStaticShell';

const ATTR = 'data-hami-global-search-open';
const CLOSING_ATTR = 'data-hami-global-search-closing';

export function isGlobalSearchShellSnappedOpen(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.getAttribute(ATTR) === '1';
}

export function snapGlobalSearchShellOpen(): void {
    if (typeof document === 'undefined') return;
    purgeStaticBootShellAfterBoot();
    document.documentElement.removeAttribute(CLOSING_ATTR);
    document.documentElement.setAttribute(ATTR, '1');
}

export function snapGlobalSearchShellClose(): void {
    if (typeof document === 'undefined') return;
    document.documentElement.removeAttribute(CLOSING_ATTR);
    document.documentElement.removeAttribute(ATTR);
}

import {
    clearNativeBiometricEnrollment,
    hasNativeBiometricEnrollment,
} from '@/app/runtime/nativeBiometricEnrollmentStore';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import {
    clearStoredBiometricCredential,
    hasStoredBiometricCredential,
    isWebAuthnLockSupported,
    registerBiometricCredential,
    verifyBiometricUnlock,
} from '@/app/services/security/webAuthnLock';
import {
    clearBiometricWorkspaceUnlock,
    markBiometricWorkspaceUnlocked,
} from '@/app/services/security/biometricWorkspaceGate';

export type BiometricChannel = 'native' | 'web' | 'none';

export type BiometricSessionAvailability = {
    channel: BiometricChannel;
    pluginLoaded: boolean;
    hardwareAvailable: boolean;
    enrolled: boolean;
};

export type BiometricEnrollOutcome =
    | { status: 'enrolled' }
    | { status: 'cancelled' }
    | { status: 'unavailable' }
    | { status: 'failed' };

function loadNativeBiometricBridge() {
    return import('@/app/runtime/nativeBiometricBridge');
}

function resolveChannel(): BiometricChannel {
    if (isCapacitorNativePlatform()) return 'native';
    if (isWebAuthnLockSupported()) return 'web';
    return 'none';
}

export function hasBiometricSessionEnrollment(): boolean {
    return hasNativeBiometricEnrollment() || (isWebAuthnLockSupported() && hasStoredBiometricCredential());
}

export async function probeBiometricSession(): Promise<BiometricSessionAvailability> {
    const channel = resolveChannel();

    if (channel === 'native') {
        const { probeNativeBiometricAvailability } = await loadNativeBiometricBridge();
        const probe = await probeNativeBiometricAvailability();
        return {
            channel: 'native',
            pluginLoaded: probe.pluginLoaded,
            hardwareAvailable: probe.hardwareAvailable,
            enrolled: hasNativeBiometricEnrollment(),
        };
    }

    if (channel === 'web') {
        return {
            channel: 'web',
            pluginLoaded: true,
            hardwareAvailable: isWebAuthnLockSupported(),
            enrolled: hasStoredBiometricCredential(),
        };
    }

    return {
        channel: 'none',
        pluginLoaded: false,
        hardwareAvailable: false,
        enrolled: false,
    };
}

export function resolveBiometricSessionHint(
    availability: BiometricSessionAvailability,
    lockEnabled: boolean,
): string {
    if (availability.channel === 'native') {
        if (!availability.pluginLoaded) {
            return 'ميزة القفل غير متاحة في هذا التثبيت — حدّث التطبيق أو أعد تثبيته';
        }
        if (!availability.hardwareAvailable) {
            return 'سجّل بصمة أو Face ID في إعدادات الهاتف أولاً، ثم أعد المحاولة';
        }
        return lockEnabled
            ? 'مفعّل — يُقفل عند فتح المكتب، والعودة من الخلفية، وبعد الخمول'
            : 'جاهز — اضغط المفتاح وتحقق ببصمتك';
    }

    if (availability.channel === 'web') {
        return lockEnabled ? 'مفعّل عبر WebAuthn على المتصفح' : '';
    }

    if (!lockEnabled) return '';
    return 'يتطلب HTTPS وجهازاً يدعم البصمة — أو تطبيق Android/iOS';
}

export async function enrollBiometricSessionLock(): Promise<BiometricEnrollOutcome> {
    const channel = resolveChannel();

    if (channel === 'native') {
        const { registerNativeBiometric } = await loadNativeBiometricBridge();
        const nativeRegistered = await registerNativeBiometric();
        if (nativeRegistered === true) {
            markBiometricWorkspaceUnlocked();
            return { status: 'enrolled' };
        }
        if (nativeRegistered === false) return { status: 'cancelled' };
        return { status: 'unavailable' };
    }

    if (channel === 'web') {
        try {
            const registered = await registerBiometricCredential();
            if (registered) {
                markBiometricWorkspaceUnlocked();
                return { status: 'enrolled' };
            }
            return { status: 'failed' };
        } catch (err) {
            const { isBiometryUserCancelError } = await loadNativeBiometricBridge();
            if (isBiometryUserCancelError(err)) return { status: 'cancelled' };
            return { status: 'failed' };
        }
    }

    return { status: 'unavailable' };
}

/** null = لا قناة بيومترية — يُستخدم مسار التأكيد البديل */
export async function verifyBiometricSessionUnlock(): Promise<boolean | null> {
    if (hasNativeBiometricEnrollment()) {
        const { verifyNativeBiometricUnlock } = await loadNativeBiometricBridge();
        const nativeOk = await verifyNativeBiometricUnlock();
        if (nativeOk === true) return true;
        if (nativeOk === false) return false;
        return null;
    }

    if (isWebAuthnLockSupported() && hasStoredBiometricCredential()) {
        try {
            return await verifyBiometricUnlock();
        } catch {
            return false;
        }
    }

    return null;
}

export function clearBiometricSessionEnrollment(): void {
    clearStoredBiometricCredential();
    clearNativeBiometricEnrollment();
    clearBiometricWorkspaceUnlock();
    void loadNativeBiometricBridge()
        .then((m) => m.clearNativeBiometricOnDisable())
        .catch(() => undefined);
}

export function reconcileBiometricSessionLockEnabled(lockEnabled: boolean): 'ok' | 'reset' {
    if (!lockEnabled) return 'ok';
    if (hasBiometricSessionEnrollment()) return 'ok';
    clearBiometricSessionEnrollment();
    return 'reset';
}

