/** الواجهة تدعم الوضع الداكن فقط — يُحوَّل أي وضع فاتح/تلقائي محفوظ. */

function normalizeThemeMode(_mode: unknown): ThemeMode {

    return 'dark';

}



type LegacyFlat = Partial<{

    version: number;

    themeMode: AppSettingsState['appearance']['themeMode'];

    theme: ThemeKey;

    shape: ShapeKey;

    language: AppSettingsState['appearance']['language'];

    biometric: boolean;

    glassOpacity: number;

    wallpaper: string;

    fontSize: number;

    autoSave: boolean;

    cloudSync: boolean;

    privacyBlur: boolean;

    brandColor: string;

    appearance: AppSettingsState['appearance'];

    security: AppSettingsState['security'];

    data: AppSettingsState['data'];

    performance: AppSettingsState['performance'];

}>;



function deepMerge<T>(base: T, patch: Partial<T>): T {

    const out = { ...(base as unknown as Record<string, unknown>) };

    const patchObj = patch as unknown as Record<string, unknown>;

    for (const key of Object.keys(patchObj)) {

        const val = patchObj[key];

        if (val === undefined) continue;

        const baseVal = out[key];

        if (

            val &&

            typeof val === 'object' &&

            !Array.isArray(val) &&

            baseVal &&

            typeof baseVal === 'object' &&

            !Array.isArray(baseVal)

        ) {

            out[key] = deepMerge(baseVal as Record<string, unknown>, val as Record<string, unknown>);

        } else {

            out[key] = val;

        }

    }

    return out as unknown as T;

}



function normalizeAppSettings(merged: AppSettingsState): AppSettingsState {
    const themeTargets = collapseLegacyThemeApplyTarget(merged.appearance);

    return {
        version: SETTINGS_SCHEMA_VERSION,
        appearance: {
            ...merged.appearance,
            themeMode: normalizeThemeMode(merged.appearance.themeMode),
            language: normalizeAppearanceLanguage(merged.appearance.language),
            backgroundPreset: normalizeBackgroundPreset(merged.appearance.backgroundPreset),
            backgroundPatternOpacity: normalizeBackgroundPatternOpacity(merged.appearance.backgroundPatternOpacity),
            backgroundPatternBlur: normalizeAppearancePatternBlur(merged.appearance.backgroundPatternBlur),
            glassOpacity: normalizeGlassOpacity(merged.appearance.glassOpacity),
            homeContainerBorder: merged.appearance.homeContainerBorder !== false,
            themeApplyTarget: themeTargets.themeApplyTarget,
            patternApplyTarget: 'blocks',
            cardTheme: themeTargets.cardTheme,
            patternTheme: themeTargets.patternTheme,
            wallpaperStamp: merged.appearance.wallpaperStamp,
            fontSize: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontSize,
            fontPreset: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontPreset,
        },

        security: {

            ...merged.security,

            localOnlyMode: merged.security.localOnlyMode === true,
            privacyBlur: LAWYER_SETTINGS_V2_DEFAULTS.security.privacyBlur,

        },

        data: merged.security.localOnlyMode
            ? {
                  ...merged.data,
                  cloudSync: false,
                  syncNotes: false,
                  syncFiles: false,
                  syncExecution: false,
              }
            : { ...merged.data },

        performance: {
            ...merged.performance,
            litePerformance: normalizeLitePerformanceMode(merged.performance.litePerformance),
        },

        homeLayout: normalizeHomeLayout(merged.homeLayout),

        notifications: normalizeNotificationSettings(merged.notifications),

    };

}



/** Load v2 settings or migrate legacy `lawyer_settings` + theme keys. */

export function migrateLawyerSettings(

    raw: unknown,

    themeKey?: ThemeKey | null,

    shapeKey?: ShapeKey | null,

): AppSettingsState {

    if (raw && typeof raw === 'object') {

        const obj = raw as LegacyFlat & Record<string, unknown>;

        if (obj.version === SETTINGS_SCHEMA_VERSION && obj.appearance) {

            const merged = deepMerge(LAWYER_SETTINGS_V2_DEFAULTS, obj as unknown as Partial<AppSettingsState>);

            return normalizeAppSettings(merged);

        }

        if (obj.version === 2 && obj.appearance) {

            const merged = deepMerge(LAWYER_SETTINGS_V2_DEFAULTS, obj as unknown as Partial<AppSettingsState>);

            return normalizeAppSettings(merged);

        }



        const migrated: Partial<AppSettingsState> = {

            appearance: {

                ...LAWYER_SETTINGS_V2_DEFAULTS.appearance,

                themeMode: normalizeThemeMode(obj.themeMode ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.themeMode),

                theme: themeKey ?? obj.theme ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.theme,

                shape: shapeKey ?? obj.shape ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.shape,

                language: obj.language ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.language,

                fontSize: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontSize,
                fontPreset: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontPreset,

                glassOpacity: normalizeGlassOpacity(obj.glassOpacity ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.glassOpacity),

                wallpaper: obj.wallpaper,

                backgroundPreset: normalizeBackgroundPreset(

                    (obj.appearance as AppSettingsState['appearance'] | undefined)?.backgroundPreset,

                ),

                brandColor: obj.brandColor ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.brandColor,

            },

            security: {

                ...LAWYER_SETTINGS_V2_DEFAULTS.security,

                privacyBlur: LAWYER_SETTINGS_V2_DEFAULTS.security.privacyBlur,

                biometricLock: obj.biometric ?? LAWYER_SETTINGS_V2_DEFAULTS.security.biometricLock,

            },

            data: {

                ...LAWYER_SETTINGS_V2_DEFAULTS.data,

                autoSave: obj.autoSave ?? LAWYER_SETTINGS_V2_DEFAULTS.data.autoSave,

                cloudSync: obj.cloudSync ?? LAWYER_SETTINGS_V2_DEFAULTS.data.cloudSync,

            },

        };

        return normalizeAppSettings(deepMerge(LAWYER_SETTINGS_V2_DEFAULTS, migrated));

    }



    const base = { ...LAWYER_SETTINGS_V2_DEFAULTS };

    if (themeKey) base.appearance = { ...base.appearance, theme: themeKey };

    if (shapeKey) base.appearance = { ...base.appearance, shape: shapeKey };

    return base;

}

import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import type { ThemeKey, ShapeKey } from '@/app/types/common';
import { LAWYER_SETTINGS_V2_DEFAULTS } from './defaults';
import type { AppSettingsState } from './types';
import { SETTINGS_SCHEMA_VERSION } from './types';
import { normalizeLitePerformanceMode } from '@/app/runtime/devicePerformanceTier';
import { normalizeHomeLayout } from './homeLayout';
import { normalizeNotificationSettings } from './notificationSettings';
import { normalizeGlassOpacity } from './surfaceAppearance';
import { persistLocalOnlyBootFlag } from './localOnlyUrlPolicy';

let cached: AppSettingsState | null = null;
let cacheAt = 0;
let live: AppSettingsState | null = null;
let liveAt = 0;
const liveListeners = new Set<() => void>();

function notifyLawyerSettingsLiveListeners(): void {
    for (const listener of liveListeners) listener();
}

function ensureRuntimeListener(): void {
    if (typeof window === 'undefined') return;
    const w = window as unknown as { __hamiSettingsRuntimeInstalled?: boolean };
    if (w.__hamiSettingsRuntimeInstalled) return;
    w.__hamiSettingsRuntimeInstalled = true;
    window.addEventListener('hami:settings-updated', (evt) => {
        try {
            const next = (evt as CustomEvent).detail as unknown;
            if (!next || typeof next !== 'object') return;
            live = next as AppSettingsState;
            liveAt = Date.now();
            cached = live;
            cacheAt = liveAt;
            notifyLawyerSettingsLiveListeners();
        } catch {
            return;
        }
    });
}

export function invalidateLawyerSettingsCache(): void {
    cached = null;
    cacheAt = 0;
}

export function publishLawyerSettingsLive(next: AppSettingsState): void {
    live = next;
    liveAt = Date.now();
    cached = next;
    cacheAt = liveAt;
    notifyLawyerSettingsLiveListeners();
}

/** اشتراك React (useSyncExternalStore) — بلا TTL يعيد إنشاء المرجع */
export function subscribeLawyerSettingsLive(onStoreChange: () => void): () => void {
    ensureRuntimeListener();
    liveListeners.add(onStoreChange);
    return () => {
        liveListeners.delete(onStoreChange);
    };
}

/** مرجع مستقر طالما لم يُنشر تحديث — مناسب لـ useSyncExternalStore */
export function getLawyerSettingsStoreSnapshot(): AppSettingsState {
    ensureRuntimeListener();
    if (live) return live;
    if (cached) return cached;
    return getLawyerSettingsSnapshot();
}

function clampGlassOpacity(value: unknown): number {
    return normalizeGlassOpacity(value);
}

function clamp01(value: unknown, fallback: number): number {
    const n = typeof value === 'number' && Number.isFinite(value) ? value : fallback;
    return Math.min(1, Math.max(0, n));
}

/**
 * لقطة sync خفيفة بلا migrate / backgroundPresets / homeLayout —
 * المخطط الحالي يُدمَج سطحياً؛ الإرث يأخذ defaults + theme/shape حتى يكتمل migrate بعد paint.
 */
export function hydrateLawyerSettingsFast(
    raw: unknown,
    themeKey?: ThemeKey | null,
    shapeKey?: ShapeKey | null,
): AppSettingsState {
    if (raw && typeof raw === 'object') {
        const obj = raw as Partial<AppSettingsState> & Record<string, unknown>;
        if (obj.version === SETTINGS_SCHEMA_VERSION && obj.appearance) {
            const appearance = {
                ...LAWYER_SETTINGS_V2_DEFAULTS.appearance,
                ...obj.appearance,
                themeMode: 'dark' as const,
                theme: (themeKey ?? obj.appearance.theme ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.theme) as ThemeKey,
                shape: (shapeKey ?? obj.appearance.shape ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.shape) as ShapeKey,
                glassOpacity: clampGlassOpacity(obj.appearance.glassOpacity),
                backgroundPreset: obj.appearance.backgroundPreset ?? 'none',
                backgroundPatternOpacity: clamp01(
                    obj.appearance.backgroundPatternOpacity,
                    LAWYER_SETTINGS_V2_DEFAULTS.appearance.backgroundPatternOpacity,
                ),
                backgroundPatternBlur: clamp01(
                    obj.appearance.backgroundPatternBlur,
                    LAWYER_SETTINGS_V2_DEFAULTS.appearance.backgroundPatternBlur,
                ),
                homeContainerBorder: obj.appearance.homeContainerBorder !== false,
                wallpaper: undefined,
            };
            const localOnlyMode = obj.security?.localOnlyMode === true;
            if (localOnlyMode) persistLocalOnlyBootFlag(true);
            return {
                version: SETTINGS_SCHEMA_VERSION,
                appearance,
                security: {
                    ...LAWYER_SETTINGS_V2_DEFAULTS.security,
                    ...obj.security,
                    localOnlyMode,
                },
                data: { ...LAWYER_SETTINGS_V2_DEFAULTS.data, ...obj.data },
                performance: {
                    ...LAWYER_SETTINGS_V2_DEFAULTS.performance,
                    ...obj.performance,
                    litePerformance: normalizeLitePerformanceMode(obj.performance?.litePerformance),
                },
                homeLayout: normalizeHomeLayout(obj.homeLayout ?? LAWYER_SETTINGS_V2_DEFAULTS.homeLayout),
            notifications: normalizeNotificationSettings(obj.notifications),
            };
        }
    }

    const base: AppSettingsState = {
        ...LAWYER_SETTINGS_V2_DEFAULTS,
        appearance: { ...LAWYER_SETTINGS_V2_DEFAULTS.appearance },
    };
    if (themeKey) base.appearance = { ...base.appearance, theme: themeKey };
    if (shapeKey) base.appearance = { ...base.appearance, shape: shapeKey };
    return base;
}

/** Sync read for services/hooks outside React (short TTL cache). */
export function getLawyerSettingsSnapshot(): AppSettingsState {
    ensureRuntimeListener();
    const now = Date.now();
    if (live && now - liveAt < 60_000) return live;
    if (cached && now - cacheAt < 400) return cached;
    const raw = persistenceRepository.load('lawyer_settings');
    const theme = persistenceRepository.load<ThemeKey>('lawyer_theme');
    const shape = persistenceRepository.load<ShapeKey>('lawyer_shape');
    cached = hydrateLawyerSettingsFast(raw, theme, shape);
    cacheAt = now;
    return cached;
}

import { SmartDialog } from '@/app/components/ui/SmartDialog';
import { SmartToast } from '@/app/components/ui/SmartToast';
import {
    verifyBiometricSessionUnlock,
} from '@/app/services/security/biometricSessionService';
import { getLawyerSettingsSnapshot } from '@/app/services/settings/settingsSnapshot';

type VerifySensitiveSettingsOptions = {
    /** نص يُطلب كتابته حرفياً عند غياب البيومتري */
    confirmPhrase: string;
    promptMessage?: string;
    title?: string;
};

const CHALLENGE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

function randomChallengeToken(length = 4): string {
    if (typeof crypto === 'undefined' || typeof crypto.getRandomValues !== 'function') {
        throw new Error('[sensitive_gate:csprng_unavailable] csprng_unavailable');
    }
    const bytes = new Uint8Array(length);
    crypto.getRandomValues(bytes);
    let out = '';
    for (let i = 0; i < length; i += 1) {
        out += CHALLENGE_ALPHABET[bytes[i]! % CHALLENGE_ALPHABET.length]!;
    }
    return out;
}

function timingSafeEqualUtf8(left: string, right: string): boolean {
    const encoder = new TextEncoder();
    const a = encoder.encode(left);
    const b = encoder.encode(right);
    const len = Math.max(a.length, b.length);
    let diff = a.length ^ b.length;
    for (let i = 0; i < len; i += 1) {
        diff |= (a[i] ?? 0) ^ (b[i] ?? 0);
    }
    return diff === 0;
}

/**
 * يولّد عبارة تأكيد لمرة واحدة (أساس + رمز عشوائي) حتى لا تُخمَّن العبارة الثابتة
 * عند غياب البيومتري.
 */
export function mintSensitiveConfirmChallenge(basePhrase: string): {
    confirmPhrase: string;
    promptMessage: string;
} {
    const token = randomChallengeToken(4);
    const confirmPhrase = `${basePhrase.trim()}-${token}`;
    return {
        confirmPhrase,
        promptMessage: `اكتب «${confirmPhrase}» حرفياً للمتابعة:`,
    };
}

async function verifyWithBiometric(security: ReturnType<typeof getLawyerSettingsSnapshot>['security']): Promise<boolean | null> {
    if (!security.biometricLock) return null;

    const biometricOk = await verifyBiometricSessionUnlock();
    if (biometricOk === true) return true;
    if (biometricOk === false) {
        SmartToast.warning('تعذّر التحقق البيومتري — ألغِ العملية أو فعّل البصمة من جديد');
        return false;
    }

    return null;
}

/** تحقق إضافي قبل مسح/إعادة ضبط — بيومتري إن وُجد، وإلا عبارة تأكيد مكتوبة */
export async function verifySensitiveSettingsAction(options: VerifySensitiveSettingsOptions): Promise<boolean> {
    const { confirmPhrase, promptMessage, title } = options;
    const security = getLawyerSettingsSnapshot().security;

    const biometricResult = await verifyWithBiometric(security);
    if (biometricResult === true) return true;
    if (biometricResult === false) return false;

    const typed = await SmartDialog.prompt(
        promptMessage ?? `اكتب «${confirmPhrase}» للمتابعة:`,
        '',
        { title: title ?? 'تأكيد الهوية', confirmText: 'متابعة', cancelText: 'إلغاء' },
    );
    const normalized = typed?.trim() ?? '';
    if (!normalized) return false;
    if (!timingSafeEqualUtf8(normalized, confirmPhrase)) {
        SmartToast.warning('نص التأكيد غير صحيح');
        return false;
    }
    return true;
}

